#!/usr/bin/env node

import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from 'node:fs'
import { basename, dirname, relative, resolve } from 'node:path'
import { compileWorkspace } from './compiler.js'
import {
  diagnosticJson,
  isMainModule,
  usage,
  versionResult,
  type CliResult,
} from './cli-support.js'
import { runAskCommand } from './ask-command.js'
import { runCheckCommand } from './check-command.js'
import { runImportCommand } from './import-command.js'
import { runExportCommand } from './export-command.js'
import { runApplyCommand } from './apply-cli.js'
import { runDesignCommand } from './design-command.js'
import {
  evaluateEvidenceWorkspace,
  loadEvidence,
} from './evidence.js'
import { deriveArtifactCoverage } from './artifact-coverage.js'
import { deriveAttestationStaleness } from './attestation-staleness.js'
import { reconcileEvidenceReports } from './reconciliation.js'
import { reconciliationReportText } from './reconciliation-text.js'
import { loadWorkspaceManifest } from './workspace.js'

export type { CliResult } from './cli-support.js'

const runReconciliation = (
  options: readonly string[],
  cwd: string,
): CliResult => {
  // Bare reconcile already emits JSON, so --json changes nothing — but a
  // harness scripting "add --json to every verb" must not hit exit 2 on
  // the one verb that treats it as unknown (#275). Accepted as a no-op.
  // --text is the same report for a person (#526, ADR 0153); asking for
  // both shapes at once names no output, so it is refused like any other
  // malformed call.
  const text = options.includes('--text')
  const positional = options.filter(
    (option) => option !== '--json' && option !== '--text',
  )
  const [workspacePath] = positional
  if (
    positional.length !== 1 ||
    workspacePath === undefined ||
    workspacePath.startsWith('-') ||
    (text && options.includes('--json'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  try {
    const loadedWorkspace = loadWorkspaceManifest(
      {
        path: workspacePath,
        source: readFileSync(resolve(cwd, workspacePath), 'utf8'),
      },
      cwd,
    )
    if (!loadedWorkspace.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(loadedWorkspace.diagnostics),
        stderr: '',
      }
    }
    const sourcePaths = [
      ...loadedWorkspace.workspace.profiles,
      ...loadedWorkspace.workspace.patterns,
      ...loadedWorkspace.workspace.documents,
    ]
    const compilation = compileWorkspace(
      sourcePaths.map((path) => ({
        path,
        source: readFileSync(resolve(cwd, path), 'utf8'),
      })),
    )
    if (!compilation.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(compilation.diagnostics),
        stderr: '',
      }
    }
    const evidenceDocuments = []
    for (const path of loadedWorkspace.workspace.evidence) {
      const loaded = loadEvidence({
        path,
        source: readFileSync(resolve(cwd, path), 'utf8'),
      })
      if (!loaded.ok) {
        return {
          exitCode: 1,
          stdout: diagnosticJson(loaded.diagnostics),
          stderr: '',
        }
      }
      evidenceDocuments.push(loaded.evidence)
    }
    const evaluation = evaluateEvidenceWorkspace(
      compilation.graph,
      evidenceDocuments,
    )
    if (!evaluation.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(evaluation.diagnostics),
        stderr: '',
      }
    }
    // Attestation staleness derives from git (ADR 0074), so it belongs
    // to reconcile, the verb that reports observed reality; the design
    // evaluator and the check gate stay git-free.
    const documentIdByPath = new Map(
      compilation.graph.documents.map(({ id, source }) => [source, id]),
    )
    const staleness = deriveAttestationStaleness(
      cwd,
      loadedWorkspace.workspace.documents.map((path) => ({
        path,
        source: readFileSync(resolve(cwd, path), 'utf8'),
        documentId: documentIdByPath.get(path) ?? path,
      })),
    )
    // Coverage anchors on the manifest's own directory, not the process
    // cwd, so the same command reports the same coverage wherever it was
    // invoked (ADR 0130).
    const coverage = deriveArtifactCoverage(
      dirname(resolve(cwd, workspacePath)),
      loadedWorkspace.manifest.coverage,
    )
    const report = reconcileEvidenceReports(
      loadedWorkspace.workspace.id,
      evaluation.reports,
      compilation.graph,
      staleness,
      coverage,
    )
    return {
      exitCode: 0,
      stdout: text
        ? reconciliationReportText(report)
        : `${JSON.stringify(report, null, 2)}\n`,
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

// The id grammar the document and workspace schemas share: a lowercase
// letter first, then lowercase alphanumerics in single-hyphen segments.
const initIdPattern = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/

// The first check output should say the project's own name, not `main`
// (#275, ADR 0112): the default id is the target directory's basename,
// slugified to the shared id grammar. `init .` resolves before deriving,
// so the cwd's basename is what gets named. `main` remains the fallback
// when the basename yields nothing the schemas accept ('.', '..',
// all-symbols, a leading digit).
export const deriveInitId = (directory: string): string => {
  const slug = basename(directory)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
  return initIdPattern.test(slug) ? slug : 'main'
}

const runInit = (options: readonly string[], cwd: string): CliResult => {
  const positional = options.filter((option) => option !== '--no-pointer')
  const writePointer = positional.length === options.length
  const target = positional[0]
  if (
    positional.length !== 1 ||
    target === undefined ||
    target.startsWith('-')
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  const workspaceRoot = resolve(cwd, target)
  const documentPath = resolve(
    workspaceRoot,
    '.yarramate/architecture/main.yaml',
  )
  const manifestPath = resolve(workspaceRoot, '.yarramate/workspace.yaml')
  const displayPath = relative(cwd, documentPath)
  const displayManifestPath = relative(cwd, manifestPath)
  const existing = [
    ...(existsSync(documentPath) ? [displayPath] : []),
    ...(existsSync(manifestPath) ? [displayManifestPath] : []),
  ]
  if (existing.length > 0) {
    return {
      exitCode: 2,
      stdout: '',
      stderr: `${existing.join(' and ')} ${existing.length === 1 ? 'already exists' : 'already exist'}; nothing was changed\n`,
    }
  }
  const workspaceId = deriveInitId(workspaceRoot)
  mkdirSync(dirname(documentPath), { recursive: true })
  writeFileSync(
    documentPath,
    'format: yarramate/v1\n' +
      `id: ${workspaceId}\n` +
      'profile: yarramate/core@0.1\n' +
      'concepts: []\n' +
      'relationships: []\n',
    'utf8',
  )
  writeFileSync(
    manifestPath,
    'format: yarramate/workspace/v1\n' +
      `id: ${workspaceId}\n` +
      'documents:\n' +
      '  - architecture/*.yaml\n' +
      'profiles: []\n' +
      'projections: []\n' +
      'adapterMappings: []\n' +
      'evidence: []\n',
    'utf8',
  )
  const pointerMarker = '## YarraMate architecture'
  const pointerBlock =
    `${pointerMarker}\n` +
    '\n' +
    'This repository declares its architecture as canonical, versioned\n' +
    'YarraMate documents in `.yarramate/`. When prose documentation and the\n' +
    'model disagree, the model is authoritative.\n' +
    '\n' +
    '- Orient first: `yarramate ask .yarramate/workspace.yaml`\n' +
    '- Continue the design interview: `yarramate design .yarramate/workspace.yaml`\n' +
    '- Validate changes: `yarramate check .yarramate/workspace.yaml --json`\n' +
    '\n' +
    'Author native documents only; never edit generated output.\n'
  // Harnesses look in different files: AGENTS.md is the cross-harness
  // convention, while Claude Code auto-loads CLAUDE.md only. Delivering to
  // both is what makes the pointer reach an agent without instruction.
  const pointerNotes: string[] = []
  if (writePointer) {
    for (const pointerFile of ['AGENTS.md', 'CLAUDE.md']) {
      const pointerPath = resolve(workspaceRoot, pointerFile)
      const displayPointerPath = relative(cwd, pointerPath)
      if (!existsSync(pointerPath)) {
        writeFileSync(pointerPath, pointerBlock, 'utf8')
        pointerNotes.push(
          `Created ${displayPointerPath} with the YarraMate pointer\n`,
        )
      } else {
        const existingPointer = readFileSync(pointerPath, 'utf8')
        if (existingPointer.includes(pointerMarker)) {
          pointerNotes.push(
            `${displayPointerPath} already declares the YarraMate pointer\n`,
          )
        } else {
          writeFileSync(
            pointerPath,
            `${existingPointer.replace(/\n*$/, '\n\n')}${pointerBlock}`,
            'utf8',
          )
          pointerNotes.push(
            `Extended ${displayPointerPath} with the YarraMate pointer\n`,
          )
        }
      }
    }
  }
  return {
    exitCode: 0,
    stdout:
      `Created ${displayPath} and ${displayManifestPath}\n` +
      pointerNotes.join(''),
    stderr: '',
  }
}

// The seven-verb contract (docs/AGENT-INTERFACE.md): one verb per
// lifecycle stage — init creates, design fills, apply writes, ask reads,
// check gates, reconcile reports drift, export derives artifacts.
export function runCli(
  args: readonly string[],
  cwd: string = process.cwd(),
): CliResult {
  const [command, ...options] = args
  if (command === '--help' || command === '-h' || command === 'help') {
    return { exitCode: 0, stdout: usage, stderr: '' }
  }
  if (command === '--version' || command === '-v') {
    return versionResult('yarramate')
  }
  if (command === 'init') {
    return runInit(options, cwd)
  }
  if (command === 'design') {
    return runDesignCommand(options, cwd)
  }
  if (command === 'apply') {
    return runApplyCommand(options, cwd)
  }
  if (command === 'ask') {
    return runAskCommand(options, cwd)
  }
  if (command === 'check') {
    return runCheckCommand(options, cwd)
  }
  if (command === 'reconcile') {
    return runReconciliation(options, cwd)
  }
  if (command === 'export') {
    return runExportCommand(options, cwd)
  }
  return { exitCode: 2, stdout: '', stderr: usage }
}

/**
 * Every verb, including the one that cannot be synchronous.
 *
 * `import xlsx` has to inflate a workbook, and the only inflater available
 * everywhere this runs is `DecompressionStream`, which is async. Widening
 * `runCli` to return a promise would change the type every one of its callers
 * reads - the readers half of the rule in CONTRIBUTING.md - so the async verb
 * gets its own entry and `runCli` keeps its signature.
 */
export async function runCliAsync(
  args: readonly string[],
  cwd: string = process.cwd(),
): Promise<CliResult> {
  const [command, ...options] = args
  if (command === 'import') return runImportCommand(options, cwd)
  return runCli(args, cwd)
}

if (isMainModule(import.meta.url, process.argv[1])) {
  const result = await runCliAsync(process.argv.slice(2))
  process.stdout.write(result.stdout)
  process.stderr.write(result.stderr)
  process.exitCode = result.exitCode
}

#!/usr/bin/env node

import {
  closeSync,
  existsSync,
  lstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createHash, randomUUID } from 'node:crypto'
import Ajv2020Module from 'ajv/dist/2020.js'
import { isMap, isSeq, parseDocument } from 'yaml'
import {
  isMainModule,
  resolveCliWorkspaceSources,
  versionResult,
  type CliResult,
} from '../cli-support.js'
import { deriveChangedSubjects } from '../changed.js'
import { compileWorkspace } from '../compiler.js'
import {
  adapterMappingLocation,
  loadAdapterMapping,
  validateAdapterMapping,
} from '../adapter-mapping.js'
import {
  prepareLikeC4Export,
  type LikeC4PreparationDiagnostic,
} from './likec4-prepare.js'
import {
  exportLikeC4ProjectFromSources,
  inputDigestsOf,
  ownershipOf,
  projectNameOf,
} from './likec4-project-export.js'
import generatedProjectSchema from '../../schema/yarramate-likec4-generated-project.schema.json' with {
  type: 'json',
}
import generatedProjectV2Schema from '../../schema/yarramate-likec4-generated-project-v2.schema.json' with {
  type: 'json',
}

const Ajv2020 = Ajv2020Module.default
const validateGeneratedProjectMarker = new Ajv2020({
  allErrors: true,
}).compile(generatedProjectSchema)
const validateGeneratedProjectV2Marker = new Ajv2020({
  allErrors: true,
}).compile(generatedProjectV2Schema)
// A marker written before 1.0 flattened subject ids records a comparison's
// endpoints in the qualified `<document>#<local>` form, which `subjectIdentity`
// no longer admits in either marker version. Such a marker is still one of
// ours: those ids are recorded metadata, not addresses anything resolves, and
// regeneration rewrites them flat. So it is accepted where an existing project
// is read, exactly as a marker written before output digests existed is, and
// the upgrade happens on the next write with nothing for the reader to do.
// Each variant is derived from its own schema rather than copied, so a change
// to either cannot leave its variant behind: only the one pattern is relaxed.
const preFlattenSubjectIdentity =
  '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*(?:#[a-z][a-z0-9]*(?:-[a-z0-9]+)*)?$'
const preFlattenVariant = (schema: {
  readonly $id: string
  readonly $defs: {
    readonly subjectIdentity: { readonly pattern: string }
  }
}): Readonly<Record<string, unknown>> => ({
  ...schema,
  $id: `${schema.$id}/pre-flatten-subject-ids`,
  $defs: {
    ...schema.$defs,
    subjectIdentity: {
      ...schema.$defs.subjectIdentity,
      pattern: preFlattenSubjectIdentity,
    },
  },
})
const validateGeneratedProjectPreFlattenMarker = new Ajv2020({
  allErrors: true,
}).compile(preFlattenVariant(generatedProjectSchema))
const validateGeneratedProjectV2PreFlattenMarker = new Ajv2020({
  allErrors: true,
}).compile(preFlattenVariant(generatedProjectV2Schema))
const generatedFileNames = [
  'likec4.config.json',
  'model.likec4',
  'specification.likec4',
] as const

const sha256 = (value: string | Buffer): string =>
  createHash('sha256').update(value).digest('hex')

const stageFile = (
  destination: string,
  value: string | Buffer,
): { readonly publish: () => void; readonly cleanup: () => void } => {
  const staged = `${destination}.yarramate-${randomUUID()}.tmp`
  const descriptor = openSync(staged, 'wx', 0o666)
  let written = false
  try {
    writeFileSync(descriptor, value)
    written = true
  } finally {
    closeSync(descriptor)
    if (!written && existsSync(staged)) unlinkSync(staged)
  }
  return {
    publish: () => renameSync(staged, destination),
    cleanup: () => {
      if (existsSync(staged)) unlinkSync(staged)
    },
  }
}

const publishFiles = (
  files: readonly {
    readonly destination: string
    readonly value: string | Buffer
  }[],
) => {
  const stagedFiles: ReturnType<typeof stageFile>[] = []
  try {
    for (const file of files) {
      stagedFiles.push(stageFile(file.destination, file.value))
    }
  } catch (error) {
    for (const staged of stagedFiles) staged.cleanup()
    throw error
  }
  try {
    for (const staged of stagedFiles) staged.publish()
  } finally {
    for (const staged of stagedFiles) staged.cleanup()
  }
}

const usage =
  'Usage:\n' +
  '  yarramate-likec4 map --sync [--prune] <mapping.yaml> <workspace-or-source...>\n' +
  '  yarramate-likec4 check <projection.yaml> <mapping.yaml> [--json] [--kinds <kind-mapping.yaml>] [--compare <from-state> <to-state>] <workspace-or-source...>\n' +
  '  yarramate-likec4 check <likec4-project.yaml> [--json] <workspace-or-source...>\n' +
  '  yarramate-likec4 export <projection.yaml> <mapping.yaml> [--kinds <kind-mapping.yaml>] [--compare <from-state> <to-state>] <workspace-or-source...>\n' +
  '  yarramate-likec4 export-project [--check] <projection.yaml> <mapping.yaml> <output-dir> [--kinds <kind-mapping.yaml>] [--compare <from-state> <to-state>] <workspace-or-source...>\n' +
  '  yarramate-likec4 export-project [--check] <likec4-project.yaml> <output-dir> [--changed <git-range>] <workspace-or-source...>\n'

const diagnosticJson = (
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): string =>
  `${JSON.stringify(
    {
      format: 'yarramate/likec4-diagnostic-result/v1',
      diagnostics,
    },
    null,
    2,
  )}\n`

const checkJson = (
  ok: boolean,
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): string =>
  `${JSON.stringify(
    {
      format: 'yarramate/likec4-check-result/v1',
      ok,
      diagnostics,
    },
    null,
    2,
  )}\n`

const unmappedSubjectPreviewLength = 3

const summarizeUnmappedSubjects = (
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): readonly LikeC4PreparationDiagnostic[] =>
  (
    [
      ['YMLC102', 'concepts'],
      ['YMLC111', 'relationships'],
    ] as const
  ).reduce<readonly LikeC4PreparationDiagnostic[]>(
    (current, [code, noun]) => {
      const unmapped = current.filter(
        (diagnostic) => diagnostic.code === code,
      )
      if (unmapped.length <= unmappedSubjectPreviewLength) return current
      const preview = unmapped
        .slice(0, unmappedSubjectPreviewLength)
        .map((diagnostic) =>
          'subject' in diagnostic && diagnostic.subject !== undefined
            ? `"${diagnostic.subject}"`
            : `"${diagnostic.path}:${diagnostic.line}"`,
        )
        .join(', ')
      const summary: LikeC4PreparationDiagnostic = {
        ...unmapped[0]!,
        message:
          `${unmapped.length} projected ${noun} have no LikeC4 mapping ` +
          `(first: ${preview}); run "yarramate-likec4 map --sync" to add ` +
          'the missing mappings',
      }
      let summarized = false
      return current.flatMap((diagnostic) => {
        if (diagnostic.code !== code) return [diagnostic]
        if (summarized) return []
        summarized = true
        return [summary]
      })
    },
    diagnostics,
  )

const lowerCamel = (value: string) =>
  value.replaceAll(/-([a-z0-9])/g, (_, character: string) =>
    character.toUpperCase(),
  )

const runLikeC4MapSync = (
  args: readonly string[],
  cwd: string,
): CliResult => {
  const sync = args[0]
  const prune = args[1] === '--prune'
  const mappingPath = args[prune ? 2 : 1]
  const sourcePaths = args.slice(prune ? 3 : 2)
  if (
    sync !== '--sync' ||
    mappingPath === undefined ||
    mappingPath.startsWith('-') ||
    sourcePaths.length === 0 ||
    sourcePaths.some((path) => path.startsWith('-'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  try {
    const resolved = resolveCliWorkspaceSources(sourcePaths, cwd)
    if (!resolved.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(resolved.diagnostics),
        stderr: '',
      }
    }
    const compilation = compileWorkspace(
      resolved.paths.map((path) => ({
        path,
        source: readFileSync(resolve(cwd, path), 'utf8'),
      })),
    )
    if (!compilation.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(compilation.diagnostics),
        stderr: '',
      }
    }
    const absoluteMappingPath = resolve(cwd, mappingPath)
    const original = readFileSync(absoluteMappingPath, 'utf8')
    const loaded = loadAdapterMapping({
      path: mappingPath,
      source: original,
    })
    if (!loaded.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(loaded.diagnostics),
        stderr: '',
      }
    }
    if (loaded.mapping.adapter !== 'likec4') {
      const location = adapterMappingLocation(loaded.mapping, 'adapter')
      return {
        exitCode: 1,
        stdout: diagnosticJson([{
          severity: 'error',
          code: 'YMLC101',
          message: `Adapter mapping targets "${loaded.mapping.adapter}", not "likec4"`,
          ...location,
        }]),
        stderr: '',
      }
    }
    const graphSubjects = new Set(
      compilation.graph.subjects.map(({ id }) => id),
    )
    const staleCount = loaded.mapping.mappings.filter(
      ({ native }) => !graphSubjects.has(native),
    ).length
    const validation = validateAdapterMapping(
      compilation.graph,
      loaded.mapping,
    )
    const blockingDiagnostics = validation.ok
      ? []
      : validation.diagnostics.filter(({ code }) => code !== 'YM601')
    if (blockingDiagnostics.length > 0) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(blockingDiagnostics),
        stderr: '',
      }
    }
    const mapped = new Set(
      loaded.mapping.mappings.map(({ native }) => native),
    )
    const claimedExternal = new Set(
      loaded.mapping.mappings
        .filter(({ native }) => !prune || graphSubjects.has(native))
        .map(({ external }) => external),
    )
    const architectureStates = new Set(
      compilation.graph.claims
        .filter(({ predicate }) => predicate === 'yarramate/state/type')
        .map(({ subject }) => subject),
    )
    const additions = compilation.graph.subjects
      .filter(
        ({ id }) => !mapped.has(id) && !architectureStates.has(id),
      )
      .map((subject) => {
        // A subject id is the authored id, unique across the workspace, so it
        // is the whole name. The document-prefixed fallback that used to break
        // ties has nothing left to disambiguate; two ids can still collapse
        // onto one camel-case name (`foo-bar` and `fooBar`), and the numeric
        // suffix below has always been what separates those.
        let external = lowerCamel(subject.id)
        let suffix = 2
        const base = external
        while (claimedExternal.has(external)) {
          external = `${base}_${suffix}`
          suffix += 1
        }
        claimedExternal.add(external)
        return {
          native: subject.id,
          external,
          type: subject.type,
        }
      })
    if (additions.length === 0 && (!prune || staleCount === 0)) {
      return {
        exitCode: 0,
        stdout:
          staleCount === 0
            ? `LikeC4 mapping ${mappingPath} is already synchronized\n`
            : `LikeC4 mapping ${mappingPath} has ${staleCount} stale ${staleCount === 1 ? 'mapping' : 'mappings'} (use --prune)\n`,
        stderr: '',
      }
    }
    const document = parseDocument(original)
    const mappings = document.getIn(['mappings'], true)
    if (prune && isSeq(mappings)) {
      const firstMappingWasPruned =
        mappings.items.length > 0 &&
        isMap(mappings.items[0]) &&
        !graphSubjects.has(String(mappings.items[0].get('native')))
      mappings.items = mappings.items.filter(
        (item) =>
          !isMap(item) ||
          graphSubjects.has(String(item.get('native'))),
      )
      if (firstMappingWasPruned) mappings.commentBefore = undefined
    }
    for (const addition of additions) {
      document.addIn(['mappings'], addition)
    }
    if (isSeq(mappings)) mappings.flow = false
    const candidate = document.toString({ lineWidth: 0 })
    const candidateMapping = loadAdapterMapping({
      path: mappingPath,
      source: candidate,
    })
    if (!candidateMapping.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(candidateMapping.diagnostics),
        stderr: '',
      }
    }
    const candidateValidation = validateAdapterMapping(
      compilation.graph,
      candidateMapping.mapping,
    )
    const candidateBlockingDiagnostics = candidateValidation.ok
      ? []
      : candidateValidation.diagnostics.filter(
          ({ code }) => prune || code !== 'YM601',
        )
    if (candidateBlockingDiagnostics.length > 0) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(candidateBlockingDiagnostics),
        stderr: '',
      }
    }
    const staged = stageFile(absoluteMappingPath, candidate)
    try {
      staged.publish()
    } finally {
      staged.cleanup()
    }
    return {
      exitCode: 0,
      stdout: prune
        ? additions.length > 0
          ? `Added ${additions.length} and pruned ${staleCount} stale LikeC4 ${staleCount === 1 ? 'mapping' : 'mappings'} in ${mappingPath}\n`
          : `Pruned ${staleCount} stale LikeC4 ${staleCount === 1 ? 'mapping' : 'mappings'} from ${mappingPath}\n`
        : `Added ${additions.length} LikeC4 ${additions.length === 1 ? 'mapping' : 'mappings'} to ${mappingPath}` +
          (staleCount === 0
            ? '\n'
            : `; left ${staleCount} stale ${staleCount === 1 ? 'mapping' : 'mappings'} (use --prune)\n`),
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

// Ownership fields never gate updates: a marker of either format version
// plus intact output digests proves the directory is entirely
// machine-generated, so regenerating after the inputs changed loses nothing.
const readGeneratedProjectMarker = (
  markerPath: string,
): Readonly<Record<string, unknown>> | undefined => {
  let marker: unknown
  try {
    marker = JSON.parse(readFileSync(markerPath, 'utf8'))
  } catch {
    return undefined
  }
  return validateGeneratedProjectMarker(marker) ||
    validateGeneratedProjectV2Marker(marker) ||
    validateGeneratedProjectPreFlattenMarker(marker) ||
    validateGeneratedProjectV2PreFlattenMarker(marker)
    ? (marker as Readonly<Record<string, unknown>>)
    : undefined
}

const changedGeneratedFile = (
  projectPath: string,
  marker: Readonly<Record<string, unknown>>,
): string | undefined => {
  // Markers written before output digests existed are accepted once and
  // upgraded on regeneration.
  if (marker['digests'] === undefined) return undefined
  const digests = marker['digests'] as Readonly<Record<string, string>>
  return generatedFileNames.find((file) => {
    const path = resolve(projectPath, file)
    return (
      !existsSync(path) || sha256(readFileSync(path)) !== digests[file]
    )
  })
}

const publishGeneratedProject = (
  cwd: string,
  outputDirectory: string,
  input: {
    readonly projectName: string
    readonly title: string
    readonly modelSource: string
    readonly ownership: Readonly<Record<string, unknown>>
    readonly inputDigests: Readonly<Record<string, string>>
  },
): CliResult => {
  const projectPath = resolve(cwd, outputDirectory)
  const markerPath = resolve(projectPath, 'yarramate.generated.json')
  const updating = existsSync(projectPath)
  if (updating) {
    const projectStat = lstatSync(projectPath)
    if (projectStat.isSymbolicLink() || !projectStat.isDirectory()) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Output directory already exists: ${projectPath}\n`,
      }
    }
    const unsafeFile = [
      markerPath,
      ...generatedFileNames.map((file) => resolve(projectPath, file)),
    ].find((path) => {
      if (!existsSync(path)) return false
      const stat = lstatSync(path)
      return stat.isSymbolicLink() || !stat.isFile()
    })
    if (unsafeFile !== undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Generated project contains an unsafe file: ${unsafeFile}\n`,
      }
    }
    const marker = readGeneratedProjectMarker(markerPath)
    if (marker === undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Output directory exists but is not a YarraMate-generated project: ${projectPath}\n`,
      }
    }
    const changedFile = changedGeneratedFile(projectPath, marker)
    if (changedFile !== undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Generated project file has changed: ${resolve(projectPath, changedFile)}\n`,
      }
    }
  } else {
    mkdirSync(projectPath, { recursive: true })
  }
  const specificationSource = readFileSync(
    fileURLToPath(
      new URL(
        '../../assets/likec4/specification.likec4',
        import.meta.url,
      ),
    ),
  )
  const configSource = `${JSON.stringify(
    {
      $schema: 'https://likec4.dev/schemas/config.json',
      name: input.projectName,
      title: input.title,
    },
    null,
    2,
  )}\n`
  const markerSource = `${JSON.stringify(
    {
      ...input.ownership,
      files: [
        'likec4.config.json',
        'model.likec4',
        'specification.likec4',
      ],
      digests: {
        'likec4.config.json': sha256(configSource),
        'model.likec4': sha256(input.modelSource),
        'specification.likec4': sha256(specificationSource),
      },
      inputDigests: input.inputDigests,
    },
    null,
    2,
  )}\n`
  publishFiles([
    {
      destination: resolve(projectPath, 'likec4.config.json'),
      value: configSource,
    },
    {
      destination: resolve(projectPath, 'model.likec4'),
      value: input.modelSource,
    },
    {
      destination: resolve(projectPath, 'specification.likec4'),
      value: specificationSource,
    },
    { destination: markerPath, value: markerSource },
  ])
  return {
    exitCode: 0,
    stdout: updating
      ? `Updated LikeC4 project at ${projectPath}\n`
      : `Wrote LikeC4 project to ${projectPath}\n`,
    stderr: '',
  }
}

// Freshness is a pure digest comparison between the marker and the would-be
// export; nothing on disk is written or semantically judged.
const checkGeneratedProject = (
  cwd: string,
  outputDirectory: string,
  input: {
    readonly modelSource: string
    readonly inputDigests: Readonly<Record<string, string>>
  },
): CliResult => {
  const projectPath = resolve(cwd, outputDirectory)
  if (!existsSync(projectPath)) {
    return {
      exitCode: 1,
      stdout: 'Generated LikeC4 output: absent\n',
      stderr: '',
    }
  }
  const marker = readGeneratedProjectMarker(
    resolve(projectPath, 'yarramate.generated.json'),
  )
  if (marker === undefined) {
    return {
      exitCode: 2,
      stdout: '',
      stderr: `Output directory exists but is not a YarraMate-generated project: ${projectPath}\n`,
    }
  }
  const changedFile = changedGeneratedFile(projectPath, marker)
  if (changedFile !== undefined) {
    return {
      exitCode: 1,
      stdout:
        'Generated LikeC4 output: modified\n' +
        'Reason:\n' +
        `- generated file changed: ${resolve(projectPath, changedFile)}\n` +
        'Safe to regenerate: no\n',
      stderr: '',
    }
  }
  const recordedInputs = marker['inputDigests'] as
    | Readonly<Record<string, string>>
    | undefined
  const reasons: string[] = []
  if (recordedInputs === undefined) {
    reasons.push('marker predates input digests')
  } else {
    const inputPaths = [
      ...new Set([
        ...Object.keys(recordedInputs),
        ...Object.keys(input.inputDigests),
      ]),
    ].sort()
    for (const path of inputPaths) {
      const recorded = recordedInputs[path]
      const current = input.inputDigests[path]
      if (recorded === undefined) reasons.push(`input added: ${path}`)
      else if (current === undefined) {
        reasons.push(`input removed: ${path}`)
      } else if (recorded !== current) {
        reasons.push(`input changed: ${path}`)
      }
    }
  }
  const digests = marker['digests'] as
    | Readonly<Record<string, string>>
    | undefined
  if (
    digests !== undefined &&
    sha256(input.modelSource) !== digests['model.likec4']
  ) {
    reasons.push('model source changed')
  }
  if (reasons.length === 0) {
    return {
      exitCode: 0,
      stdout: 'Generated LikeC4 output: fresh\n',
      stderr: '',
    }
  }
  return {
    exitCode: 1,
    stdout:
      'Generated LikeC4 output: stale\n' +
      'Reason:\n' +
      reasons.map((reason) => `- ${reason}\n`).join('') +
      'Safe to regenerate: yes\n',
    stderr: '',
  }
}

export function runLikeC4Cli(
  args: readonly string[],
  cwd: string = process.cwd(),
): CliResult {
  if (args[0] === '--version') {
    return versionResult('yarramate-likec4')
  }
  if (args[0] === 'map') {
    return runLikeC4MapSync(args.slice(1), cwd)
  }
  const checkFreshness =
    args[0] === 'export-project' && args.includes('--check')
  const [command, projectionPath, mappingPath, ...options] = checkFreshness
    ? args.filter((argument) => argument !== '--check')
    : args
  let projectDefinitionMode = false
  if (
    (command === 'check' || command === 'export-project') &&
    projectionPath !== undefined
  ) {
    try {
      projectDefinitionMode =
        parseDocument(
          readFileSync(resolve(cwd, projectionPath), 'utf8'),
        ).get('format') === 'yarramate/likec4-project/v1'
    } catch {
      projectDefinitionMode = false
    }
  }
  const outputDirectory =
    command === 'export-project'
      ? projectDefinitionMode
        ? mappingPath
        : options[0]
      : undefined
  const sourceOptions =
    projectDefinitionMode && command === 'check'
      ? [mappingPath, ...options].filter(
          (value): value is string => value !== undefined,
        )
      : command === 'export-project'
      ? projectDefinitionMode
        ? options
        : options.slice(1)
      : options
  const json = command === 'check' && sourceOptions.includes('--json')
  let invalidOptions = false
  let kindMappingPath: string | undefined
  let comparison:
    | { readonly from: string; readonly to: string }
    | undefined
  let changedRange: string | undefined
  const sourcePaths: string[] = []
  for (let index = 0; index < sourceOptions.length; index += 1) {
    const option = sourceOptions[index]!
    if (option === '--json') {
      if (command !== 'check') invalidOptions = true
      continue
    }
    if (option === '--kinds') {
      const value = sourceOptions[index + 1]
      if (
        value === undefined ||
        value.startsWith('-') ||
        kindMappingPath !== undefined
      ) {
        invalidOptions = true
      } else {
        kindMappingPath = value
        index += 1
      }
      continue
    }
    if (option === '--changed') {
      const value = sourceOptions[index + 1]
      if (
        value === undefined ||
        value.startsWith('-') ||
        changedRange !== undefined
      ) {
        invalidOptions = true
      } else {
        changedRange = value
        index += 1
      }
      continue
    }
    if (option === '--compare') {
      const from = sourceOptions[index + 1]
      const to = sourceOptions[index + 2]
      if (
        from === undefined ||
        to === undefined ||
        from.startsWith('-') ||
        to.startsWith('-') ||
        comparison !== undefined
      ) {
        invalidOptions = true
      } else {
        comparison = { from, to }
        index += 2
      }
      continue
    }
    if (option.startsWith('-')) invalidOptions = true
    else sourcePaths.push(option)
  }
  if (
    (command !== 'check' &&
      command !== 'export' &&
      command !== 'export-project') ||
    projectionPath === undefined ||
    (!projectDefinitionMode && mappingPath === undefined) ||
    (projectDefinitionMode &&
      command === 'export-project' &&
      mappingPath === undefined) ||
    (command === 'export-project' && outputDirectory === undefined) ||
    (projectDefinitionMode &&
      (kindMappingPath !== undefined || comparison !== undefined)) ||
    (changedRange !== undefined &&
      !(projectDefinitionMode && command === 'export-project')) ||
    invalidOptions ||
    sourcePaths.length === 0 ||
    sourcePaths.some((argument) => argument.startsWith('-'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  const diagnosticOutput = (
    diagnostics: Parameters<typeof diagnosticJson>[0],
  ) =>
    json
      ? checkJson(false, diagnostics)
      : diagnosticJson(
          command === 'check'
            ? summarizeUnmappedSubjects(diagnostics)
            : diagnostics,
        )

  try {
    const resolved = resolveCliWorkspaceSources(sourcePaths, cwd)
    if (!resolved.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticOutput(resolved.diagnostics),
        stderr: '',
      }
    }
    const sources = resolved.paths.map((path) => ({
      path,
      source: readFileSync(resolve(cwd, path), 'utf8'),
    }))
    if (projectDefinitionMode) {
      const projectSource = {
        path: projectionPath,
        source: readFileSync(resolve(cwd, projectionPath), 'utf8'),
      }
      const projectDirectory = dirname(resolve(cwd, projectionPath))
      // The git-derived review overlay is the CLI's own: it needs a
      // repository. Everything after it runs the same pure pipeline the
      // path-free entry runs (ADR 0156).
      let gitChange
      if (changedRange !== undefined) {
        const modelDocuments = sources.flatMap((candidate) => {
          const parsed = parseDocument(candidate.source)
          if (parsed.get('format') !== 'yarramate/v1') return []
          const documentId = parsed.get('id')
          return typeof documentId === 'string'
            ? [{ ...candidate, documentId }]
            : []
        })
        const derived = deriveChangedSubjects(
          cwd,
          changedRange,
          modelDocuments,
        )
        if (!derived.ok) {
          return { exitCode: 2, stdout: '', stderr: `${derived.message}\n` }
        }
        const all = [
          ...derived.changed.concepts,
          ...derived.changed.relationships,
        ]
        gitChange = {
          range: derived.changed.range,
          added: derived.changed.added,
          modified: all.filter(
            (id) => !derived.changed.added.includes(id),
          ),
        }
      }
      const exported = exportLikeC4ProjectFromSources({
        project: projectSource,
        sources,
        readReference: (path) => {
          try {
            return {
              path,
              source: readFileSync(resolve(projectDirectory, path), 'utf8'),
            }
          } catch {
            return undefined
          }
        },
        requireMappedRelationships: command === 'check',
        ...(gitChange === undefined ? {} : { gitChange }),
      })
      if (!exported.ok) {
        return {
          exitCode: 1,
          stdout: diagnosticOutput(exported.diagnostics),
          stderr: '',
        }
      }
      if (command === 'check') {
        return {
          exitCode: 0,
          stdout: json
            ? checkJson(true, [])
            : `Checked LikeC4 project ${exported.projectIdentity}: no errors\n`,
          stderr: '',
        }
      }
      const inputDigests = inputDigestsOf(exported.inputs)
      if (checkFreshness) {
        return checkGeneratedProject(cwd, outputDirectory!, {
          modelSource: exported.modelSource,
          inputDigests,
        })
      }
      return publishGeneratedProject(cwd, outputDirectory!, {
        projectName: projectNameOf(exported.projectIdentity),
        title: exported.project.title,
        modelSource: exported.modelSource,
        ownership: { ...ownershipOf(exported) },
        inputDigests,
      })
    }
    const projectionSource = {
      path: projectionPath,
      source: readFileSync(resolve(cwd, projectionPath), 'utf8'),
    }
    const mappingSource = {
      path: mappingPath!,
      source: readFileSync(resolve(cwd, mappingPath!), 'utf8'),
    }
    const kindMappingSource =
      kindMappingPath === undefined
        ? undefined
        : {
            path: kindMappingPath,
            source: readFileSync(resolve(cwd, kindMappingPath), 'utf8'),
          }
    const prepared = prepareLikeC4Export({
      sources,
      projection: projectionSource,
      subjectMapping: mappingSource,
      ...(kindMappingSource === undefined
        ? {}
        : { kindMapping: kindMappingSource }),
      ...(comparison === undefined ? {} : { comparison }),
      vocabulary: command === 'export' ? 'consumer' : 'bundled',
      requireMappedRelationships: command === 'check',
    })
    if (!prepared.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticOutput(prepared.diagnostics),
        stderr: '',
      }
    }
    if (command === 'check') {
      return {
        exitCode: 0,
        stdout: json
          ? checkJson(true, [])
          : `Checked LikeC4 export ${prepared.projection.projection}: no errors\n`,
        stderr: '',
      }
    }
    if (command === 'export') {
      return { exitCode: 0, stdout: prepared.source, stderr: '' }
    }

    const projectionIdentity = prepared.projection.projection
    const mappingIdentity = `${prepared.subjectMapping.id}@${prepared.subjectMapping.version}`
    const kindMappingIdentity =
      prepared.kindMapping === undefined
        ? undefined
        : `${prepared.kindMapping.id}@${prepared.kindMapping.version}`
    const comparisonIdentity = comparison
    const inputDigests = inputDigestsOf([
      projectionSource,
      mappingSource,
      ...(kindMappingSource === undefined ? [] : [kindMappingSource]),
      ...sources,
    ])
    if (checkFreshness) {
      return checkGeneratedProject(cwd, outputDirectory!, {
        modelSource: prepared.source,
        inputDigests,
      })
    }
    return publishGeneratedProject(cwd, outputDirectory!, {
      projectName: ['yarramate', projectionIdentity]
        .join('-')
        .replaceAll(/[^A-Za-z0-9_-]/g, '-'),
      title:
        prepared.projection.presentation?.title ??
        projectionIdentity.slice(0, projectionIdentity.lastIndexOf('@')),
      modelSource: prepared.source,
      ownership: {
        format: 'yarramate/likec4-generated-project/v1',
        projection: projectionIdentity,
        mapping: mappingIdentity,
        ...(kindMappingIdentity === undefined
          ? {}
          : { kindMapping: kindMappingIdentity }),
        ...(comparisonIdentity === undefined
          ? {}
          : { comparison: comparisonIdentity }),
      },
      inputDigests,
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

if (isMainModule(import.meta.url, process.argv[1])) {
  const result = runLikeC4Cli(process.argv.slice(2))
  process.stdout.write(result.stdout)
  process.stderr.write(result.stderr)
  process.exitCode = result.exitCode
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://yarramate.org/schema/likec4-generated-project/v2",
  "title": "YarraMate generated multi-view LikeC4 project marker",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "project", "mapping", "views", "files", "digests"],
  "properties": {
    "format": {
      "const": "yarramate/likec4-generated-project/v2"
    },
    "project": {
      "$ref": "#/$defs/versionedIdentity"
    },
    "mapping": {
      "$ref": "#/$defs/versionedIdentity"
    },
    "kindMapping": {
      "$ref": "#/$defs/versionedIdentity"
    },
    "views": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/view"
      }
    },
    "digests": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "likec4.config.json",
        "model.likec4",
        "specification.likec4"
      ],
      "properties": {
        "likec4.config.json": {
          "$ref": "#/$defs/sha256"
        },
        "model.likec4": {
          "$ref": "#/$defs/sha256"
        },
        "specification.likec4": {
          "$ref": "#/$defs/sha256"
        }
      }
    },
    "inputDigests": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/sha256"
      }
    },
    "files": {
      "const": [
        "likec4.config.json",
        "model.likec4",
        "specification.likec4"
      ]
    }
  },
  "$defs": {
    "id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "versionedIdentity": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*@[0-9]+\\.[0-9]+$"
    },
    "subjectIdentity": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "view": {
      "type": "object",
      "additionalProperties": false,
      "required": ["projection"],
      "properties": {
        "id": {
          "$ref": "#/$defs/id"
        },
        "projection": {
          "$ref": "#/$defs/versionedIdentity"
        },
        "comparison": {
          "type": "object",
          "additionalProperties": false,
          "required": ["from", "to"],
          "properties": {
            "from": {
              "$ref": "#/$defs/subjectIdentity"
            },
            "to": {
              "$ref": "#/$defs/subjectIdentity"
            }
          }
        }
      }
    },
    "sha256": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    }
  }
}

#!/usr/bin/env node

import {
  closeSync,
  existsSync,
  lstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  renameSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createHash, randomUUID } from 'node:crypto'
import Ajv2020Module from 'ajv/dist/2020.js'
import { isMap, isSeq, parseDocument } from 'yaml'
import {
  isMainModule,
  resolveCliWorkspaceSources,
  versionResult,
  type CliResult,
} from '../cli-support.js'
import { deriveChangedSubjects } from '../changed.js'
import { compileWorkspace } from '../compiler.js'
import {
  adapterMappingLocation,
  loadAdapterMapping,
  validateAdapterMapping,
} from '../adapter-mapping.js'
import {
  prepareLikeC4Export,
  type LikeC4PreparationDiagnostic,
} from './likec4-prepare.js'
import {
  exportLikeC4ProjectFromSources,
  inputDigestsOf,
  ownershipOf,
  projectNameOf,
} from './likec4-project-export.js'
import generatedProjectSchema from '../../schema/yarramate-likec4-generated-project.schema.json' with {
  type: 'json',
}
import generatedProjectV2Schema from '../../schema/yarramate-likec4-generated-project-v2.schema.json' with {
  type: 'json',
}

const Ajv2020 = Ajv2020Module.default
const validateGeneratedProjectMarker = new Ajv2020({
  allErrors: true,
}).compile(generatedProjectSchema)
const validateGeneratedProjectV2Marker = new Ajv2020({
  allErrors: true,
}).compile(generatedProjectV2Schema)
// A marker written before 1.0 flattened subject ids records a comparison's
// endpoints in the qualified `<document>#<local>` form, which `subjectIdentity`
// no longer admits in either marker version. Such a marker is still one of
// ours: those ids are recorded metadata, not addresses anything resolves, and
// regeneration rewrites them flat. So it is accepted where an existing project
// is read, exactly as a marker written before output digests existed is, and
// the upgrade happens on the next write with nothing for the reader to do.
// Each variant is derived from its own schema rather than copied, so a change
// to either cannot leave its variant behind: only the one pattern is relaxed.
const preFlattenSubjectIdentity =
  '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*(?:#[a-z][a-z0-9]*(?:-[a-z0-9]+)*)?$'
const preFlattenVariant = (schema: {
  readonly $id: string
  readonly $defs: {
    readonly subjectIdentity: { readonly pattern: string }
  }
}): Readonly<Record<string, unknown>> => ({
  ...schema,
  $id: `${schema.$id}/pre-flatten-subject-ids`,
  $defs: {
    ...schema.$defs,
    subjectIdentity: {
      ...schema.$defs.subjectIdentity,
      pattern: preFlattenSubjectIdentity,
    },
  },
})
const validateGeneratedProjectPreFlattenMarker = new Ajv2020({
  allErrors: true,
}).compile(preFlattenVariant(generatedProjectSchema))
const validateGeneratedProjectV2PreFlattenMarker = new Ajv2020({
  allErrors: true,
}).compile(preFlattenVariant(generatedProjectV2Schema))
const generatedFileNames = [
  'likec4.config.json',
  'model.likec4',
  'specification.likec4',
] as const

const sha256 = (value: string | Buffer): string =>
  createHash('sha256').update(value).digest('hex')

const stageFile = (
  destination: string,
  value: string | Buffer,
): { readonly publish: () => void; readonly cleanup: () => void } => {
  const staged = `${destination}.yarramate-${randomUUID()}.tmp`
  const descriptor = openSync(staged, 'wx', 0o666)
  let written = false
  try {
    writeFileSync(descriptor, value)
    written = true
  } finally {
    closeSync(descriptor)
    if (!written && existsSync(staged)) unlinkSync(staged)
  }
  return {
    publish: () => renameSync(staged, destination),
    cleanup: () => {
      if (existsSync(staged)) unlinkSync(staged)
    },
  }
}

const publishFiles = (
  files: readonly {
    readonly destination: string
    readonly value: string | Buffer
  }[],
) => {
  const stagedFiles: ReturnType<typeof stageFile>[] = []
  try {
    for (const file of files) {
      stagedFiles.push(stageFile(file.destination, file.value))
    }
  } catch (error) {
    for (const staged of stagedFiles) staged.cleanup()
    throw error
  }
  try {
    for (const staged of stagedFiles) staged.publish()
  } finally {
    for (const staged of stagedFiles) staged.cleanup()
  }
}

const usage =
  'Usage:\n' +
  '  yarramate-likec4 map --sync [--prune] <mapping.yaml> <workspace-or-source...>\n' +
  '  yarramate-likec4 check <projection.yaml> <mapping.yaml> [--json] [--kinds <kind-mapping.yaml>] [--compare <from-state> <to-state>] <workspace-or-source...>\n' +
  '  yarramate-likec4 check <likec4-project.yaml> [--json] <workspace-or-source...>\n' +
  '  yarramate-likec4 export <projection.yaml> <mapping.yaml> [--kinds <kind-mapping.yaml>] [--compare <from-state> <to-state>] <workspace-or-source...>\n' +
  '  yarramate-likec4 export-project [--check] <projection.yaml> <mapping.yaml> <output-dir> [--kinds <kind-mapping.yaml>] [--compare <from-state> <to-state>] <workspace-or-source...>\n' +
  '  yarramate-likec4 export-project [--check] <likec4-project.yaml> <output-dir> [--changed <git-range>] <workspace-or-source...>\n'

const diagnosticJson = (
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): string =>
  `${JSON.stringify(
    {
      format: 'yarramate/likec4-diagnostic-result/v1',
      diagnostics,
    },
    null,
    2,
  )}\n`

const checkJson = (
  ok: boolean,
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): string =>
  `${JSON.stringify(
    {
      format: 'yarramate/likec4-check-result/v1',
      ok,
      diagnostics,
    },
    null,
    2,
  )}\n`

const unmappedSubjectPreviewLength = 3

const summarizeUnmappedSubjects = (
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): readonly LikeC4PreparationDiagnostic[] =>
  (
    [
      ['YMLC102', 'concepts'],
      ['YMLC111', 'relationships'],
    ] as const
  ).reduce<readonly LikeC4PreparationDiagnostic[]>(
    (current, [code, noun]) => {
      const unmapped = current.filter(
        (diagnostic) => diagnostic.code === code,
      )
      if (unmapped.length <= unmappedSubjectPreviewLength) return current
      const preview = unmapped
        .slice(0, unmappedSubjectPreviewLength)
        .map((diagnostic) =>
          'subject' in diagnostic && diagnostic.subject !== undefined
            ? `"${diagnostic.subject}"`
            : `"${diagnostic.path}:${diagnostic.line}"`,
        )
        .join(', ')
      const summary: LikeC4PreparationDiagnostic = {
        ...unmapped[0]!,
        message:
          `${unmapped.length} projected ${noun} have no LikeC4 mapping ` +
          `(first: ${preview}); run "yarramate-likec4 map --sync" to add ` +
          'the missing mappings',
      }
      let summarized = false
      return current.flatMap((diagnostic) => {
        if (diagnostic.code !== code) return [diagnostic]
        if (summarized) return []
        summarized = true
        return [summary]
      })
    },
    diagnostics,
  )

const lowerCamel = (value: string) =>
  value.replaceAll(/-([a-z0-9])/g, (_, character: string) =>
    character.toUpperCase(),
  )

const runLikeC4MapSync = (
  args: readonly string[],
  cwd: string,
): CliResult => {
  const sync = args[0]
  const prune = args[1] === '--prune'
  const mappingPath = args[prune ? 2 : 1]
  const sourcePaths = args.slice(prune ? 3 : 2)
  if (
    sync !== '--sync' ||
    mappingPath === undefined ||
    mappingPath.startsWith('-') ||
    sourcePaths.length === 0 ||
    sourcePaths.some((path) => path.startsWith('-'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  try {
    const resolved = resolveCliWorkspaceSources(sourcePaths, cwd)
    if (!resolved.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(resolved.diagnostics),
        stderr: '',
      }
    }
    const compilation = compileWorkspace(
      resolved.paths.map((path) => ({
        path,
        source: readFileSync(resolve(cwd, path), 'utf8'),
      })),
    )
    if (!compilation.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(compilation.diagnostics),
        stderr: '',
      }
    }
    const absoluteMappingPath = resolve(cwd, mappingPath)
    const original = readFileSync(absoluteMappingPath, 'utf8')
    const loaded = loadAdapterMapping({
      path: mappingPath,
      source: original,
    })
    if (!loaded.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(loaded.diagnostics),
        stderr: '',
      }
    }
    if (loaded.mapping.adapter !== 'likec4') {
      const location = adapterMappingLocation(loaded.mapping, 'adapter')
      return {
        exitCode: 1,
        stdout: diagnosticJson([{
          severity: 'error',
          code: 'YMLC101',
          message: `Adapter mapping targets "${loaded.mapping.adapter}", not "likec4"`,
          ...location,
        }]),
        stderr: '',
      }
    }
    const graphSubjects = new Set(
      compilation.graph.subjects.map(({ id }) => id),
    )
    const staleCount = loaded.mapping.mappings.filter(
      ({ native }) => !graphSubjects.has(native),
    ).length
    const validation = validateAdapterMapping(
      compilation.graph,
      loaded.mapping,
    )
    const blockingDiagnostics = validation.ok
      ? []
      : validation.diagnostics.filter(({ code }) => code !== 'YM601')
    if (blockingDiagnostics.length > 0) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(blockingDiagnostics),
        stderr: '',
      }
    }
    const mapped = new Set(
      loaded.mapping.mappings.map(({ native }) => native),
    )
    const claimedExternal = new Set(
      loaded.mapping.mappings
        .filter(({ native }) => !prune || graphSubjects.has(native))
        .map(({ external }) => external),
    )
    const architectureStates = new Set(
      compilation.graph.claims
        .filter(({ predicate }) => predicate === 'yarramate/state/type')
        .map(({ subject }) => subject),
    )
    const additions = compilation.graph.subjects
      .filter(
        ({ id }) => !mapped.has(id) && !architectureStates.has(id),
      )
      .map((subject) => {
        // A subject id is the authored id, unique across the workspace, so it
        // is the whole name. The document-prefixed fallback that used to break
        // ties has nothing left to disambiguate; two ids can still collapse
        // onto one camel-case name (`foo-bar` and `fooBar`), and the numeric
        // suffix below has always been what separates those.
        let external = lowerCamel(subject.id)
        let suffix = 2
        const base = external
        while (claimedExternal.has(external)) {
          external = `${base}_${suffix}`
          suffix += 1
        }
        claimedExternal.add(external)
        return {
          native: subject.id,
          external,
          type: subject.type,
        }
      })
    if (additions.length === 0 && (!prune || staleCount === 0)) {
      return {
        exitCode: 0,
        stdout:
          staleCount === 0
            ? `LikeC4 mapping ${mappingPath} is already synchronized\n`
            : `LikeC4 mapping ${mappingPath} has ${staleCount} stale ${staleCount === 1 ? 'mapping' : 'mappings'} (use --prune)\n`,
        stderr: '',
      }
    }
    const document = parseDocument(original)
    const mappings = document.getIn(['mappings'], true)
    if (prune && isSeq(mappings)) {
      const firstMappingWasPruned =
        mappings.items.length > 0 &&
        isMap(mappings.items[0]) &&
        !graphSubjects.has(String(mappings.items[0].get('native')))
      mappings.items = mappings.items.filter(
        (item) =>
          !isMap(item) ||
          graphSubjects.has(String(item.get('native'))),
      )
      if (firstMappingWasPruned) mappings.commentBefore = undefined
    }
    for (const addition of additions) {
      document.addIn(['mappings'], addition)
    }
    if (isSeq(mappings)) mappings.flow = false
    const candidate = document.toString({ lineWidth: 0 })
    const candidateMapping = loadAdapterMapping({
      path: mappingPath,
      source: candidate,
    })
    if (!candidateMapping.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(candidateMapping.diagnostics),
        stderr: '',
      }
    }
    const candidateValidation = validateAdapterMapping(
      compilation.graph,
      candidateMapping.mapping,
    )
    const candidateBlockingDiagnostics = candidateValidation.ok
      ? []
      : candidateValidation.diagnostics.filter(
          ({ code }) => prune || code !== 'YM601',
        )
    if (candidateBlockingDiagnostics.length > 0) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(candidateBlockingDiagnostics),
        stderr: '',
      }
    }
    const staged = stageFile(absoluteMappingPath, candidate)
    try {
      staged.publish()
    } finally {
      staged.cleanup()
    }
    return {
      exitCode: 0,
      stdout: prune
        ? additions.length > 0
          ? `Added ${additions.length} and pruned ${staleCount} stale LikeC4 ${staleCount === 1 ? 'mapping' : 'mappings'} in ${mappingPath}\n`
          : `Pruned ${staleCount} stale LikeC4 ${staleCount === 1 ? 'mapping' : 'mappings'} from ${mappingPath}\n`
        : `Added ${additions.length} LikeC4 ${additions.length === 1 ? 'mapping' : 'mappings'} to ${mappingPath}` +
          (staleCount === 0
            ? '\n'
            : `; left ${staleCount} stale ${staleCount === 1 ? 'mapping' : 'mappings'} (use --prune)\n`),
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

// Ownership fields never gate updates: a marker of either format version
// plus intact output digests proves the directory is entirely
// machine-generated, so regenerating after the inputs changed loses nothing.
const readGeneratedProjectMarker = (
  markerPath: string,
): Readonly<Record<string, unknown>> | undefined => {
  let marker: unknown
  try {
    marker = JSON.parse(readFileSync(markerPath, 'utf8'))
  } catch {
    return undefined
  }
  return validateGeneratedProjectMarker(marker) ||
    validateGeneratedProjectV2Marker(marker) ||
    validateGeneratedProjectPreFlattenMarker(marker) ||
    validateGeneratedProjectV2PreFlattenMarker(marker)
    ? (marker as Readonly<Record<string, unknown>>)
    : undefined
}

const changedGeneratedFile = (
  projectPath: string,
  marker: Readonly<Record<string, unknown>>,
): string | undefined => {
  // Markers written before output digests existed are accepted once and
  // upgraded on regeneration.
  if (marker['digests'] === undefined) return undefined
  const digests = marker['digests'] as Readonly<Record<string, string>>
  return generatedFileNames.find((file) => {
    const path = resolve(projectPath, file)
    return (
      !existsSync(path) || sha256(readFileSync(path)) !== digests[file]
    )
  })
}

const publishGeneratedProject = (
  cwd: string,
  outputDirectory: string,
  input: {
    readonly projectName: string
    readonly title: string
    readonly modelSource: string
    readonly ownership: Readonly<Record<string, unknown>>
    readonly inputDigests: Readonly<Record<string, string>>
  },
): CliResult => {
  const projectPath = resolve(cwd, outputDirectory)
  const markerPath = resolve(projectPath, 'yarramate.generated.json')
  const updating = existsSync(projectPath)
  if (updating) {
    const projectStat = lstatSync(projectPath)
    if (projectStat.isSymbolicLink() || !projectStat.isDirectory()) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Output directory already exists: ${projectPath}\n`,
      }
    }
    const unsafeFile = [
      markerPath,
      ...generatedFileNames.map((file) => resolve(projectPath, file)),
    ].find((path) => {
      if (!existsSync(path)) return false
      const stat = lstatSync(path)
      return stat.isSymbolicLink() || !stat.isFile()
    })
    if (unsafeFile !== undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Generated project contains an unsafe file: ${unsafeFile}\n`,
      }
    }
    const marker = readGeneratedProjectMarker(markerPath)
    if (marker === undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Output directory exists but is not a YarraMate-generated project: ${projectPath}\n`,
      }
    }
    const changedFile = changedGeneratedFile(projectPath, marker)
    if (changedFile !== undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Generated project file has changed: ${resolve(projectPath, changedFile)}\n`,
      }
    }
  } else {
    mkdirSync(projectPath, { recursive: true })
  }
  const specificationSource = readFileSync(
    fileURLToPath(
      new URL(
        '../../assets/likec4/specification.likec4',
        import.meta.url,
      ),
    ),
  )
  const configSource = `${JSON.stringify(
    {
      $schema: 'https://likec4.dev/schemas/config.json',
      name: input.projectName,
      title: input.title,
    },
    null,
    2,
  )}\n`
  const markerSource = `${JSON.stringify(
    {
      ...input.ownership,
      files: [
        'likec4.config.json',
        'model.likec4',
        'specification.likec4',
      ],
      digests: {
        'likec4.config.json': sha256(configSource),
        'model.likec4': sha256(input.modelSource),
        'specification.likec4': sha256(specificationSource),
      },
      inputDigests: input.inputDigests,
    },
    null,
    2,
  )}\n`
  publishFiles([
    {
      destination: resolve(projectPath, 'likec4.config.json'),
      value: configSource,
    },
    {
      destination: resolve(projectPath, 'model.likec4'),
      value: input.modelSource,
    },
    {
      destination: resolve(projectPath, 'specification.likec4'),
      value: specificationSource,
    },
    { destination: markerPath, value: markerSource },
  ])
  return {
    exitCode: 0,
    stdout: updating
      ? `Updated LikeC4 project at ${projectPath}\n`
      : `Wrote LikeC4 project to ${projectPath}\n`,
    stderr: '',
  }
}

// Freshness is a pure digest comparison between the marker and the would-be
// export; nothing on disk is written or semantically judged.
const checkGeneratedProject = (
  cwd: string,
  outputDirectory: string,
  input: {
    readonly modelSource: string
    readonly inputDigests: Readonly<Record<string, string>>
  },
): CliResult => {
  const projectPath = resolve(cwd, outputDirectory)
  if (!existsSync(projectPath)) {
    return {
      exitCode: 1,
      stdout: 'Generated LikeC4 output: absent\n',
      stderr: '',
    }
  }
  const marker = readGeneratedProjectMarker(
    resolve(projectPath, 'yarramate.generated.json'),
  )
  if (marker === undefined) {
    return {
      exitCode: 2,
      stdout: '',
      stderr: `Output directory exists but is not a YarraMate-generated project: ${projectPath}\n`,
    }
  }
  const changedFile = changedGeneratedFile(projectPath, marker)
  if (changedFile !== undefined) {
    return {
      exitCode: 1,
      stdout:
        'Generated LikeC4 output: modified\n' +
        'Reason:\n' +
        `- generated file changed: ${resolve(projectPath, changedFile)}\n` +
        'Safe to regenerate: no\n',
      stderr: '',
    }
  }
  const recordedInputs = marker['inputDigests'] as
    | Readonly<Record<string, string>>
    | undefined
  const reasons: string[] = []
  if (recordedInputs === undefined) {
    reasons.push('marker predates input digests')
  } else {
    const inputPaths = [
      ...new Set([
        ...Object.keys(recordedInputs),
        ...Object.keys(input.inputDigests),
      ]),
    ].sort()
    for (const path of inputPaths) {
      const recorded = recordedInputs[path]
      const current = input.inputDigests[path]
      if (recorded === undefined) reasons.push(`input added: ${path}`)
      else if (current === undefined) {
        reasons.push(`input removed: ${path}`)
      } else if (recorded !== current) {
        reasons.push(`input changed: ${path}`)
      }
    }
  }
  const digests = marker['digests'] as
    | Readonly<Record<string, string>>
    | undefined
  if (
    digests !== undefined &&
    sha256(input.modelSource) !== digests['model.likec4']
  ) {
    reasons.push('model source changed')
  }
  if (reasons.length === 0) {
    return {
      exitCode: 0,
      stdout: 'Generated LikeC4 output: fresh\n',
      stderr: '',
    }
  }
  return {
    exitCode: 1,
    stdout:
      'Generated LikeC4 output: stale\n' +
      'Reason:\n' +
      reasons.map((reason) => `- ${reason}\n`).join('') +
      'Safe to regenerate: yes\n',
    stderr: '',
  }
}

export function runLikeC4Cli(
  args: readonly string[],
  cwd: string = process.cwd(),
): CliResult {
  if (args[0] === '--version') {
    return versionResult('yarramate-likec4')
  }
  if (args[0] === 'map') {
    return runLikeC4MapSync(args.slice(1), cwd)
  }
  const checkFreshness =
    args[0] === 'export-project' && args.includes('--check')
  const [command, projectionPath, mappingPath, ...options] = checkFreshness
    ? args.filter((argument) => argument !== '--check')
    : args
  let projectDefinitionMode = false
  if (
    (command === 'check' || command === 'export-project') &&
    projectionPath !== undefined
  ) {
    try {
      projectDefinitionMode =
        parseDocument(
          readFileSync(resolve(cwd, projectionPath), 'utf8'),
        ).get('format') === 'yarramate/likec4-project/v1'
    } catch {
      projectDefinitionMode = false
    }
  }
  const outputDirectory =
    command === 'export-project'
      ? projectDefinitionMode
        ? mappingPath
        : options[0]
      : undefined
  const sourceOptions =
    projectDefinitionMode && command === 'check'
      ? [mappingPath, ...options].filter(
          (value): value is string => value !== undefined,
        )
      : command === 'export-project'
      ? projectDefinitionMode
        ? options
        : options.slice(1)
      : options
  const json = command === 'check' && sourceOptions.includes('--json')
  let invalidOptions = false
  let kindMappingPath: string | undefined
  let comparison:
    | { readonly from: string; readonly to: string }
    | undefined
  let changedRange: string | undefined
  const sourcePaths: string[] = []
  for (let index = 0; index < sourceOptions.length; index += 1) {
    const option = sourceOptions[index]!
    if (option === '--json') {
      if (command !== 'check') invalidOptions = true
      continue
    }
    if (option === '--kinds') {
      const value = sourceOptions[index + 1]
      if (
        value === undefined ||
        value.startsWith('-') ||
        kindMappingPath !== undefined
      ) {
        invalidOptions = true
      } else {
        kindMappingPath = value
        index += 1
      }
      continue
    }
    if (option === '--changed') {
      const value = sourceOptions[index + 1]
      if (
        value === undefined ||
        value.startsWith('-') ||
        changedRange !== undefined
      ) {
        invalidOptions = true
      } else {
        changedRange = value
        index += 1
      }
      continue
    }
    if (option === '--compare') {
      const from = sourceOptions[index + 1]
      const to = sourceOptions[index + 2]
      if (
        from === undefined ||
        to === undefined ||
        from.startsWith('-') ||
        to.startsWith('-') ||
        comparison !== undefined
      ) {
        invalidOptions = true
      } else {
        comparison = { from, to }
        index += 2
      }
      continue
    }
    if (option.startsWith('-')) invalidOptions = true
    else sourcePaths.push(option)
  }
  if (
    (command !== 'check' &&
      command !== 'export' &&
      command !== 'export-project') ||
    projectionPath === undefined ||
    (!projectDefinitionMode && mappingPath === undefined) ||
    (projectDefinitionMode &&
      command === 'export-project' &&
      mappingPath === undefined) ||
    (command === 'export-project' && outputDirectory === undefined) ||
    (projectDefinitionMode &&
      (kindMappingPath !== undefined || comparison !== undefined)) ||
    (changedRange !== undefined &&
      !(projectDefinitionMode && command === 'export-project')) ||
    invalidOptions ||
    sourcePaths.length === 0 ||
    sourcePaths.some((argument) => argument.startsWith('-'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  const diagnosticOutput = (
    diagnostics: Parameters<typeof diagnosticJson>[0],
  ) =>
    json
      ? checkJson(false, diagnostics)
      : diagnosticJson(
          command === 'check'
            ? summarizeUnmappedSubjects(diagnostics)
            : diagnostics,
        )

  try {
    const resolved = resolveCliWorkspaceSources(sourcePaths, cwd)
    if (!resolved.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticOutput(resolved.diagnostics),
        stderr: '',
      }
    }
    const sources = resolved.paths.map((path) => ({
      path,
      source: readFileSync(resolve(cwd, path), 'utf8'),
    }))
    if (projectDefinitionMode) {
      const projectSource = {
        path: projectionPath,
        source: readFileSync(resolve(cwd, projectionPath), 'utf8'),
      }
      const projectDirectory = dirname(resolve(cwd, projectionPath))
      // The git-derived review overlay is the CLI's own: it needs a
      // repository. Everything after it runs the same pure pipeline the
      // path-free entry runs (ADR 0156).
      let gitChange
      if (changedRange !== undefined) {
        const modelDocuments = sources.flatMap((candidate) => {
          const parsed = parseDocument(candidate.source)
          if (parsed.get('format') !== 'yarramate/v1') return []
          const documentId = parsed.get('id')
          return typeof documentId === 'string'
            ? [{ ...candidate, documentId }]
            : []
        })
        const derived = deriveChangedSubjects(
          cwd,
          changedRange,
          modelDocuments,
        )
        if (!derived.ok) {
          return { exitCode: 2, stdout: '', stderr: `${derived.message}\n` }
        }
        const all = [
          ...derived.changed.concepts,
          ...derived.changed.relationships,
        ]
        gitChange = {
          range: derived.changed.range,
          added: derived.changed.added,
          modified: all.filter(
            (id) => !derived.changed.added.includes(id),
          ),
        }
      }
      const exported = exportLikeC4ProjectFromSources({
        project: projectSource,
        sources,
        readReference: (path) => {
          try {
            return {
              path,
              source: readFileSync(resolve(projectDirectory, path), 'utf8'),
            }
          } catch {
            return undefined
          }
        },
        requireMappedRelationships: command === 'check',
        ...(gitChange === undefined ? {} : { gitChange }),
      })
      if (!exported.ok) {
        return {
          exitCode: 1,
          stdout: diagnosticOutput(exported.diagnostics),
          stderr: '',
        }
      }
      if (command === 'check') {
        return {
          exitCode: 0,
          stdout: json
            ? checkJson(true, [])
            : `Checked LikeC4 project ${exported.projectIdentity}: no errors\n`,
          stderr: '',
        }
      }
      const inputDigests = inputDigestsOf(exported.inputs)
      if (checkFreshness) {
        return checkGeneratedProject(cwd, outputDirectory!, {
          modelSource: exported.modelSource,
          inputDigests,
        })
      }
      return publishGeneratedProject(cwd, outputDirectory!, {
        projectName: projectNameOf(exported.projectIdentity),
        title: exported.project.title,
        modelSource: exported.modelSource,
        ownership: { ...ownershipOf(exported) },
        inputDigests,
      })
    }
    const projectionSource = {
      path: projectionPath,
      source: readFileSync(resolve(cwd, projectionPath), 'utf8'),
    }
    const mappingSource = {
      path: mappingPath!,
      source: readFileSync(resolve(cwd, mappingPath!), 'utf8'),
    }
    const kindMappingSource =
      kindMappingPath === undefined
        ? undefined
        : {
            path: kindMappingPath,
            source: readFileSync(resolve(cwd, kindMappingPath), 'utf8'),
          }
    const prepared = prepareLikeC4Export({
      sources,
      projection: projectionSource,
      subjectMapping: mappingSource,
      ...(kindMappingSource === undefined
        ? {}
        : { kindMapping: kindMappingSource }),
      ...(comparison === undefined ? {} : { comparison }),
      vocabulary: command === 'export' ? 'consumer' : 'bundled',
      requireMappedRelationships: command === 'check',
    })
    if (!prepared.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticOutput(prepared.diagnostics),
        stderr: '',
      }
    }
    if (command === 'check') {
      return {
        exitCode: 0,
        stdout: json
          ? checkJson(true, [])
          : `Checked LikeC4 export ${prepared.projection.projection}: no errors\n`,
        stderr: '',
      }
    }
    if (command === 'export') {
      return { exitCode: 0, stdout: prepared.source, stderr: '' }
    }

    const projectionIdentity = prepared.projection.projection
    const mappingIdentity = `${prepared.subjectMapping.id}@${prepared.subjectMapping.version}`
    const kindMappingIdentity =
      prepared.kindMapping === undefined
        ? undefined
        : `${prepared.kindMapping.id}@${prepared.kindMapping.version}`
    const comparisonIdentity = comparison
    const inputDigests = inputDigestsOf([
      projectionSource,
      mappingSource,
      ...(kindMappingSource === undefined ? [] : [kindMappingSource]),
      ...sources,
    ])
    if (checkFreshness) {
      return checkGeneratedProject(cwd, outputDirectory!, {
        modelSource: prepared.source,
        inputDigests,
      })
    }
    return publishGeneratedProject(cwd, outputDirectory!, {
      projectName: ['yarramate', projectionIdentity]
        .join('-')
        .replaceAll(/[^A-Za-z0-9_-]/g, '-'),
      title:
        prepared.projection.presentation?.title ??
        projectionIdentity.slice(0, projectionIdentity.lastIndexOf('@')),
      modelSource: prepared.source,
      ownership: {
        format: 'yarramate/likec4-generated-project/v1',
        projection: projectionIdentity,
        mapping: mappingIdentity,
        ...(kindMappingIdentity === undefined
          ? {}
          : { kindMapping: kindMappingIdentity }),
        ...(comparisonIdentity === undefined
          ? {}
          : { comparison: comparisonIdentity }),
      },
      inputDigests,
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

if (isMainModule(import.meta.url, process.argv[1])) {
  const result = runLikeC4Cli(process.argv.slice(2))
  process.stdout.write(result.stdout)
  process.stderr.write(result.stderr)
  process.exitCode = result.exitCode
}

import { globSync, realpathSync, statSync } from 'node:fs'
import { dirname, relative, resolve, sep } from 'node:path'
import type { WorkspaceSource } from './compiler.js'
import { resolveManifest } from './workspace-resolution.js'

// The manifest's validation, pattern arithmetic and diagnostics live in
// `workspace-resolution.ts`, which imports no Node built-in; this module is
// the one caller that resolves a manifest's globs against a real filesystem
// and so is never bundled. `resolveWorkspaceFrom` in the same module is the
// same resolution over a store's file list (ADR 0156).
export type {
  ResolvedWorkspace,
  WorkspaceManifest,
  WorkspaceManifestResult,
} from './workspace-resolution.js'

export function loadWorkspaceManifest(
  source: WorkspaceSource,
  cwd: string,
) {
  const base = dirname(resolve(cwd, source.path))
  const realBase = realpathSync(base)
  return resolveManifest(source, (pattern) =>
    globSync(pattern, { cwd: base })
      .filter((path) => statSync(resolve(base, path)).isFile())
      .map((path) => {
        const realMatch = realpathSync(resolve(base, path))
        const withinBase =
          realMatch === realBase || realMatch.startsWith(`${realBase}${sep}`)
        return {
          path: relative(cwd, resolve(base, path)).split(sep).join('/'),
          identity: realMatch,
          ...(withinBase ? {} : { outside: true as const }),
        }
      }),
  )
}

#!/usr/bin/env node

import { join } from 'node:path'
import { isMainModule, versionResult, type CliResult } from '../cli-support.js'
import {
  fetchVisualStatus,
  readVisualJsonDocument,
  readVisualSessionDescriptor,
  recoverVisualSessionClient,
  sendVisualResponse,
  stopVisualSessionClient,
  visualClientDiagnostic,
  visualFailureDiagnostics,
  visualSessionAlreadyStopped,
  waitForVisualEvent,
} from './visual/client.js'
import {
  parseVisualResponse,
  parseVisualSessionRequest,
  type VisualDiagnostic,
  type VisualTerminationReason,
} from './visual/protocol.js'
import { buildVisualSessionRequest } from './visual/request.js'
import { startVisualServer } from './visual/session-server.js'
import { pruneStaleVisualSessions } from './visual/session-store.js'

export const visualUsage =
  'Usage:\n' +
  '  yarramate-visual request [--view <id>] [--title <text>]\n' +
  '                           [--description <text>] [--chat]\n' +
  '  yarramate-visual start <request.json>\n' +
  '  yarramate-visual wait <descriptor-uri> [--after <sequence>]\n' +
  '  yarramate-visual respond <descriptor-uri> <response.json>\n' +
  '  yarramate-visual status <descriptor-uri>\n' +
  '  yarramate-visual recover <descriptor-uri> [--transcript]\n' +
  '  yarramate-visual stop <descriptor-uri> [--transcript]\n' +
  '\n' +
  '<descriptor-uri> is the `descriptorPath` file: URI `start` published,\n' +
  'copied back verbatim. It is never resolved against the working directory.\n' +
  '  yarramate-visual --version\n'

/**
 * Where a repository keeps its live sessions, one directory per session. It sits
 * under the ignored build directory because a session is runtime state: never
 * canonical, never committed, and pruned by the next start.
 */
export const VISUAL_SESSION_DIRECTORY = join('.yarramate-out', 'visual')

/** Terminations that mean the session did not end the way it was asked to. */
const FAILED_TERMINATION: Readonly<
  Partial<Record<VisualTerminationReason, true>>
> = {
  'child-failed': true,
  'browser-timeout': true,
  'server-failed': true,
  'compiler-failed': true,
}

const usageResult: CliResult = {
  exitCode: 2,
  stdout: '',
  stderr: visualUsage,
}

/**
 * One document per line: every command an agent drives writes at most one
 * versioned document, so a caller reads exactly one line per invocation.
 */
const documentLine = (value: unknown) => `${JSON.stringify(value)}\n`

/**
 * Stdout carries the document that was asked for and nothing else, so a refusal
 * goes to stderr where it cannot be mistaken for an answer.
 */
const refusalResult = (
  diagnostics: readonly VisualDiagnostic[],
): CliResult => ({
  exitCode: 1,
  stdout: '',
  stderr: documentLine({
    format: 'yarramate/visual-diagnostic-result/v1',
    diagnostics,
  }),
})

/** Sequences are counted, so only a plain non-negative integer is one. */
const sequenceFlag = (rest: readonly string[]): number | undefined => {
  if (rest.length === 0) return 0
  const [flag, value] = rest
  if (flag !== '--after' || value === undefined || rest.length !== 2) {
    return undefined
  }
  if (!/^(?:0|[1-9][0-9]*)$/.test(value)) return undefined
  const sequence = Number(value)
  return Number.isSafeInteger(sequence) ? sequence : undefined
}

const transcriptFlag = (rest: readonly string[]): boolean | undefined =>
  rest.length === 0
    ? false
    : rest.length === 1 && rest[0] === '--transcript'
      ? true
      : undefined

interface RequestFlags {
  readonly view: string | undefined
  readonly title: string | undefined
  readonly description: string | undefined
  readonly chatEnabled: boolean
}

/**
 * Strict because the document this builds is a session's whole input: a
 * misspelled flag that was silently ignored would open a session on the wrong
 * view, or with chat off when the caller asked for it. A repeated flag is a
 * caller that means two things at once, and a value beginning with `--` is a
 * missing value rather than a title, so both refuse with usage.
 */
const requestFlags = (rest: readonly string[]): RequestFlags | undefined => {
  let view: string | undefined
  let title: string | undefined
  let description: string | undefined
  let chatEnabled = false
  for (let index = 0; index < rest.length; index += 1) {
    const flag = rest[index]
    if (flag === '--chat') {
      if (chatEnabled) return undefined
      chatEnabled = true
      continue
    }
    const value = rest[index + 1]
    if (value === undefined || value.startsWith('--')) return undefined
    index += 1
    if (flag === '--view' && view === undefined) view = value
    else if (flag === '--title' && title === undefined) title = value
    else if (flag === '--description' && description === undefined) {
      description = value
    } else return undefined
  }
  return { view, title, description, chatEnabled }
}

/**
 * Transcribes the workspace into the request document `start` consumes. It is
 * the only visual command that reads the repository rather than a session:
 * every other one addresses a descriptor, and this one runs before a session
 * exists.
 */
const requestCliCommand = (
  rest: readonly string[],
  cwd: string,
): CliResult => {
  const flags = requestFlags(rest)
  if (flags === undefined) return usageResult
  const built = buildVisualSessionRequest({
    cwd,
    initialView: flags.view,
    title: flags.title,
    description: flags.description,
    chatEnabled: flags.chatEnabled,
  })
  if (!built.ok) return refusalResult(built.diagnostics)
  return { exitCode: 0, stdout: documentLine(built.request), stderr: '' }
}

const waitCliCommand = async (
  descriptorUri: string,
  rest: readonly string[],
): Promise<CliResult> => {
  const after = sequenceFlag(rest)
  if (after === undefined) return usageResult
  const descriptor = await readVisualSessionDescriptor(descriptorUri)
  if (!descriptor.ok) return refusalResult(descriptor.diagnostics)
  const delivery = await waitForVisualEvent(descriptor.value, after)
  if (!delivery.ok) return refusalResult(delivery.diagnostics)
  return {
    exitCode: 0,
    // An idle window is not a failure and has no document: the caller polls
    // again from the sequence it already knows.
    stdout: delivery.value.waiting ? '' : documentLine(delivery.value.event),
    stderr: '',
  }
}

const respondCliCommand = async (
  descriptorUri: string,
  rest: readonly string[],
  cwd: string,
): Promise<CliResult> => {
  const [responsePath, ...trailing] = rest
  if (responsePath === undefined || trailing.length > 0) return usageResult
  const descriptor = await readVisualSessionDescriptor(descriptorUri)
  if (!descriptor.ok) return refusalResult(descriptor.diagnostics)
  // The response document is the agent's own file, named however the agent
  // likes: it is not a protocol path field, so it stays a native path
  // resolved against `cwd`.
  const document = await readVisualJsonDocument(responsePath, cwd)
  if (!document.ok) return refusalResult(document.diagnostics)
  // Validated here as well as by the runtime, so an invalid response never
  // reaches the session at all.
  const response = parseVisualResponse(document.value)
  if (!response.ok) return refusalResult(response.diagnostics)
  const accepted = await sendVisualResponse(descriptor.value, response.value)
  if (!accepted.ok) return refusalResult(accepted.diagnostics)
  return { exitCode: 0, stdout: documentLine(accepted.value), stderr: '' }
}

const statusCliCommand = async (
  descriptorUri: string,
  rest: readonly string[],
): Promise<CliResult> => {
  if (rest.length > 0) return usageResult
  const descriptor = await readVisualSessionDescriptor(descriptorUri)
  if (!descriptor.ok) return refusalResult(descriptor.diagnostics)
  const status = await fetchVisualStatus(descriptor.value)
  if (!status.ok) return refusalResult(status.diagnostics)
  return { exitCode: 0, stdout: documentLine(status.value), stderr: '' }
}

const recoverCliCommand = async (
  descriptorUri: string,
  rest: readonly string[],
): Promise<CliResult> => {
  const includeTranscript = transcriptFlag(rest)
  if (includeTranscript === undefined) return usageResult
  const descriptor = await readVisualSessionDescriptor(descriptorUri)
  if (!descriptor.ok) return refusalResult(descriptor.diagnostics)
  const handoff = await recoverVisualSessionClient(
    descriptor.value,
    includeTranscript,
  )
  if (!handoff.ok) return refusalResult(handoff.diagnostics)
  return { exitCode: 0, stdout: documentLine(handoff.value), stderr: '' }
}

/**
 * Converges the session on stopped, and says so however many times it is asked.
 * The design's failure table requires a repeated stop to report the
 * already-stopped state, and the first stop takes the descriptor with the
 * session root, so the second invocation has nothing left to read. That one
 * shape — descriptor and session root both gone — reports the same benign
 * already-stopped result the client returns for a retained descriptor: exit 0,
 * no handoff document, because there is no session left to hand off.
 *
 * Every other unreadable descriptor still refuses. Nothing weakens: no
 * credential is retained, no directory is removed on the strength of a
 * descriptor that did not parse, and a corrupt, redirected, or foreign
 * descriptor fails exactly as before.
 */
const stopCliCommand = async (
  descriptorUri: string,
  rest: readonly string[],
): Promise<CliResult> => {
  const includeTranscript = transcriptFlag(rest)
  if (includeTranscript === undefined) return usageResult
  const descriptor = await readVisualSessionDescriptor(descriptorUri)
  if (!descriptor.ok) {
    return (await visualSessionAlreadyStopped(descriptorUri))
      ? { exitCode: 0, stdout: '', stderr: '' }
      : refusalResult(descriptor.diagnostics)
  }
  const stopped = await stopVisualSessionClient(
    descriptor.value,
    includeTranscript,
  )
  if (!stopped.ok) return refusalResult(stopped.diagnostics)
  return {
    exitCode: 0,
    // A session that was already gone has no handoff left to publish.
    stdout: stopped.value === undefined ? '' : documentLine(stopped.value),
    stderr: '',
  }
}

/**
 * Every command an agent can run to completion. `start` is not one of them: it
 * blocks for the life of the session and is dispatched by `runVisualCli`.
 *
 * `request` is the one verb that takes no descriptor - it runs before any
 * session exists - so it is dispatched ahead of the descriptor requirement.
 */
export async function runVisualClientCli(
  args: readonly string[],
  cwd: string = process.cwd(),
): Promise<CliResult> {
  const [command, descriptor, ...rest] = args
  if (command === '--version') return versionResult('yarramate-visual')
  if (command === 'request') return requestCliCommand(args.slice(1), cwd)
  if (descriptor === undefined) return usageResult
  // `cwd` reaches only the commands that still read a native path of their
  // own. The descriptor argument is a `file:` URI and is never resolved
  // against anything.
  switch (command) {
    case 'wait':
      return waitCliCommand(descriptor, rest)
    case 'respond':
      return respondCliCommand(descriptor, rest, cwd)
    case 'status':
      return statusCliCommand(descriptor, rest)
    case 'recover':
      return recoverCliCommand(descriptor, rest)
    case 'stop':
      return stopCliCommand(descriptor, rest)
    default:
      return usageResult
  }
}

/** Where a foreground session publishes, and where it observes its signals. */
export interface VisualSignalSource {
  on(signal: 'SIGINT' | 'SIGTERM', listener: () => void): unknown
  off(signal: 'SIGINT' | 'SIGTERM', listener: () => void): unknown
}

export interface VisualStartIo {
  readonly stdout: (chunk: string) => void
  readonly stderr: (chunk: string) => void
  /** Defaults to the process itself. */
  readonly signals?: VisualSignalSource
}

const processIo: VisualStartIo = {
  stdout: (chunk) => void process.stdout.write(chunk),
  stderr: (chunk) => void process.stderr.write(chunk),
}

/**
 * Serves one visual session in the foreground.
 *
 * The request is validated before any filesystem or network effect, so a bad
 * document costs nothing. Exactly one public `visual-session-started/v2` line is
 * published before the command blocks — it names the private descriptor but
 * never carries the agent capability, which lives only in that mode 0600 file.
 * The command then holds the session open until the runtime closes it, whether
 * that is a signal, an agent stop, or a runtime failure; the runtime recovers
 * the handoff before it removes the session in every one of those cases.
 */
export const runVisualStart = async (
  requestPath: string,
  cwd: string = process.cwd(),
  io: VisualStartIo = processIo,
): Promise<CliResult> => {
  const document = await readVisualJsonDocument(requestPath, cwd)
  if (!document.ok) return refusalResult(document.diagnostics)
  const request = parseVisualSessionRequest(document.value)
  if (!request.ok) return refusalResult(request.diagnostics)

  const baseDir = join(cwd, VISUAL_SESSION_DIRECTORY)
  const signals = io.signals ?? process
  let handle
  try {
    // A previous runtime's orphans are collected on the critical path of a new
    // session, bounded per pass so a full directory cannot stall this one.
    await pruneStaleVisualSessions(baseDir, new Date())
    handle = await startVisualServer({ request: request.value, baseDir, cwd })
  } catch (cause) {
    // A failed start has already recovered and removed whatever it created.
    return refusalResult(visualFailureDiagnostics(cause))
  }

  io.stdout(documentLine(handle.started))

  // One handler for both signals: `stop` converges on the first reason it is
  // given, so a repeated or second signal is absorbed rather than racing.
  //
  // A signal is not a caller, and nothing here awaits the teardown it starts:
  // a stop that fails is observed rather than left to reach the runtime as an
  // unhandled rejection and take the whole session down with it. What it could
  // not tear down is still up, this command is still blocked on `closed`, and
  // the next signal runs the teardown again.
  const interrupt = () => {
    void handle.stop('main-cancelled').catch(() => undefined)
  }
  signals.on('SIGINT', interrupt)
  signals.on('SIGTERM', interrupt)
  try {
    const closed = await handle.closed
    // The recovered handoff is what the journal says happened; the reason the
    // stop asked for is only what someone wanted. A session the reviewer ended
    // is a success even when a cancelling agent is what closed the server, and
    // a child that died before its handoff is a failure even when it did not.
    const outcome = closed.handoff?.terminationReason ?? closed.reason
    return FAILED_TERMINATION[outcome] === true
      ? refusalResult([
          visualClientDiagnostic(
            'YMVS409',
            `Visual session ${handle.started.sessionId} ended with termination reason "${outcome}"`,
          ),
        ])
      : { exitCode: 0, stdout: '', stderr: '' }
  } finally {
    signals.off('SIGINT', interrupt)
    signals.off('SIGTERM', interrupt)
  }
}

/**
 * The whole binary: `start` blocks and streams its one document through `io`,
 * every other command runs to completion and returns its document.
 */
export const runVisualCli = async (
  args: readonly string[],
  cwd: string = process.cwd(),
  io: VisualStartIo = processIo,
): Promise<CliResult> => {
  if (args[0] !== 'start') return runVisualClientCli(args, cwd)
  const requestPath = args[1]
  if (requestPath === undefined || args.length !== 2) return usageResult
  return runVisualStart(requestPath, cwd, io)
}

if (isMainModule(import.meta.url, process.argv[1])) {
  void runVisualCli(process.argv.slice(2)).then((result) => {
    process.stdout.write(result.stdout)
    process.stderr.write(result.stderr)
    process.exitCode = result.exitCode
  })
}

