      "properties": {
        "likec4.config.json": {
          "$ref": "#/$defs/sha256"
        },
        "model.likec4": {
          "$ref": "#/$defs/sha256"
        },
        "specification.likec4": {
          "$ref": "#/$defs/sha256"
        }
      }
    },
    "inputDigests": {
      "type": "object",
