const CONCEPT_KIND_PREDICATE = 'yarramate/concept/kind'
const CONCEPT_NAME_PREDICATE = 'yarramate/concept/name'
const CONCEPT_DESCRIPTION_PREDICATE = 'yarramate/concept/description'
const CONCEPT_ALIAS_PREDICATE = 'yarramate/concept/alias'
const LIFECYCLE_STATUS_PREDICATE = 'yarramate/lifecycle/status'
const IDENTITY_DISTINCT_FROM_PREDICATE = 'yarramate/identity/distinct-from'
const LINEAGE_SUPERSEDES_PREDICATE = 'yarramate/lineage/supersedes'
const OWNERSHIP_OWNER_PREDICATE = 'yarramate/ownership/owner'
const ORGANISATION_FOLDER_PREDICATE = 'yarramate/organisation/folder'
const CONSTRAINT_REQUIRES_PREDICATE = 'yarramate/constraint/requires'
const REFERENCE_REFERS_TO_PREDICATE = 'yarramate/reference/refers-to'
const STATE_PRESENT_IN_PREDICATE = 'yarramate/state/present-in'

const RELATIONSHIP_NAME_PREDICATE = 'yarramate/relationship/name'
const RELATIONSHIP_DESCRIPTION_PREDICATE = 'yarramate/relationship/description'
const ACCESS_MODE_PREDICATE = 'yarramate/access/mode'
const FLOW_CONTENT_PREDICATE = 'yarramate/flow/content'

// This is compiler-internal data: every claim's object narrows deterministically
// by predicate. A mismatch means a real bug upstream in src/compiler.ts, not
// malformed input this function should tolerate — so it throws rather than
// silently coercing to an empty string.
const claimValue = (claim: GraphClaim): string => {
  if ('value' in claim.object) {
    return claim.object.value
  }
  throw new Error(
    `Expected a value-typed object for claim "${claim.id}" (subject "${claim.subject}", predicate "${claim.predicate}"), got a ref-typed object`,
  )
}

const claimRef = (claim: GraphClaim): string => {
  if ('ref' in claim.object) {
    return claim.object.ref
  }
  throw new Error(
    `Expected a ref-typed object for claim "${claim.id}" (subject "${claim.subject}", predicate "${claim.predicate}"), got a value-typed object`,
  )
}

// The compiler qualifies every subject id as `<document id>#<authored id>`
// (`qualifyReference` in src/compiler.ts), and a document's authored ids never
// contain `#`. An operation addresses a subject by the id someone wrote in the
// file, not by the qualified identity the compile derived, so the projection
// carries both rather than leaving the browser to re-derive one from the other.
const authoredIdOf = (subjectId: string): string => {
  const boundary = subjectId.indexOf('#')
  return boundary === -1 ? subjectId : subjectId.slice(boundary + 1)
}

const compareById = <T extends { readonly id: string }>(left: T, right: T) =>
  left.id.localeCompare(right.id)

const groupClaimsBySubject = (
  claims: readonly GraphClaim[],
): Map<string, GraphClaim[]> => {
  const groups = new Map<string, GraphClaim[]>()
  for (const claim of claims) {
    const group = groups.get(claim.subject)
    if (group === undefined) {
      groups.set(claim.subject, [claim])
    } else {
      group.push(claim)
    }
  }
  return groups
}

const projectConcept = (
  subjectId: string,
  claims: readonly GraphClaim[],
  profileContext: ResolvedProfileContext,
): CanvasNode => {
  const kindClaim = claims.find((claim) => claim.predicate === CONCEPT_KIND_PREDICATE)
  if (kindClaim === undefined) {
    throw new Error(
      `Concept "${subjectId}" is missing its required yarramate/concept/kind claim`,
    )
  }
  const kind = claimValue(kindClaim)

  const nameClaim = claims.find((claim) => claim.predicate === CONCEPT_NAME_PREDICATE)
  if (nameClaim === undefined) {
    throw new Error(
      `Concept "${subjectId}" is missing its required yarramate/concept/name claim`,
    )
  }

  const descriptionClaim = claims.find(
    (claim) => claim.predicate === CONCEPT_DESCRIPTION_PREDICATE,
  )
  const statusClaim = claims.find((claim) => claim.predicate === LIFECYCLE_STATUS_PREDICATE)
  const ownerClaim = claims.find((claim) => claim.predicate === OWNERSHIP_OWNER_PREDICATE)
  const folderClaim = claims.find(
    (claim) => claim.predicate === ORGANISATION_FOLDER_PREDICATE,
  )

  const constraints = claims
    .filter((claim) => claim.predicate === CONSTRAINT_REQUIRES_PREDICATE)
    .map((requiresClaim) => {
      // The constraint's local id lives between the `~constraint-` marker
      // and the end of the requires claim's own id; the paired expects
      // claim (if the constraint declared one) reuses that same local id
      // under a `~expects-` marker in the same claim group.
      const localId = requiresClaim.id.split('~constraint-')[1]
      if (localId === undefined) {
        throw new Error(
          `Constraint claim "${requiresClaim.id}" on concept "${subjectId}" does not follow the "<subject>~constraint-<id>" id convention`,
        )
      }
      const expectsClaim = claims.find(
        (claim) => claim.id === `${subjectId}~expects-${localId}`,
      )
      let expects: { readonly provider: string; readonly key: string; readonly value: string } | null
      if (expectsClaim === undefined) {
        expects = null
      } else {
        const parsed = parseConstraintExpectsValue(claimValue(expectsClaim))
        if (parsed === undefined) {
          throw new Error(
            `Constraint expects claim "${expectsClaim.id}" on concept "${subjectId}" does not follow the "provider key value" encoding`,
          )
        }
        expects = parsed
      }
      return {
        id: localId,
        ref: claimRef(requiresClaim),
        expects,
      }
    })

  const attestations = claims
    .filter((claim) => claim.predicate.startsWith(ATTESTATION_PREDICATE_PREFIX))
    .map((claim) => {
      const parsed = parseAttestationClaimValue(claimValue(claim))
      if (parsed === undefined) {
        throw new Error(
          `Attestation claim "${claim.id}" on concept "${subjectId}" does not follow the "by on [recordedBy]" encoding`,
        )
      }
      return {
        topic: claim.predicate.slice(ATTESTATION_PREDICATE_PREFIX.length),
        by: parsed.by,
        on: parsed.on,
        recordedBy: parsed.recordedBy ?? null,
      }
    })

  return {
    id: subjectId,
    localId: authoredIdOf(subjectId),
    document: kindClaim.source.path,
    kind,
    kindLabel: kindLabelOf(kind),
    coreKindLabel: kindLabelOf(
      profileContext.conceptKindLineages.get(kind)?.[0] ?? kind,
    ),
    portKinds: profileContext.patternPortKinds.get(kind) ?? [],
    layer: (profileContext.conceptKindLayers.get(kind) as Layer | undefined) ?? null,
    aspect: (profileContext.conceptKindAspects.get(kind) as Aspect | undefined) ?? null,
    name: claimValue(nameClaim),
    description: descriptionClaim === undefined ? null : claimValue(descriptionClaim),
    aka: claims
      .filter((claim) => claim.predicate === CONCEPT_ALIAS_PREDICATE)
      .map(claimValue)
      .sort(),
    status: statusClaim === undefined ? null : claimValue(statusClaim),
    owner: ownerClaim === undefined ? null : claimRef(ownerClaim),
    folder: folderClaim === undefined ? null : claimValue(folderClaim),
    distinctFrom: claims
      .filter((claim) => claim.predicate === IDENTITY_DISTINCT_FROM_PREDICATE)
      .map(claimRef)
      .sort(),
    supersedes: claims
      .filter((claim) => claim.predicate === LINEAGE_SUPERSEDES_PREDICATE)
      .map(claimRef)
      .sort(),
    constraints,
    references: claims
      .filter((claim) => claim.predicate === REFERENCE_REFERS_TO_PREDICATE)
      .map((referencesClaim) => {
        const localId = referencesClaim.id.split('~reference-')[1]
        if (localId === undefined) {
          throw new Error(
            `Reference claim "${referencesClaim.id}" on concept "${subjectId}" does not follow the "<subject>~reference-<id>" id convention`,
          )
        }
        return {
          id: localId,
          ref: claimRef(referencesClaim),
        }
      })
      .sort((left, right) => left.ref.localeCompare(right.ref)),
    presentIn: claims
      .filter((claim) => claim.predicate === STATE_PRESENT_IN_PREDICATE)
      .map(claimRef)
      .sort(),
    attestations,
  }
}

const projectRelationship = (
  relationshipId: string,
  allClaims: readonly GraphClaim[],
  ownClaims: readonly GraphClaim[],
  profileContext: ResolvedProfileContext,
  conceptKindOf: ReadonlyMap<string, string> = new Map(),
): CanvasEdge => {
  // A relationship's defining claim is asymmetric: its id is the
  // relationship's subject id, but its own `subject` field is the
  // from-concept, so it lives in the from-concept's claim group, not this
  // relationship's — it has to be found by scanning every claim.
  const definingClaim = allClaims.find((claim) => claim.id === relationshipId)
  if (definingClaim === undefined) {
    throw new Error(`Relationship "${relationshipId}" is missing its defining claim`)
  }
  const kind = definingClaim.predicate
  const lineage = profileContext.relationshipKindLineages.get(kind)
  const coreKindLabel = kindLabelOf(lineage?.[0] ?? kind)
  const endpointLineage = (subject: string): readonly string[] | undefined => {
    const conceptKind = conceptKindOf.get(subject)
    return conceptKind === undefined
      ? undefined
      : profileContext.conceptKindLineages.get(conceptKind)
  }
  const reading = contextualReading(
    endpointLineage(definingClaim.subject),
    endpointLineage(claimRef(definingClaim)),
    coreKindLabel,
  )

  const nameClaim = ownClaims.find((claim) => claim.predicate === RELATIONSHIP_NAME_PREDICATE)
  const descriptionClaim = ownClaims.find(
    (claim) => claim.predicate === RELATIONSHIP_DESCRIPTION_PREDICATE,
  )
  const modeClaim = ownClaims.find((claim) => claim.predicate === ACCESS_MODE_PREDICATE)
  const contentClaim = ownClaims.find((claim) => claim.predicate === FLOW_CONTENT_PREDICATE)
  const statusClaim = ownClaims.find((claim) => claim.predicate === LIFECYCLE_STATUS_PREDICATE)

  return {
    id: relationshipId,
    localId: authoredIdOf(relationshipId),
    document: definingClaim.source.path,
    kind,
    kindLabel: kindLabelOf(kind),
    coreKindLabel,
    readingKind: readingKindOf(lineage, coreKindLabel),
    responsibility: responsibilityLetterOf(lineage, kind),
    ...(reading === undefined ? {} : { reading }),
    from: definingClaim.subject,
    to: claimRef(definingClaim),
    name: nameClaim === undefined ? null : claimValue(nameClaim),
    description: descriptionClaim === undefined ? null : claimValue(descriptionClaim),
    mode: modeClaim === undefined ? null : claimValue(modeClaim),
    content: contentClaim === undefined ? null : claimValue(contentClaim),
    status: statusClaim === undefined ? null : claimValue(statusClaim),
    references: ownClaims
      .filter((claim) => claim.predicate === REFERENCE_REFERS_TO_PREDICATE)
      .map((referencesClaim) => {
        const localId = referencesClaim.id.split('~reference-')[1]
        if (localId === undefined) {
          throw new Error(
            `Reference claim "${referencesClaim.id}" on relationship "${relationshipId}" does not follow the "<subject>~reference-<id>" id convention`,
          )
        }
        return {
          id: localId,
          ref: claimRef(referencesClaim),
        }
      })
      .sort((left, right) => left.ref.localeCompare(right.ref)),
    presentIn: ownClaims
      .filter((claim) => claim.predicate === STATE_PRESENT_IN_PREDICATE)
      .map(claimRef)
      .sort(),
  }
}

export function projectGraphForCanvas(
  graph: SemanticGraph,
  profileContext: ResolvedProfileContext,
): CanvasGraph {
  const claimsBySubject = groupClaimsBySubject(graph.claims)
  // Each concept's authored kind, for the readings an edge's endpoints decide.
  const conceptKindOf = new Map<string, string>()
  for (const claim of graph.claims) {
    if (claim.predicate === CONCEPT_KIND_PREDICATE && 'value' in claim.object) {
      conceptKindOf.set(claim.subject, claim.object.value)
    }
  }

  const nodes: CanvasNode[] = []
  const edges: CanvasEdge[] = []

  for (const subject of graph.subjects) {
    const ownClaims = claimsBySubject.get(subject.id) ?? []
    if (subject.type === 'concept') {
      nodes.push(projectConcept(subject.id, ownClaims, profileContext))
    } else {
      edges.push(
        projectRelationship(subject.id, graph.claims, ownClaims, profileContext, conceptKindOf),
      )
    }
  }

  nodes.sort(compareById)
  edges.sort(compareById)

  return { nodes, edges }
}

/**
 * White-labelling (#546, ADR 0158): one value, set once by a host, that
 * names the product on every surface a consumer's users see - the editor
 * shell, the tool list an agent reads, the workbook's cover sheet and the
 * LikeC4 banner. Nothing else changes: record formats, diagnostic codes and
 * the wire protocol are contracts, not branding, and stay `yarramate/...`
 * and `YM...`. Absent, every surface reads exactly as it always has.
 *
 * Pure: no imports, so it sits under every entry (`yarramate/tools`,
 * `yarramate/workbook`, `yarramate/visual-app`) without weight.
 */

export type BrandingLogo =
  /** Inline markup the host wrote; rendered as the host's own SVG. */
  | { readonly svg: string }
  /** An address the page fetches; rendered as an image. */
  | { readonly url: string }

export interface Branding {
  /** "ApertureX", "Halcyon Architecture". Required: a brand without a name is not one. */
  readonly productName: string
  /**
   * For tight chrome: beside the logo in the brand mark, and in the
   * authority line ("Checked Halcyon model"). Defaults to `productName`.
   * `null` draws the logo alone, for a wordmark that already says the name.
   */
  readonly shortName?: string | null
  /** Beside the title in the editor shell. Nothing is drawn without one. */
  readonly logo?: BrandingLogo
  /**
   * One CSS colour for the chrome - the authority mark, the notices, the
   * changeset controls - never the notation: what a node or an edge looks
   * like is the style preset's, and a comparison's added/removed marks keep
   * their own tokens.
   */
  readonly accent?: string
  /** Where the brand mark links. Without it the mark is text, not a link. */
  readonly docsUrl?: string
  /**
   * The line under the product name, on the editor strip, the workbook's
   * cover sheet and the LikeC4 banner. Unset: "Powered by yarramate". A
   * string replaces it; `null` removes it, and with it every other mention
   * of the engine those surfaces make.
   */
  readonly vendorLine?: string | null
  /**
   * The prefix of the tool names an agent reads: `acme` publishes
   * `acme_design`, `acme_apply`, ... Default `yarramate`. An instruction
   * written for `yarramate_design` will not find `acme_design`, so a host
   * that re-prefixes owns its own agent instructions.
   */
  readonly toolPrefix?: string
}

/** `Branding` with every default applied, which is what the surfaces read. */
export interface ResolvedBranding {
  readonly productName: string
  /** `null` when the mark is the logo alone; the authority line then says `productName`. */
  readonly shortName: string | null
  readonly logo?: BrandingLogo
  readonly accent?: string
  readonly docsUrl?: string
  /** `null` when there is none to show. */
  readonly vendorLine: string | null
  readonly toolPrefix: string
  /** False is the unbranded product: every surface as it was before #546. */
  readonly branded: boolean
}

export const YARRAMATE_PRODUCT_NAME = 'YarraMate'
export const YARRAMATE_TOOL_PREFIX = 'yarramate'
export const DEFAULT_VENDOR_LINE = 'Powered by yarramate'

/** What an MCP client accepts in a tool name, applied to the prefix alone. */
const TOOL_PREFIX = /^[A-Za-z0-9][A-Za-z0-9-]*$/

const UNBRANDED: ResolvedBranding = {
  productName: YARRAMATE_PRODUCT_NAME,
  shortName: YARRAMATE_PRODUCT_NAME,
  vendorLine: null,
  toolPrefix: YARRAMATE_TOOL_PREFIX,
  branded: false,
}

/**
 * Applies the defaults. `undefined` is the unbranded product. A value with
 * a blank `productName` or a `toolPrefix` no MCP client could publish is a
 * host's configuration error and throws, at mount or serve time, rather
 * than reaching a person as a blank name or an agent as a broken tool list.
 */
export const resolveBranding = (branding?: Branding): ResolvedBranding => {
  if (branding === undefined) return UNBRANDED
  const productName = branding.productName.trim()
  if (productName === '') {
    throw new TypeError('branding.productName must not be blank')
  }
  const toolPrefix = branding.toolPrefix ?? YARRAMATE_TOOL_PREFIX
  if (!TOOL_PREFIX.test(toolPrefix)) {
    throw new TypeError(
      `branding.toolPrefix "${toolPrefix}" must be letters, digits and hyphens, starting with a letter or digit`,
    )
  }
  const shortName =
    branding.shortName === null ? null : branding.shortName?.trim()
  const vendorLine =
    branding.vendorLine === undefined
      ? DEFAULT_VENDOR_LINE
      : branding.vendorLine === null || branding.vendorLine.trim() === ''
        ? null
        : branding.vendorLine.trim()
  return {
    productName,
    shortName:
      shortName === null
        ? null
        : shortName === undefined || shortName === ''
          ? productName
          : shortName,
    ...(branding.logo === undefined ? {} : { logo: branding.logo }),
    ...(branding.accent === undefined ? {} : { accent: branding.accent }),
    ...(branding.docsUrl === undefined ? {} : { docsUrl: branding.docsUrl }),
    vendorLine,
    toolPrefix,
    branded: true,
  }
}

/**
 * The product name as an identifier segment: the LikeC4 project name is
 * `<slug>-<project id>`, `yarramate-…` unbranded. Lower-case letters,
 * digits and single hyphens; a name with nothing usable in it falls back
 * to the engine's own slug rather than producing an empty segment.
 */
export const brandSlug = (branding: ResolvedBranding): string => {
  if (!branding.branded) return YARRAMATE_TOOL_PREFIX
  // Split on the runs and join what is left: linear, where a trim by
  // `^-+|-+$` is polynomial on a name that is mostly hyphens (CodeQL
  // js/polynomial-redos, the rule that bit #547's walker too).
  const slug = (branding.shortName ?? branding.productName)
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((part) => part !== '')
    .join('-')
  return slug === '' ? YARRAMATE_TOOL_PREFIX : slug
}

/**
 * The governance log (#560, ADR 0160): the RAID log's risks and
 * assumptions as the model holds them, derived the way the responsibility
 * matrix is derived and never authored. One row per risk or assumption:
 * its owner and status, what it threatens or bears on, what mitigates it,
 * the latest review attestation, what it supersedes, and the groupings it
 * aggregates into (an adopter's severity or likelihood classes, which the
 * engine carries without knowing the scale). Issues and open questions are
 * the adopter's and the interrogation's; the engine never sees an issue.
 *
 * Deterministic: identical inputs give identical bytes, so CI can diff it.
 */
import type {
  GraphClaim,
  ResolvedProfileContext,
  SemanticGraph,
} from './compiler.js'
import {
  ATTESTATION_PREDICATE_PREFIX,
  parseAttestationClaimValue,
} from './graph-claims.js'
import {
  REVIEW_TOPICS,
  governanceTypeOf,
  type GovernanceType,
} from './governance-kinds.js'

export interface GovernanceSource {
  readonly path: string
  readonly line: number
}

export interface GovernanceRef {
  readonly id: string
  readonly name: string
}

/** The latest review attestation on a row, by date. */
export interface GovernanceReview {
  readonly topic: string
  readonly on: string
  readonly by: string
  readonly source: GovernanceSource
}

export interface GovernanceRow {
  readonly subject: string
  readonly name: string
  readonly kind: string
  readonly type: GovernanceType
  readonly status: string | null
  readonly description?: string
  readonly owner: GovernanceRef | null
  /** A risk's outgoing `influence` targets: what it threatens. */
  readonly threatens: readonly GovernanceRef[]
  /** An assumption's outgoing `association` targets: what it bears on. */
  readonly bearsOn: readonly GovernanceRef[]
  /** Incoming `influence` or `association` sources on a risk: what mitigates it. */
  readonly mitigatedBy: readonly GovernanceRef[]
  readonly review: GovernanceReview | null
  readonly supersedes: readonly string[]
  /** The groupings that aggregate this row: an adopter's rating classes. */
  readonly groupedBy: readonly GovernanceRef[]
}

export interface GovernanceLog {
  readonly format: 'yarramate/governance/v1'
  readonly workspace: string
  readonly summary: {
    readonly rows: number
    readonly risks: number
    readonly assumptions: number
    readonly unowned: number
    readonly unmitigated: number
    readonly unconfirmed: number
    readonly unreviewed: number
  }
  readonly rows: readonly GovernanceRow[]
  readonly gaps: {
    /** Rows with no owner. */
    readonly unowned: readonly string[]
    /** Current risks nothing mitigates. */
    readonly unmitigated: readonly string[]
    /** Assumptions with no `assumption-confirmed` attestation. */
    readonly unconfirmed: readonly string[]
    /** Risks with no `risk-reviewed` attestation. How old is too old is the adopter's. */
    readonly unreviewed: readonly string[]
  }
}

export interface GovernanceOptions {
  /** The subjects that may get a row; absent, every risk and assumption. */
  readonly rows?: readonly string[]
}

const CORE = 'yarramate/core@0.1#'

const documentOf = (subject: string): string => {
  const hash = subject.indexOf('#')
  return hash === -1 ? '' : subject.slice(0, hash)
}

const bySubjectOrder = (left: string, right: string): number =>
  documentOf(left).localeCompare(documentOf(right)) ||
  left.localeCompare(right)

const citation = (claim: GraphClaim): GovernanceSource => ({
  path: claim.source.path,
  line: claim.source.line,
})

export function buildGovernanceLog(
  workspace: string,
  graph: SemanticGraph,
  profileContext: ResolvedProfileContext,
  options: GovernanceOptions = {},
): GovernanceLog {
  const conceptIds = new Set(
    graph.subjects.filter(({ type }) => type === 'concept').map(({ id }) => id),
  )
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const values = new Map<string, string>()
  const refs = new Map<string, string[]>()
  const attestations = new Map<string, GraphClaim[]>()
  const definingClaims: GraphClaim[] = []
  for (const claim of graph.claims) {
    if (relationshipIds.has(claim.id) && 'ref' in claim.object) {
      definingClaims.push(claim)
      continue
    }
    if ('ref' in claim.object) {
      const key = `${claim.subject} ${claim.predicate}`
      refs.set(key, [...(refs.get(key) ?? []), claim.object.ref])
      continue
    }
    if (claim.predicate.startsWith(ATTESTATION_PREDICATE_PREFIX)) {
      attestations.set(claim.subject, [
        ...(attestations.get(claim.subject) ?? []),
        claim,
      ])
      continue
    }
    values.set(`${claim.subject} ${claim.predicate}`, claim.object.value)
  }
  const value = (subject: string, predicate: string): string | undefined =>
    values.get(`${subject} ${predicate}`)
  const refsOf = (subject: string, predicate: string): readonly string[] =>
    refs.get(`${subject} ${predicate}`) ?? []
  const kindOf = (subject: string): string =>
    value(subject, 'yarramate/concept/kind') ?? ''
  const nameOf = (subject: string): string =>
    value(subject, 'yarramate/concept/name') ?? subject
  const refOf = (id: string): GovernanceRef => ({ id, name: nameOf(id) })
  const typeOf = (subject: string): GovernanceType | null => {
    const kind = kindOf(subject)
    return governanceTypeOf(profileContext.conceptKindLineages.get(kind), kind)
  }
  const coreKindOf = (relationshipKind: string): string =>
    (profileContext.relationshipKindLineages.get(relationshipKind) ?? [
      relationshipKind,
    ])[0]!

  const rowIds = (options.rows ?? [...conceptIds])
    .filter((id) => conceptIds.has(id) && typeOf(id) !== null)
    .sort(bySubjectOrder)
  const rowSet = new Set(rowIds)

  const outgoing = new Map<string, { core: string; to: string }[]>()
  const incoming = new Map<string, { core: string; from: string }[]>()
  for (const claim of definingClaims) {
    if (!('ref' in claim.object)) continue
    const core = coreKindOf(claim.predicate)
    if (rowSet.has(claim.subject)) {
      outgoing.set(claim.subject, [
        ...(outgoing.get(claim.subject) ?? []),
        { core, to: claim.object.ref },
      ])
    }
    if (rowSet.has(claim.object.ref)) {
      incoming.set(claim.object.ref, [
        ...(incoming.get(claim.object.ref) ?? []),
        { core, from: claim.subject },
      ])
    }
  }
  const targets = (subject: string, core: string): readonly GovernanceRef[] =>
    (outgoing.get(subject) ?? [])
      .filter((edge) => edge.core === `${CORE}${core}`)
      .map(({ to }) => to)
      .sort(bySubjectOrder)
      .map(refOf)
  const sources = (subject: string, cores: readonly string[]): readonly GovernanceRef[] =>
    (incoming.get(subject) ?? [])
      .filter((edge) => cores.some((core) => edge.core === `${CORE}${core}`))
      .map(({ from }) => from)
      .sort(bySubjectOrder)
      .map(refOf)
  const latestReview = (
    subject: string,
    topic: string,
  ): GovernanceReview | null => {
    let latest: GovernanceReview | null = null
    for (const claim of attestations.get(subject) ?? []) {
      if (claim.predicate !== `${ATTESTATION_PREDICATE_PREFIX}${topic}`) continue
      if (!('value' in claim.object)) continue
      const parts = parseAttestationClaimValue(claim.object.value)
      if (parts === undefined) continue
      if (latest === null || parts.on >= latest.on) {
        latest = { topic, on: parts.on, by: parts.by, source: citation(claim) }
      }
    }
    return latest
  }

  const rows: GovernanceRow[] = rowIds.map((subject) => {
    const type = typeOf(subject)!
    const owner = refsOf(subject, 'yarramate/ownership/owner')[0]
    const description = value(subject, 'yarramate/concept/description')
    return {
      subject,
      name: nameOf(subject),
      kind: kindOf(subject),
      type,
      status: value(subject, 'yarramate/lifecycle/status') ?? null,
      ...(description === undefined ? {} : { description }),
      owner: owner === undefined ? null : refOf(owner),
      threatens: type === 'risk' ? targets(subject, 'influence') : [],
      bearsOn: type === 'assumption' ? targets(subject, 'association') : [],
      mitigatedBy:
        type === 'risk' ? sources(subject, ['influence', 'association']) : [],
      review: latestReview(subject, REVIEW_TOPICS[type]),
      supersedes: [...refsOf(subject, 'yarramate/lineage/supersedes')].sort(),
      groupedBy: sources(subject, ['aggregation']),
    }
  })
  const ids = (predicate: (row: GovernanceRow) => boolean): string[] =>
    rows.filter(predicate).map(({ subject }) => subject)
  const unowned = ids((row) => row.owner === null)
  const unmitigated = ids(
    (row) =>
      // Every risk still open, whatever its status says or does not say. The
      // first cut counted only `status: current`, so a risk nobody had given a
      // status, which is every freshly authored one, was never here and the
      // tile read 0 over a log where every risk was unmitigated (#564). The
      // engine's word for "open" is not-retired: that is what keeps unstatused
      // subjects in a projection with `excludeStatuses: [retired]` and what
      // the interrogation applies by default. A planned risk is asked for its
      // mitigation too; a mitigation can be planned.
      row.type === 'risk' && row.status !== 'retired' && row.mitigatedBy.length === 0,
  )
  const unconfirmed = ids((row) => row.type === 'assumption' && row.review === null)
  const unreviewed = ids((row) => row.type === 'risk' && row.review === null)
  return {
    format: 'yarramate/governance/v1',
    workspace,
    summary: {
      rows: rows.length,
      risks: rows.filter(({ type }) => type === 'risk').length,
      assumptions: rows.filter(({ type }) => type === 'assumption').length,
      unowned: unowned.length,
      unmitigated: unmitigated.length,
      unconfirmed: unconfirmed.length,
      unreviewed: unreviewed.length,
    },
    rows,
    gaps: { unowned, unmitigated, unconfirmed, unreviewed },
  }
}

const escapeCell = (text: string): string => text.replaceAll('|', '\\|')

const names = (entries: readonly GovernanceRef[]): string =>
  entries.map(({ name }) => escapeCell(name)).join(', ')

const list = (ids: readonly string[]): string =>
  ids.length === 0 ? 'none' : ids.map((id) => `\`${id}\``).join(', ')

/** The log as one markdown table a person reads, with the gaps under it. */
export function renderGovernanceMarkdown(log: GovernanceLog): string {
  const lines: string[] = ['# Governance log', '']
  lines.push(
    `Workspace \`${log.workspace}\`: ${log.summary.risks} risk${
      log.summary.risks === 1 ? '' : 's'
    }, ${log.summary.assumptions} assumption${
      log.summary.assumptions === 1 ? '' : 's'
    }. Derived from the record; edit the native documents, not this file.`,
    '',
  )
  if (log.rows.length === 0) {
    lines.push('_No rows._', '')
  } else {
    lines.push(
      '| Subject | Type | Status | Owner | Threatens / bears on | Mitigated by | Review | Grouped by |',
      '|---|---|---|---|---|---|---|---|',
    )
    for (const row of log.rows) {
      const review =
        row.review === null ? '' : `${row.review.topic} ${row.review.on} by ${escapeCell(row.review.by)}`
      lines.push(
        `| ${escapeCell(row.name)} (\`${row.subject}\`) | ${row.type} | ${row.status ?? ''} | ${
          row.owner === null ? '' : escapeCell(row.owner.name)
        } | ${names(row.type === 'risk' ? row.threatens : row.bearsOn)} | ${names(
          row.mitigatedBy,
        )} | ${review} | ${names(row.groupedBy)} |`,
      )
    }
    lines.push('')
  }
  lines.push(
    '## Gaps',
    '',
    `- Unowned: ${list(log.gaps.unowned)}`,
    `- Unmitigated risks: ${list(log.gaps.unmitigated)}`,
    `- Unconfirmed assumptions: ${list(log.gaps.unconfirmed)}`,
    `- Unreviewed risks: ${list(log.gaps.unreviewed)}`,
    '',
  )
  return `${lines.join('\n')}\n`
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://yarramate.org/schema/projection/v1",
  "title": "YarraMate semantic projection",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "id", "version", "query"],
  "properties": {
    "format": {
      "const": "yarramate/projection/v1"
    },
    "id": {
      "$ref": "#/$defs/id"
    },
    "version": {
      "type": "string",
      "pattern": "^[0-9]+\\.[0-9]+$"
    },
    "query": {
      "$ref": "#/$defs/query"
    },
    "presentation": {
      "$ref": "#/$defs/presentation"
    }
  },
  "$defs": {
    "query": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "subjects": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/subjectIdentity"
          }
        },
        "instances": {
          "description": "Pattern instances whose CONTENTS this query selects (#473, ADR 0144). Each id names an instance, and the facet selects that instance together with everything the fold tree would draw inside it: the same closure `presentation.fold: \"instances\"` collapses into one box, read through this view's own `nesting`. This is the one facet that ADDS rather than narrows. `subjects` and `instances` are a single identity facet spelled two ways and their values combine with OR, while every other field still ANDs over the union. Naming the instance rather than hand-listing its members is what keeps a view from going stale the next time the pattern binds a slot. An id that names nothing is refused (YM921); one that names a subject which is not a pattern instance is refused separately (YM922), because a typo and a category error send an author to different places.",
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/subjectIdentity"
          }
        },
        "exclude": {
          "description": "Subjects this query would otherwise select and the author has taken out: the exception a rule cannot state (#267, ADR 0122). Applied after every other facet and after relationship expansion, so an excluded subject is out whichever way it would have come back in. Naming a subject no facet selects is allowed and inert until the model grows into the rule.",
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/subjectIdentity"
          }
        },
        "documents": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/id"
          }
        },
        "kinds": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/qualifiedKind"
          }
        },
        "layers": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/layer"
          }
        },
        "statuses": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "enum": ["planned", "current", "retired"]
          }
        },
        "excludeStatuses": {
          "description": "Drop concepts carrying one of these lifecycle statuses while keeping concepts that declare no status at all - 'everything except retired' for viewpoint projections, where a bare statuses filter would wrongly drop unstatused actors and motivation elements.",
          "type": "array",
          "uniqueItems": true,
          "items": {
            "enum": ["planned", "current", "retired"]
          }
        },
        "states": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/subjectIdentity"
          }
        },
        "owners": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/subjectIdentity"
          }
        },
        "constraints": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/subjectIdentity"
          }
        },
        "relationshipKinds": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/qualifiedKind"
          }
        },
        "kindMatching": {
          "enum": ["exact", "descendants"]
        },
        "relationships": {
          "enum": ["between", "connected", "none"]
        },
        "isolatedConcepts": {
          "enum": ["include", "exclude"]
        }
      }
    },
    "presentation": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "title": {
          "$ref": "#/$defs/nonEmptyText"
        },
        "description": {
          "$ref": "#/$defs/nonEmptyText"
        },
        "layout": {
          "description": "How the view arranges itself (ADR 0147), a ladder where each mode keeps everything below it: \"layered\" places the nodes and lets the canvas draw straight lines between them; \"routed\" also routes every edge around the nodes and reserves room for its label; \"served-by\" also layers serving, realization and specialization upward, so the served element sits above what serves it and the label reads down the page; \"bands\" also pins every element to its ArchiMate layer's band. A view that says nothing lays out \"served-by\".",
          "enum": ["layered", "routed", "served-by", "bands"]
        },
        "direction": {
          "enum": ["top-down", "left-right"]
        },
        "nesting": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "enum": ["composition", "assignment"]
          }
        },
        "fold": {
          "description": "Whether this view draws pattern instances FOLDED by default (#473). \"instances\" collapses every instance to a single node carrying its members, with the edges into and out of them lifted onto the box; \"none\", the default, draws everything. A reader opens what they want, so this says where to START rather than what may be seen. Folding reads the same containment tree nesting does, so a view declaring fold without \"assignment\" in nesting collapses less than its author probably expects; the editor says so rather than the loader refusing it, because a diagnostic has no warning severity and this is not an error.",
          "enum": ["instances", "none"]
        },
        "showLifecycle": {
          "type": "boolean"
        },
        "showEvidence": {
          "type": "boolean"
        },
        "showOwnership": {
          "type": "boolean"
        },
        "showResponsibility": {
          "description": "Whether responsibility edges (responsible, consulted, informed; ADR 0159) draw on the canvas. Off when absent: a role responsible for eight applications is eight lines out of one box, and the subject's properties read the letters either way.",
          "type": "boolean"
        },
        "showKindLabels": {
          "description": "Whether an unnamed relationship is labelled with its reading (\"serves\", \"served by\", \"realizes\"). Off, the line style and arrowhead alone say the kind; a named relationship keeps its name either way. On when absent.",
          "type": "boolean"
        },
        "notation": {
          "enum": ["archimate"]
        },
        "folder": {
          "type": "string",
          "description": "The folder this view files itself under in an editor's rail. A LABEL the author declares, never the directory the projection sits in: nest with '/' separators, and the filesystem is never consulted (ADR 0104).",
          "pattern": "^[^/]+(?:/[^/]+)*$",
          "minLength": 1
        }
      }
    },
    "id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "qualifiedKind": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9-]*(?:/[a-z][a-z0-9-]*)+@[0-9]+\\.[0-9]+#[a-z][A-Za-z0-9-]*$"
    },
    "subjectIdentity": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "nonEmptyText": {
      "type": "string",
      "minLength": 1
    },
    "layer": {
      "enum": [
        "motivation",
        "strategy",
        "business",
        "application",
        "technology",
        "physical",
        "implementation",
        "composite"
      ]
  }
  }
}

