// Every kind is derived in `tools/export.ts` (ADR 0156): this command
// parses arguments, resolves the manifest against the filesystem, and
// writes what the core hands back where `--out` says. The git-derived
// review slice (`--changed`) is the CLI's own and reuses the same pieces;
// the LikeC4 kind delegates to the `yarramate-likec4` binary, as before.

const here = dirname(fileURLToPath(import.meta.url))
const likec4AdapterEntry = join(here, 'adapters', 'likec4-cli.js')

interface ParsedExport {
  readonly positionals: readonly string[]
  readonly out?: string
  readonly budget?: number
  readonly changed?: string
  readonly json: boolean
}

const parseExportOptions = (
  options: readonly string[],
): ParsedExport | undefined => {
  const positionals: string[] = []
  let out: string | undefined
  let budget: number | undefined
  let changed: string | undefined
  let json = false
  for (let index = 0; index < options.length; index += 1) {
    const option = options[index]
    if (option === '--json') {
      json = true
      continue
    }
    if (
      option === '--out' ||
      option === '--budget' ||
      option === '--changed'
    ) {
      const value = options[index + 1]
      if (value === undefined || value.startsWith('-')) return undefined
      if (option === '--out') {
        if (out !== undefined) return undefined
        out = value
      } else if (option === '--changed') {
        if (changed !== undefined) return undefined
        changed = value
      } else {
        if (budget !== undefined || !/^[1-9][0-9]*$/.test(value)) {
          return undefined
        }
        budget = Number(value)
      }
      index += 1
      continue
    }
    if (option === undefined || option.startsWith('-')) return undefined
    positionals.push(option)
  }
  return {
    positionals,
    ...(out === undefined ? {} : { out }),
    ...(budget === undefined ? {} : { budget }),
    ...(changed === undefined ? {} : { changed }),
    json,
  }
}

export function runExportCommand(
  options: readonly string[],
  cwd: string,
): CliResult {
  const [kind, ...rest] = options
  if (
    kind === undefined ||
    ![
      'graph',
      'markdown',
      'briefs',
      'rtm',
      'responsibility',
      'governance',
      'likec4',
      'xlsx',
    ].includes(kind)
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  const parsed = parseExportOptions(rest)
  if (parsed === undefined) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  if (kind === 'likec4') {
    const [projectDefinition, outputDirectory, workspacePath] =
      parsed.positionals
    if (
      parsed.positionals.length !== 3 ||
      projectDefinition === undefined ||
      outputDirectory === undefined ||
      workspacePath === undefined ||
      parsed.out !== undefined ||
      parsed.budget !== undefined ||
      parsed.json
    ) {
      return { exitCode: 2, stdout: '', stderr: usage }
    }
    const changedArguments =
      parsed.changed === undefined ? [] : ['--changed', parsed.changed]
    if (!existsSync(likec4AdapterEntry)) {
      return {
        exitCode: 2,
        stdout: '',
        stderr:
          `LikeC4 adapter entry not found at ${likec4AdapterEntry}; ` +
          'run from the installed package or use the yarramate-likec4 binary directly\n',
      }
    }
    const delegated = spawnSync(
      process.execPath,
      [
        likec4AdapterEntry,
        'export-project',
        projectDefinition,
        outputDirectory,
        workspacePath,
        ...changedArguments,
      ],
      { cwd, encoding: 'utf8' },
    )
    const exitCode = delegated.status === 0 ? 0 : delegated.status === 1 ? 1 : 2
    return {
      exitCode,
      stdout: delegated.stdout ?? '',
      stderr: delegated.stderr ?? '',
    }
  }

  const usesChanged = parsed.changed !== undefined
  const wholeWorkspace = kind === 'graph' || kind === 'rtm' || kind === 'governance'
  const expectedPositionals = wholeWorkspace || usesChanged ? 1 : 2
  const workspacePath = parsed.positionals[expectedPositionals - 1]
  const projectionPath =
    wholeWorkspace || usesChanged ? undefined : parsed.positionals[0]
  if (
    parsed.positionals.length !== expectedPositionals ||
    workspacePath === undefined ||
    parsed.json ||
    (usesChanged && (wholeWorkspace || kind === 'responsibility')) ||
    (parsed.budget !== undefined && kind !== 'briefs') ||
    ((kind === 'briefs' ||
      kind === 'rtm' ||
      kind === 'responsibility' ||
      kind === 'governance' ||
      kind === 'xlsx') &&
      parsed.out === undefined)
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  try {
    const manifestSource = readFileSync(resolve(cwd, workspacePath), 'utf8')
    if (
      parseDocument(manifestSource).get('format') !== 'yarramate/workspace/v1'
    ) {
      return {
        exitCode: 2,
        stdout: '',
        stderr:
          'export requires an explicit workspace manifest (yarramate/workspace/v1)\n',
      }
    }
    const failed = (diagnostics: readonly Diagnostic[]): CliResult => ({
      exitCode: 1,
      stdout: humanDiagnostics(diagnostics),
      stderr: '',
    })
    const failedTool = (failure: ToolFailure): CliResult =>
      failure.reason === 'diagnostics'
        ? failed(failure.diagnostics)
        : { exitCode: 2, stdout: '', stderr: `${failure.message}\n` }
    const loadedWorkspace = loadWorkspaceManifest(
      { path: workspacePath, source: manifestSource },
      cwd,
    )
    if (!loadedWorkspace.ok) return failed(loadedWorkspace.diagnostics)
    const workspace = loadedWorkspace.workspace
    const tool: ToolWorkspace = {
      store: createFileSystemStore(cwd),
      workspace,
      manifestDirectory: posixDirectoryOf(workspacePath),
    }
    const writeText = (path: string, text: string): void => {
      const outPath = resolve(cwd, path)
      mkdirSync(dirname(outPath), { recursive: true })
      writeFileSync(outPath, text, 'utf8')
    }

    if (kind === 'rtm') {
      const exported = exportRtm(tool)
      if (!exported.ok) return failedTool(exported)
      const { markdown, rtm } = exported.result
      writeText(join(parsed.out!, 'RTM.md'), markdown)
      writeText(join(parsed.out!, 'rtm.json'), `${JSON.stringify(rtm, null, 2)}\n`)
      return {
        exitCode: 0,
        stdout:
          `Wrote RTM.md and rtm.json (${rtm.summary.rows} row${
            rtm.summary.rows === 1 ? '' : 's'
          }, ${rtm.summary.gaps} gap${
            rtm.summary.gaps === 1 ? '' : 's'
          }) to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'governance') {
      const exported = exportGovernance(tool)
      if (!exported.ok) return failedTool(exported)
      const { markdown, log } = exported.result
      writeText(join(parsed.out!, 'GOVERNANCE.md'), markdown)
      writeText(join(parsed.out!, 'governance.json'), `${JSON.stringify(log, null, 2)}\n`)
      const gaps =
        log.summary.unowned + log.summary.unmitigated + log.summary.unconfirmed + log.summary.unreviewed
      return {
        exitCode: 0,
        stdout: `Wrote GOVERNANCE.md and governance.json (${log.summary.rows} row${
          log.summary.rows === 1 ? '' : 's'
        }, ${gaps} gap${gaps === 1 ? '' : 's'}) to ${parsed.out}\n`,
        stderr: '',
      }
    }
    if (kind === 'responsibility') {
      const exported = exportResponsibility(tool, projectionPath!)
      if (!exported.ok) return failedTool(exported)
      const { markdown, matrix } = exported.result
      writeText(join(parsed.out!, 'RESPONSIBILITY.md'), markdown)
      writeText(
        join(parsed.out!, 'responsibility.json'),
        `${JSON.stringify(matrix, null, 2)}\n`,
      )
      const gaps = matrix.summary.noAccountable + matrix.summary.noResponsible
      return {
        exitCode: 0,
        stdout:
          `Wrote RESPONSIBILITY.md and responsibility.json (${matrix.summary.rows} row${
            matrix.summary.rows === 1 ? '' : 's'
          }, ${gaps} gap${gaps === 1 ? '' : 's'}) to ${parsed.out}\n`,
        stderr: '',
      }
    }
    if (kind === 'graph') {
      const exported = exportGraph(tool)
      if (!exported.ok) return failedTool(exported)
      if (parsed.out === undefined) {
        return { exitCode: 0, stdout: exported.result.json, stderr: '' }
      }
      writeText(parsed.out, exported.result.json)
      return {
        exitCode: 0,
        stdout: `Wrote graph to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'xlsx') {
      const exported = exportWorkbook(tool, projectionPath!)
      if (!exported.ok) return failedTool(exported)
      const outPath = resolve(cwd, parsed.out!)
      mkdirSync(dirname(outPath), { recursive: true })
      writeFileSync(outPath, exported.result.bytes)
      return {
        exitCode: 0,
        stdout: `Wrote workbook to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'markdown' && parsed.changed === undefined) {
      const exported = exportMarkdown(tool, projectionPath!)
      if (!exported.ok) return failedTool(exported)
      if (parsed.out === undefined) {
        return { exitCode: 0, stdout: exported.result.markdown, stderr: '' }
      }
      writeText(parsed.out, exported.result.markdown)
      return {
        exitCode: 0,
        stdout: `Wrote markdown to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'briefs' && parsed.changed === undefined) {
      const exported = exportBriefs(
        tool,
        projectionPath!,
        parsed.budget === undefined ? {} : { budget: parsed.budget },
      )
      if (!exported.ok) return failedTool(exported)
      for (const { path, markdown } of exported.result.files) {
        writeText(join(parsed.out!, path), markdown)
      }
      const count = exported.result.concepts
      return {
        exitCode: 0,
        stdout: `Wrote ${count} brief${count === 1 ? '' : 's'} and INDEX.md to ${parsed.out}\n`,
        stderr: '',
      }
    }

    // --changed: the review slice, seeded by what git says moved (ADR
    // 0065). The CLI's own, because it needs a repository; it renders and
    // writes through the same pieces the store-backed kinds use.
    const compilation = compileOf(tool)
    if (!compilation.ok) return failedTool(compilation)
    const { compiled } = compilation
    const documentIdByPath = new Map(
      compiled.graph.documents.map(({ id, source }) => [source, id]),
    )
    const derived = deriveChangedSubjects(
      cwd,
      parsed.changed!,
      workspace.documents.map((path) => ({
        ...readSource(tool, path),
        documentId: documentIdByPath.get(path) ?? path,
      })),
    )
    if (!derived.ok) {
      return { exitCode: 2, stdout: '', stderr: `${derived.message}\n` }
    }
    const endpoints = new Set<string>()
    for (const relationshipId of derived.changed.relationships) {
      const claim = compiled.graph.claims.find(
        (candidate) =>
          candidate.id === relationshipId && 'ref' in candidate.object,
      )
      if (claim !== undefined && 'ref' in claim.object) {
        endpoints.add(claim.subject)
        endpoints.add(claim.object.ref)
      }
    }
    const seeds = [
      ...new Set([...derived.changed.concepts, ...endpoints]),
    ].sort()
    const result = evaluateProjection(
      compiled.graph,
      {
        format: 'yarramate/projection/v1',
        id: 'review-slice',
        version: '0.0',
        query: { subjects: seeds, relationships: 'connected' },
        presentation: {
          title: `Review slice ${parsed.changed}`,
          description:
            `Connected neighbourhood of the subjects changed in ` +
            `${parsed.changed}.`,
        },
      },
      compiled.profileContext,
    )

    if (kind === 'markdown') {
      const rendered = renderProjectionMarkdown(result, compiled.profileContext)
      if (parsed.out === undefined) {
        return { exitCode: 0, stdout: rendered, stderr: '' }
      }
      writeText(parsed.out, rendered)
      return {
        exitCode: 0,
        stdout: `Wrote markdown to ${parsed.out}\n`,
        stderr: '',
      }
    }

    const briefs = briefsFromResult(
      compiled,
      result,
      parsed.budget === undefined ? {} : { budget: parsed.budget },
    )
    for (const { path, markdown } of briefs.files) {
      writeText(join(parsed.out!, path), markdown)
    }
    return {
      exitCode: 0,
      stdout: `Wrote ${briefs.concepts} brief${briefs.concepts === 1 ? '' : 's'} and INDEX.md to ${parsed.out}\n`,
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

import type { GraphClaim, SemanticGraph } from './compiler.js'
import {
  ATTESTATION_PREDICATE_PREFIX,
  parseAttestationClaimValue,
  parseConstraintExpectsValue,
} from './compiler.js'
import type {
  EvidenceLocator,
  EvidenceReport,
  EvidenceResult,
} from './evidence.js'
import type { ArtifactCoverage } from './artifact-coverage.js'

export interface AssertedRelationship {
  readonly from: string
  readonly to: string
  readonly kind: string
  readonly name?: string
}

export interface DeclaredSource {
  readonly document: string
  readonly path: string
  readonly pointer: string
  readonly line: number
  readonly column: number
}

export interface ExpectationComparison {
  readonly provider: string
  readonly key: string
  readonly expected: string
  readonly observed: string
  readonly declared: DeclaredSource
}

export interface UnobservedExpectation {
  readonly claim: string
  readonly subject: string
  readonly provider: string
  readonly key: string
  readonly expected: string
  readonly declared: DeclaredSource
}

export interface EvidenceFinding {
  readonly target: {
    readonly type: 'subject' | 'claim'
    readonly id: string
  }
  readonly asserted?: AssertedRelationship
  readonly expectation?: ExpectationComparison
  readonly result: Exclude<EvidenceResult, 'confirmed'>
  readonly provider: string
  readonly evidenceDocument: string
  readonly evidence: EvidenceLocator
}

// A stale attestation is a finding with git provenance (ADR 0074): the
// sign-off predates the current wording of the attested subject. It has
// no evidence document because no provider authored it; git is the
// witness.
export interface StaleAttestationFinding {
  readonly target: {
    readonly type: 'subject'
    readonly id: string
  }
  readonly result: 'stale-attestation'
  readonly attestation: {
    readonly topic: string
    readonly by: string
    readonly on: string
  }
  readonly provider: 'git'
  readonly changedAt?: string
  readonly evidence: EvidenceLocator
}

// A sign-off a machine transcribed is not the act the authority
// performed: the recorder is named in the model, so reconcile reports
// the gap between whose judgment this claims to be and whose hand wrote
// it. The model is the witness; no provider observed anything.
export interface UnconfirmedAttestationFinding {
  readonly target: {
    readonly type: 'subject'
    readonly id: string
  }
  readonly result: 'unconfirmed-attestation'
  readonly attestation: {
    readonly topic: string
    readonly by: string
    readonly recordedBy: string
    readonly on: string
  }
  readonly provider: 'model'
  readonly declared: DeclaredSource
}

export type ReconciliationFinding =
  | EvidenceFinding
  | StaleAttestationFinding
  | UnconfirmedAttestationFinding

export interface AttestationStaleness {
  readonly findings: readonly StaleAttestationFinding[]
  readonly notes: readonly string[]
}

export interface ReconciliationReport {
  readonly format: 'yarramate/reconciliation-report/v1'
  readonly workspace: string
  readonly summary: {
    readonly evidenceDocuments: number
    readonly observations: number
    readonly confirmed: number
    readonly findings: number
    readonly contradicted: number
    readonly unknown: number
    readonly notObserved: number
    /**
     * `not-observed` observations naming no search. A negative claim about a
     * tree nobody read exhaustively is the one result whose message nothing
     * can check, so the ones offering a reader nothing to re-run are counted
     * rather than left to read like any other finding (ADR 0107).
     */
    readonly unsupportedAbsences?: number
    readonly subjectsWithoutEvidence: number
    readonly staleAttestations?: number
    readonly unconfirmedAttestations?: number
    readonly expectationsCompared: number
    readonly expectationsWithoutObservation: number
    /**
     * Files the declared coverage scope selected, and the ones no
     * observation's `repo:` locator claims (ADR 0130). Both appear exactly
     * when coverage was assessed, so a report without them is one that
     * never looked, not one that found nothing.
     */
    readonly artifactsInScope?: number
    readonly unclaimedArtifacts?: number
  }
  readonly findings: readonly ReconciliationFinding[]
  readonly unobservedSubjects?: readonly string[]
  readonly unobservedExpectations?: readonly UnobservedExpectation[]
  /**
   * The coverage patterns as the manifest declared them, echoed so the
   * report is honest about what it was asked to look at (ADR 0130).
   */
  readonly coverageScope?: readonly string[]
  /**
   * In-scope artifacts no observation claims, sorted. Absence, never
   * accusation: no finding is fabricated and `check --strict` never reads
   * this (ADR 0130), the line ADR 0049 drew for unobserved subjects.
   */
  readonly unclaimedArtifacts?: readonly string[]
  readonly notes?: readonly string[]
}

const assertedRelationshipsByClaim = (
  graph: SemanticGraph | undefined,
): ReadonlyMap<string, AssertedRelationship> => {
  const asserted = new Map<string, AssertedRelationship>()
  if (graph === undefined) return asserted
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const names = new Map<string, string>()
  for (const claim of graph.claims) {
    if (
      claim.predicate === 'yarramate/relationship/name' &&
      'value' in claim.object
    ) {
      names.set(claim.subject, claim.object.value)
    }
  }
  for (const claim of graph.claims) {
    if (!relationshipIds.has(claim.id) || !('ref' in claim.object)) continue
    const name = names.get(claim.id)
    asserted.set(claim.id, {
      from: claim.subject,
      to: claim.object.ref,
      kind: claim.predicate,
      ...(name === undefined ? {} : { name }),
    })
  }
  return asserted
}

export const constraintExpectsPredicate = 'yarramate/constraint/expects'

// A finding is now a union (ADR 0074); only the evidence arm can carry an
// expectation, so ordering reads it through one narrowing helper.
const expectationOf = (
  finding: ReconciliationFinding,
): ExpectationComparison | undefined =>
  'expectation' in finding ? finding.expectation : undefined

interface DeclaredExpectation extends UnobservedExpectation {}

// The compiler's parseConstraintExpectsValue is the sole authority for
// decoding the encoded value (ADR 0075). Provider and key admit no
// whitespace, so the first two spaces delimit them and everything after the
// second space is the expected value verbatim, spaces included.
const parseExpectation = (
  claim: GraphClaim,
): DeclaredExpectation | undefined => {
  if (
    claim.predicate !== constraintExpectsPredicate ||
    !('value' in claim.object)
  ) {
    return undefined
  }
  const parts = parseConstraintExpectsValue(claim.object.value)
  if (parts === undefined) return undefined
  return {
    claim: claim.id,
    subject: claim.subject,
    provider: parts.provider,
    key: parts.key,
    expected: parts.value,
    declared: {
      document: claim.source.document,
      path: claim.source.path,
      pointer: claim.source.pointer,
      line: claim.source.line,
      column: claim.source.column,
    },
  }
}

interface ExpectationOutcome {
  readonly findings: readonly EvidenceFinding[]
  readonly unobserved: readonly UnobservedExpectation[]
  readonly compared: number
}

// A declared expectation is matched to observations by provider and key. The
// observation's own target anchors its provenance but does not narrow the
// match: a keyed value is a fact about the project ("this deployment's region
// is X"), and several constraints on different subjects may legitimately
// expect the same fact. Comparison is string equality, deliberately; a
// provider that needs richer matching normalizes before it reports.
const compareExpectations = (
  graph: SemanticGraph | undefined,
  reports: readonly EvidenceReport[],
): ExpectationOutcome => {
  if (graph === undefined) {
    return { findings: [], unobserved: [], compared: 0 }
  }
  const findings: EvidenceFinding[] = []
  const unobserved: UnobservedExpectation[] = []
  let compared = 0
  for (const claim of graph.claims) {
    const expectation = parseExpectation(claim)
    if (expectation === undefined) continue
    let matched = false
    for (const report of reports) {
      if (report.provider !== expectation.provider) continue
      for (const observation of report.observations) {
        if (
          observation.key !== expectation.key ||
          observation.value === undefined
        ) {
          continue
        }
        matched = true
        if (observation.value === expectation.expected) continue
        findings.push({
          target: { type: 'claim', id: expectation.claim },
          expectation: {
            provider: expectation.provider,
            key: expectation.key,
            expected: expectation.expected,
            observed: observation.value,
            declared: expectation.declared,
          },
          result: 'contradicted',
          provider: report.provider,
          evidenceDocument: report.evidence,
          evidence: observation.evidence,
        })
      }
    }
    if (!matched) unobserved.push(expectation)
    else compared += 1
  }
  return {
    findings,
    unobserved: [...unobserved].sort(
      (left, right) =>
        left.claim.localeCompare(right.claim) ||
        left.key.localeCompare(right.key),
    ),
    compared,
  }
}

const unobservedCurrentConcepts = (
  graph: SemanticGraph | undefined,
  reports: readonly EvidenceReport[],
): readonly string[] => {
  if (graph === undefined) return []
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const claimsById = new Map(graph.claims.map((claim) => [claim.id, claim]))
  const observed = new Set<string>()
  for (const report of reports) {
    for (const observation of report.observations) {
      if ('subject' in observation) {
        observed.add(observation.subject)
        continue
      }
      const claim = claimsById.get(observation.claim)
      if (claim === undefined) continue
      observed.add(claim.subject)
      if (relationshipIds.has(claim.id) && 'ref' in claim.object) {
        observed.add(claim.object.ref)
      }
    }
  }
  const conceptIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'concept')
      .map(({ id }) => id),
  )
  return graph.claims
    .filter(
      (claim) =>
        claim.predicate === 'yarramate/lifecycle/status' &&
        'value' in claim.object &&
        claim.object.value === 'current' &&
        conceptIds.has(claim.subject) &&
        !observed.has(claim.subject),
    )
    .map(({ subject }) => subject)
    .sort((left, right) => left.localeCompare(right))
}

// An observation claims an artifact when its locator is `repo:<path>`,
// read syntactically: any `#fragment` stripped, a directory claiming
// everything beneath it, any other scheme claiming nothing. Resolution
// and external validity stay with the provider (ADR 0130) — nothing here
// opens a file or checks one exists.
const claimedArtifactPaths = (
  reports: readonly EvidenceReport[],
): ReadonlySet<string> => {
  const claimed = new Set<string>()
  for (const report of reports) {
    for (const observation of report.observations) {
      const uri = observation.evidence.uri
      if (!uri.startsWith('repo:')) continue
      const located = uri.slice('repo:'.length)
      const fragment = located.indexOf('#')
      // Trailing slashes are stripped with a loop, not a regex: an
      // anchored /\/+$/ is polynomial on a locator of many slashes, and
      // locators are library input.
      let path = fragment === -1 ? located : located.slice(0, fragment)
      while (path.endsWith('/')) path = path.slice(0, -1)
      if (path.length > 0) claimed.add(path)
    }
  }
  return claimed
}

const isClaimed = (
  claimed: ReadonlySet<string>,
  artifact: string,
): boolean => {
  if (claimed.has(artifact)) return true
  for (const path of claimed) {
    if (artifact.startsWith(`${path}/`)) return true
  }
  return false
}

interface CoverageOutcome {
  readonly scope?: readonly string[]
  readonly artifacts?: number
  readonly unclaimed?: readonly string[]
  readonly notes: readonly string[]
}

const assessArtifactCoverage = (
  coverage: ArtifactCoverage | undefined,
  reports: readonly EvidenceReport[],
): CoverageOutcome => {
  // An absent argument is a caller that never looked (the strict gate);
  // an unassessed derivation is a reconcile that looked and could not,
  // and says why (ADR 0130, the ADR 0074 parallel).
  if (coverage === undefined) return { notes: [] }
  if (!coverage.assessed) {
    return {
      notes: [`Artifact coverage was not assessed: ${coverage.reason}.`],
    }
  }
  const notes: string[] = []
  if (coverage.scope.length === 0) {
    notes.push(
      'The workspace manifest declares an empty coverage scope, so no artifacts were assessed.',
    )
  }
  // A dead glob is indistinguishable from a typo, and silently
  // contributing nothing is how a mistyped pattern would report full
  // coverage. A note, not a refusal: a coverage scope is a lens, not
  // load-bearing input (ADR 0130).
  for (const { pattern, artifacts } of coverage.scope) {
    if (artifacts.length === 0) {
      notes.push(`Coverage pattern "${pattern}" matched no artifacts.`)
    }
  }
  const artifacts = [
    ...new Set(coverage.scope.flatMap(({ artifacts }) => artifacts)),
  ].sort((left, right) => left.localeCompare(right))
  const claimed = claimedArtifactPaths(reports)
  return {
    scope: coverage.scope.map(({ pattern }) => pattern),
    artifacts: artifacts.length,
    unclaimed: artifacts.filter((artifact) => !isClaimed(claimed, artifact)),
    notes,
  }
}

// A judgment a machine transcribed is not the act the authority
// performed. The recorder is in the model, so the difference is
// derivable here: an authority who wrote the record in their own hand
// names nobody else, and anything else is a claim awaiting confirmation.
const unconfirmedAttestations = (
  graph: SemanticGraph | undefined,
): readonly UnconfirmedAttestationFinding[] => {
  if (graph === undefined) return []
  return graph.claims.flatMap((claim) => {
    if (!claim.predicate.startsWith(ATTESTATION_PREDICATE_PREFIX)) return []
    if (!('value' in claim.object)) return []
    const parts = parseAttestationClaimValue(claim.object.value)
    const recordedBy = parts?.recordedBy
    if (parts === undefined || recordedBy === undefined) return []
    // The authority is qualified; a recorder naming the same subject,
    // long form or short, is that authority signing for themselves.
    const local = parts.by.slice(parts.by.indexOf('#') + 1)
    if (recordedBy === parts.by || recordedBy === local) return []
    return [
      {
        target: { type: 'subject', id: claim.subject } as const,
        result: 'unconfirmed-attestation' as const,
        attestation: {
          topic: claim.predicate.slice(ATTESTATION_PREDICATE_PREFIX.length),
          by: parts.by,
          recordedBy,
          on: parts.on,
        },
        provider: 'model' as const,
        declared: claim.source,
      },
    ]
  })
}

export function reconcileEvidenceReports(
  workspace: string,
  reports: readonly EvidenceReport[],
  graph?: SemanticGraph,
  staleness?: AttestationStaleness,
  coverage?: ArtifactCoverage,
): ReconciliationReport {
  const assertedByClaim = assertedRelationshipsByClaim(graph)
  const unobservedSubjects = unobservedCurrentConcepts(graph, reports)
  const expectations = compareExpectations(graph, reports)
  const unconfirmed = unconfirmedAttestations(graph)
  const assessedCoverage = assessArtifactCoverage(coverage, reports)
  const summary = {
    evidenceDocuments: reports.length,
    observations: 0,
    confirmed: 0,
    findings: 0,
    contradicted: 0,
    unknown: 0,
    notObserved: 0,
    unsupportedAbsences: 0,
    subjectsWithoutEvidence: unobservedSubjects.length,
    // Attestation staleness is assessed only when the caller derived it
    // (the reconcile command); the counter appears exactly then, so a
    // report without it is one that never looked, not one that found
    // nothing.
    ...(staleness === undefined
      ? {}
      : { staleAttestations: staleness.findings.length }),
    // Recorder disagreement is derived from the model alone, so the
    // counter appears whenever there was a graph to read.
    ...(graph === undefined
      ? {}
      : { unconfirmedAttestations: unconfirmed.length }),
    expectationsCompared: expectations.compared,
    expectationsWithoutObservation: expectations.unobserved.length,
    // Coverage counters appear exactly when the scope was assessed
    // (ADR 0130): a report without them never looked; a report carrying
    // zero looked and found everything claimed.
    ...(assessedCoverage.artifacts === undefined
      ? {}
      : {
          artifactsInScope: assessedCoverage.artifacts,
          unclaimedArtifacts: assessedCoverage.unclaimed?.length ?? 0,
        }),
  }
  const findings: ReconciliationFinding[] = [
    ...(staleness?.findings ?? []),
    ...unconfirmed,
  ]
  const absenceNotes: string[] = []
  for (const report of reports) {
    summary.observations += report.observations.length
    for (const observation of report.observations) {
      if (observation.result === 'confirmed') {
        summary.confirmed += 1
        continue
      }
      if (observation.result === 'not-observed') {
        summary.notObserved += 1
        // A not-observed asserts a negative, and is the only result whose
        // message nothing else in the pipeline can check: the locator it
        // carries points at what the author looked at, not at the absence
        // they claim. One naming no search offers a reader nothing to
        // re-run, so it is counted and named rather than left to read like
        // a checked finding (ADR 0107).
        if ((observation.searched ?? []).length === 0) {
          summary.unsupportedAbsences += 1
          const named =
            'subject' in observation ? observation.subject : observation.claim
          absenceNotes.push(
            `The not-observed observation for ${named} names no search, ` +
              `so nothing here can be re-run to test the absence it asserts.`,
          )
        }
      } else {
        summary[observation.result] += 1
      }
      const target =
        'subject' in observation
          ? ({ type: 'subject', id: observation.subject } as const)
          : ({ type: 'claim', id: observation.claim } as const)
      const asserted =
        target.type === 'claim' ? assertedByClaim.get(target.id) : undefined
      findings.push({
        target,
        ...(asserted === undefined ? {} : { asserted }),
        result: observation.result,
        provider: report.provider,
        evidenceDocument: report.evidence,
        evidence: observation.evidence,
      })
    }
  }
  // A disagreeing expectation is an ordinary contradicted finding: same
  // taxonomy, same counters, same strict-check consequence (ADR 0075).
  for (const finding of expectations.findings) {
    summary.contradicted += 1
    findings.push(finding)
  }
  findings.sort((left, right) =>
    left.target.id.localeCompare(right.target.id) ||
    left.target.type.localeCompare(right.target.type) ||
    left.provider.localeCompare(right.provider) ||
    ('evidenceDocument' in left ? left.evidenceDocument : '').localeCompare(
      'evidenceDocument' in right ? right.evidenceDocument : '',
    ) ||
    ('attestation' in left ? left.attestation.topic : '').localeCompare(
      'attestation' in right ? right.attestation.topic : '',
    ) ||
    (expectationOf(left)?.key ?? '').localeCompare(
      expectationOf(right)?.key ?? '',
    ) ||
    (expectationOf(left)?.observed ?? '').localeCompare(
      expectationOf(right)?.observed ?? '',
    ),
  )
  summary.findings = findings.length
  const notes = [
    ...(staleness?.notes ?? []),
    ...absenceNotes,
    ...assessedCoverage.notes,
  ]
  return {
    format: 'yarramate/reconciliation-report/v1',
    workspace,
    summary,
    findings,
    ...(unobservedSubjects.length === 0 ? {} : { unobservedSubjects }),
    ...(expectations.unobserved.length === 0
      ? {}
      : { unobservedExpectations: expectations.unobserved }),
    ...(assessedCoverage.scope === undefined
      ? {}
      : { coverageScope: assessedCoverage.scope }),
    ...(assessedCoverage.unclaimed === undefined ||
    assessedCoverage.unclaimed.length === 0
      ? {}
      : { unclaimedArtifacts: assessedCoverage.unclaimed }),
    ...(notes.length === 0 ? {} : { notes }),
  }
}

import {
  adapterMappingEntryLocation,
  adapterMappingLocation,
  type AdapterMapping,
} from '../adapter-mapping.js'
import { resolveBranding, type Branding } from '../branding.js'
import type { GraphClaim } from '../compiler.js'
import type { StateComparison } from '../architecture-state.js'
import type { ProjectionResult } from '../projection.js'
import { diagnosticOrder } from '../source-document.js'
import type { LikeC4KindMapping } from './likec4-kind-mapping.js'

export interface LikeC4ExportDiagnostic {
  readonly severity: 'error'
  readonly code:
    | 'YMLC101'
    | 'YMLC102'
    | 'YMLC103'
    | 'YMLC104'
    | 'YMLC105'
    | 'YMLC106'
    | 'YMLC107'
    | 'YMLC108'
    | 'YMLC109'
    | 'YMLC111'
    | 'YMLC112'
  readonly message: string
  readonly subject?: string
  readonly path: string
  readonly pointer: string
  readonly line: number
  readonly column: number
}

export type LikeC4ExportResult =
  | { readonly ok: true; readonly source: string }
  | {
      readonly ok: false
      readonly diagnostics: readonly LikeC4ExportDiagnostic[]
    }

export interface LikeC4ExportOptions {
  readonly comparison?: StateComparison
  /** The banner names the host's product (#546, ADR 0158); absent, the engine. */
  readonly branding?: Branding
  /** Git-derived review overlay (ADR 0066): subjects new or changed in a
   *  ref range carry metadata and view styling; nothing is authored. */
  readonly gitChange?: GitChangeOverlay
}

export interface GitChangeOverlay {
  readonly range: string
  readonly added: readonly string[]
  readonly modified: readonly string[]
}

const identifier = /^[A-Za-z_][A-Za-z0-9_-]*$/

const valueFor = (
  claims: readonly GraphClaim[],
  subject: string,
  predicate: string,
): string | undefined => {
  const object = claims.find(
    (claim) => claim.subject === subject && claim.predicate === predicate,
  )?.object
  return object !== undefined && 'value' in object
    ? object.value
    : undefined
}

const referencesFor = (
  claims: readonly GraphClaim[],
  subject: string,
  predicate: string,
): readonly string[] =>
  claims
    .flatMap((claim) =>
      claim.subject === subject &&
      claim.predicate === predicate &&
      'ref' in claim.object
        ? [claim.object.ref]
        : [],
    )
    .sort()

const sourceForConcept = (
  claims: readonly GraphClaim[],
  subject: string,
) =>
  claims.find(
    (claim) =>
      claim.subject === subject &&
      claim.predicate === 'yarramate/concept/kind',
  )?.source

const metadataLines = (
  entries: readonly [
    key: string,
    value: string | readonly string[] | undefined,
  ][],
  indentation: string,
): readonly string[] => {
  const present = entries.filter(
    (
      entry,
    ): entry is [string, string | readonly string[]] =>
      entry[1] !== undefined &&
      (typeof entry[1] === 'string' || entry[1].length > 0),
  )
  if (present.length === 0) return []
  return [
    `${indentation}metadata {`,
    ...present.map(([key, value]) =>
      Array.isArray(value)
        ? `${indentation}  ${key} [${value.map(quote).join(', ')}]`
        : `${indentation}  ${key} ${quote(value as string)}`,
    ),
    `${indentation}}`,
  ]
}

const kindId = (identity: string): string => {
  const separator = identity.lastIndexOf('#')
  return separator === -1 ? identity : identity.slice(separator + 1)
}

const quote = (value: string): string =>
  `'${value.replaceAll('\\', '\\\\').replaceAll("'", "\\'").replaceAll('\n', '\\n')}'`

export function exportLikeC4(
  projection: ProjectionResult,
  mapping: AdapterMapping,
  kindMapping?: LikeC4KindMapping,
  options: LikeC4ExportOptions = {},
): LikeC4ExportResult {
  const diagnostics: LikeC4ExportDiagnostic[] = []
  if (mapping.adapter !== 'likec4') {
    const source = adapterMappingLocation(mapping, 'adapter')
    diagnostics.push({
      severity: 'error',
      code: 'YMLC101',
      message: `Adapter mapping "${mapping.id}@${mapping.version}" targets "${mapping.adapter}", not "likec4"`,
      path: source.path,
      pointer: source.pointer,
      line: source.line,
      column: source.column,
    })
  }

  const externalByNative = new Map(
    mapping.mappings
      .filter(({ type }) => type === 'concept')
      .map(({ native, external }) => [native, external] as const),
  )
  const externalConceptKind = new Map(
    kindMapping?.conceptKinds.map(({ native, external }) => [
      native,
      external,
    ]) ?? [],
  )
  const externalRelationshipKind = new Map(
    kindMapping?.relationshipKinds.map(({ native, external }) => [
      native,
      external,
    ]) ?? [],
  )
  const concepts = projection.subjects
    .filter(({ type }) => type === 'concept')
    .sort((left, right) => left.id.localeCompare(right.id))
  const gitChangeOf = (id: string): 'new' | 'changed' | undefined =>
    options.gitChange === undefined
      ? undefined
      : options.gitChange.added.includes(id)
        ? 'new'
        : options.gitChange.modified.includes(id)
          ? 'changed'
          : undefined
  const comparisonChange = new Map(
    options.comparison === undefined
      ? []
      : [
          ...options.comparison.added.map(
            ({ id }) => [id, 'added'] as const,
          ),
          ...options.comparison.removed.map(
            ({ id }) => [id, 'removed'] as const,
          ),
          ...options.comparison.retained.map(
            ({ id }) => [id, 'retained'] as const,
          ),
        ],
  )

  for (const concept of concepts) {
    const external = externalByNative.get(concept.id)
    if (external === undefined) {
      const source = sourceForConcept(projection.claims, concept.id)
      if (source === undefined) continue
      diagnostics.push({
        severity: 'error',
        code: 'YMLC102',
        message: `Projected concept "${concept.id}" has no LikeC4 mapping`,
        subject: concept.id,
        path: source.path,
        pointer: source.pointer,
        line: source.line,
        column: source.column,
      })
    } else if (!identifier.test(external)) {
      const entry = mapping.mappings.find(
        ({ native, type }) =>
          native === concept.id && type === 'concept',
      )!
      const source = adapterMappingEntryLocation(
        mapping,
        entry,
        'external',
      )
      diagnostics.push({
        severity: 'error',
        code: 'YMLC103',
        message: `LikeC4 identity "${external}" is not a valid identifier`,
        subject: concept.id,
        path: source.path,
        pointer: source.pointer,
        line: source.line,
        column: source.column,
      })
    }
  }
  if (diagnostics.length > 0) {
    return {
      ok: false,
      diagnostics: diagnostics.sort(diagnosticOrder),
    }
  }

  const brand = resolveBranding(options.branding)
  const lines = [
    `// Generated by ${brand.productName}. Edit the native documents, not this file.`,
    ...(brand.vendorLine === null ? [] : [`// ${brand.vendorLine}`]),
    'model {',
  ]
  for (const concept of concepts) {
    const external = externalByNative.get(concept.id)!
    const semanticKind =
      valueFor(
        projection.claims,
        concept.id,
        'yarramate/concept/kind',
      ) ?? 'element'
    const kind =
      externalConceptKind.get(semanticKind) ?? kindId(semanticKind)
    const name =
      valueFor(
        projection.claims,
        concept.id,
        'yarramate/concept/name',
      ) ?? concept.id
    const description = valueFor(
      projection.claims,
      concept.id,
      'yarramate/concept/description',
    )
    const metadata = metadataLines(
      [
        ['yarramateId', concept.id],
        ['yarramateKind', semanticKind],
        ['yarramateChange', comparisonChange.get(concept.id)],
        ['yarramateGitChange', gitChangeOf(concept.id)],
        [
          'status',
          valueFor(
            projection.claims,
            concept.id,
            'yarramate/lifecycle/status',
          ),
        ],
        [
          'owner',
          referencesFor(
            projection.claims,
            concept.id,
            'yarramate/ownership/owner',
          )[0],
        ],
        [
          'constraints',
          referencesFor(
            projection.claims,
            concept.id,
            'yarramate/constraint/requires',
          ),
        ],
        [
          'references',
          referencesFor(
            projection.claims,
            concept.id,
            'yarramate/reference/refers-to',
          ),
        ],
      ],
      '    ',
    )
    if (description === undefined && metadata.length === 0) {
      lines.push(`  ${external} = ${kind} ${quote(name)}`)
    } else {
      lines.push(
        `  ${external} = ${kind} ${quote(name)} {`,
        ...(description === undefined
          ? []
          : [`    description ${quote(description)}`]),
        ...metadata,
        '  }',
      )
    }
  }
  // `likec4 validate` accepts an empty model as valid, so it can never notice
  // that selected concepts stopped reaching the emitted text. The shortfall is
  // only visible here, and it is measured on the assembled lines rather than on
  // loop iterations so that a dropped definition is what fails, not a skipped
  // turn of the loop.
  const rendered = new Set(
    lines.flatMap((line) => {
      if (!line.startsWith('  ') || line.startsWith('   ')) return []
      const [head, ...rest] = line.slice(2).split(' = ')
      return rest.length > 0 ? [head!] : []
    }),
  )
  const unrendered = concepts.filter(
    ({ id }) => !rendered.has(externalByNative.get(id)!),
  )
  const missing = unrendered[0]
  if (missing !== undefined) {
    const source =
      sourceForConcept(projection.claims, missing.id) ??
      adapterMappingLocation(mapping, 'adapter')
    return {
      ok: false,
      diagnostics: [
        {
          severity: 'error',
          code: 'YMLC112',
          message: `Rendering coverage: ${concepts.length - unrendered.length} of ${concepts.length} projected concepts reached the LikeC4 model`,
          subject: missing.id,
          path: source.path,
          pointer: source.pointer,
          line: source.line,
          column: source.column,
        },
      ],
    }
  }

  const relationships = projection.subjects
    .filter(({ type }) => type === 'relationship')
    .sort((left, right) => left.id.localeCompare(right.id))
  if (relationships.length > 0) lines.push('')
  for (const relationship of relationships) {
    const structural = projection.claims.find(
      (claim) => claim.id === relationship.id,
    )
    if (
      structural === undefined ||
      !('ref' in structural.object)
    ) {
      continue
    }
    const source = externalByNative.get(structural.subject)
    const target = externalByNative.get(structural.object.ref)
    if (source === undefined || target === undefined) continue
    const name = valueFor(
      projection.claims,
      relationship.id,
      'yarramate/relationship/name',
    )
    const description = valueFor(
      projection.claims,
      relationship.id,
      'yarramate/relationship/description',
    )
    const metadata = metadataLines(
      [
        ['yarramateId', relationship.id],
        ['yarramateKind', structural.predicate],
        ['yarramateChange', comparisonChange.get(relationship.id)],
        ['yarramateGitChange', gitChangeOf(relationship.id)],
        [
          'status',
          valueFor(
            projection.claims,
            relationship.id,
            'yarramate/lifecycle/status',
          ),
        ],
        [
          'mode',
          valueFor(
            projection.claims,
            relationship.id,
            'yarramate/access/mode',
          ),
        ],
        [
          'content',
          valueFor(
            projection.claims,
            relationship.id,
            'yarramate/flow/content',
          ),
        ],
        [
          'references',
          referencesFor(
            projection.claims,
            relationship.id,
            'yarramate/reference/refers-to',
          ),
        ],
      ],
      '    ',
    )
    lines.push(
      `  ${source} -[${externalRelationshipKind.get(structural.predicate) ?? kindId(structural.predicate)}]-> ${target}${name === undefined ? '' : ` ${quote(name)}`}${description === undefined && metadata.length === 0 ? '' : ' {'}`,
      ...(description === undefined
        ? []
        : [`    description ${quote(description)}`]),
      ...metadata,
      ...(description === undefined && metadata.length === 0
        ? []
        : ['  }']),
    )
  }

  const viewId = identifier.test(projection.projection.split('@')[0] ?? '')
    ? projection.projection.split('@')[0]!
    : 'index'
  lines.push(
    '}',
    '',
    'views {',
    `  view ${viewId} {`,
    ...(projection.presentation?.title === undefined
      ? []
      : [`    title ${quote(projection.presentation.title)}`]),
    ...(projection.presentation?.description === undefined
      ? []
      : [
          `    description ${quote(projection.presentation.description)}`,
        ]),
    '    include *',
    ...(options.comparison === undefined
      ? []
      : concepts.map((concept) => {
          const external = externalByNative.get(concept.id)!
          const change = comparisonChange.get(concept.id)
          if (change === 'added') {
            return `    style ${external} { color green }`
          }
          if (change === 'removed') {
            return `    style ${external} { color red; border dashed }`
          }
          return `    style ${external} { color gray }`
        })),
    ...(options.gitChange === undefined
      ? []
      : concepts.flatMap((concept) => {
          const external = externalByNative.get(concept.id)!
          const change = gitChangeOf(concept.id)
          if (change === 'new') {
            return [`    style ${external} { color green }`]
          }
          if (change === 'changed') {
            return [`    style ${external} { color amber }`]
          }
          return []
        })),
    `    autoLayout ${projection.presentation?.direction === 'top-down' ? 'TopBottom' : 'LeftRight'}`,
    '  }',
    '}',
    '',
  )
  return { ok: true, source: lines.join('\n') }
}

import type { GraphClaim, SemanticGraph } from './compiler.js'
import {
  ATTESTATION_PREDICATE_PREFIX,
  parseAttestationClaimValue,
  parseConstraintExpectsValue,
} from './compiler.js'
import type {
  EvidenceLocator,
  EvidenceReport,
  EvidenceResult,
} from './evidence.js'
import type { ArtifactCoverage } from './artifact-coverage.js'

export interface AssertedRelationship {
  readonly from: string
  readonly to: string
  readonly kind: string
  readonly name?: string
}

export interface DeclaredSource {
  readonly document: string
  readonly path: string
  readonly pointer: string
  readonly line: number
  readonly column: number
}

export interface ExpectationComparison {
  readonly provider: string
  readonly key: string
  readonly expected: string
  readonly observed: string
  readonly declared: DeclaredSource
}

export interface UnobservedExpectation {
  readonly claim: string
  readonly subject: string
  readonly provider: string
  readonly key: string
  readonly expected: string
  readonly declared: DeclaredSource
}

export interface EvidenceFinding {
  readonly target: {
    readonly type: 'subject' | 'claim'
    readonly id: string
  }
  readonly asserted?: AssertedRelationship
  readonly expectation?: ExpectationComparison
  readonly result: Exclude<EvidenceResult, 'confirmed'>
  readonly provider: string
  readonly evidenceDocument: string
  readonly evidence: EvidenceLocator
}

// A stale attestation is a finding with git provenance (ADR 0074): the
// sign-off predates the current wording of the attested subject. It has
// no evidence document because no provider authored it; git is the
// witness.
export interface StaleAttestationFinding {
  readonly target: {
    readonly type: 'subject'
    readonly id: string
  }
  readonly result: 'stale-attestation'
  readonly attestation: {
    readonly topic: string
    readonly by: string
    readonly on: string
  }
  readonly provider: 'git'
  readonly changedAt?: string
  readonly evidence: EvidenceLocator
}

// A sign-off a machine transcribed is not the act the authority
// performed: the recorder is named in the model, so reconcile reports
// the gap between whose judgment this claims to be and whose hand wrote
// it. The model is the witness; no provider observed anything.
export interface UnconfirmedAttestationFinding {
  readonly target: {
    readonly type: 'subject'
    readonly id: string
  }
  readonly result: 'unconfirmed-attestation'
  readonly attestation: {
    readonly topic: string
    readonly by: string
    readonly recordedBy: string
    readonly on: string
  }
  readonly provider: 'model'
  readonly declared: DeclaredSource
}

export type ReconciliationFinding =
  | EvidenceFinding
  | StaleAttestationFinding
  | UnconfirmedAttestationFinding

export interface AttestationStaleness {
  readonly findings: readonly StaleAttestationFinding[]
  readonly notes: readonly string[]
}

export interface ReconciliationReport {
  readonly format: 'yarramate/reconciliation-report/v1'
  readonly workspace: string
  readonly summary: {
    readonly evidenceDocuments: number
    readonly observations: number
    readonly confirmed: number
    readonly findings: number
    readonly contradicted: number
    readonly unknown: number
    readonly notObserved: number
    /**
     * `not-observed` observations naming no search. A negative claim about a
     * tree nobody read exhaustively is the one result whose message nothing
     * can check, so the ones offering a reader nothing to re-run are counted
     * rather than left to read like any other finding (ADR 0107).
     */
    readonly unsupportedAbsences?: number
    readonly subjectsWithoutEvidence: number
    readonly staleAttestations?: number
    readonly unconfirmedAttestations?: number
    readonly expectationsCompared: number
    readonly expectationsWithoutObservation: number
    /**
     * Files the declared coverage scope selected, and the ones no
     * observation's `repo:` locator claims (ADR 0130). Both appear exactly
     * when coverage was assessed, so a report without them is one that
     * never looked, not one that found nothing.
     */
    readonly artifactsInScope?: number
    readonly unclaimedArtifacts?: number
  }
  readonly findings: readonly ReconciliationFinding[]
  readonly unobservedSubjects?: readonly string[]
  readonly unobservedExpectations?: readonly UnobservedExpectation[]
  /**
   * The coverage patterns as the manifest declared them, echoed so the
   * report is honest about what it was asked to look at (ADR 0130).
   */
  readonly coverageScope?: readonly string[]
  /**
   * In-scope artifacts no observation claims, sorted. Absence, never
   * accusation: no finding is fabricated and `check --strict` never reads
   * this (ADR 0130), the line ADR 0049 drew for unobserved subjects.
   */
  readonly unclaimedArtifacts?: readonly string[]
  readonly notes?: readonly string[]
}

const assertedRelationshipsByClaim = (
  graph: SemanticGraph | undefined,
): ReadonlyMap<string, AssertedRelationship> => {
  const asserted = new Map<string, AssertedRelationship>()
  if (graph === undefined) return asserted
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const names = new Map<string, string>()
  for (const claim of graph.claims) {
    if (
      claim.predicate === 'yarramate/relationship/name' &&
      'value' in claim.object
    ) {
      names.set(claim.subject, claim.object.value)
    }
  }
  for (const claim of graph.claims) {
    if (!relationshipIds.has(claim.id) || !('ref' in claim.object)) continue
    const name = names.get(claim.id)
    asserted.set(claim.id, {
      from: claim.subject,
      to: claim.object.ref,
      kind: claim.predicate,
      ...(name === undefined ? {} : { name }),
    })
  }
  return asserted
}

export const constraintExpectsPredicate = 'yarramate/constraint/expects'

// A finding is now a union (ADR 0074); only the evidence arm can carry an
// expectation, so ordering reads it through one narrowing helper.
const expectationOf = (
  finding: ReconciliationFinding,
): ExpectationComparison | undefined =>
  'expectation' in finding ? finding.expectation : undefined

interface DeclaredExpectation extends UnobservedExpectation {}

// The compiler's parseConstraintExpectsValue is the sole authority for
// decoding the encoded value (ADR 0075). Provider and key admit no
// whitespace, so the first two spaces delimit them and everything after the
// second space is the expected value verbatim, spaces included.
const parseExpectation = (
  claim: GraphClaim,
): DeclaredExpectation | undefined => {
  if (
    claim.predicate !== constraintExpectsPredicate ||
    !('value' in claim.object)
  ) {
    return undefined
  }
  const parts = parseConstraintExpectsValue(claim.object.value)
  if (parts === undefined) return undefined
  return {
    claim: claim.id,
    subject: claim.subject,
    provider: parts.provider,
    key: parts.key,
    expected: parts.value,
    declared: {
      document: claim.source.document,
      path: claim.source.path,
      pointer: claim.source.pointer,
      line: claim.source.line,
      column: claim.source.column,
    },
  }
}

interface ExpectationOutcome {
  readonly findings: readonly EvidenceFinding[]
  readonly unobserved: readonly UnobservedExpectation[]
  readonly compared: number
}

// A declared expectation is matched to observations by provider and key. The
// observation's own target anchors its provenance but does not narrow the
// match: a keyed value is a fact about the project ("this deployment's region
// is X"), and several constraints on different subjects may legitimately
// expect the same fact. Comparison is string equality, deliberately; a
// provider that needs richer matching normalizes before it reports.
const compareExpectations = (
  graph: SemanticGraph | undefined,
  reports: readonly EvidenceReport[],
): ExpectationOutcome => {
  if (graph === undefined) {
    return { findings: [], unobserved: [], compared: 0 }
  }
  const findings: EvidenceFinding[] = []
  const unobserved: UnobservedExpectation[] = []
  let compared = 0
  for (const claim of graph.claims) {
    const expectation = parseExpectation(claim)
    if (expectation === undefined) continue
    let matched = false
    for (const report of reports) {
      if (report.provider !== expectation.provider) continue
      for (const observation of report.observations) {
        if (
          observation.key !== expectation.key ||
          observation.value === undefined
        ) {
          continue
        }
        matched = true
        if (observation.value === expectation.expected) continue
        findings.push({
          target: { type: 'claim', id: expectation.claim },
          expectation: {
            provider: expectation.provider,
            key: expectation.key,
            expected: expectation.expected,
            observed: observation.value,
            declared: expectation.declared,
          },
          result: 'contradicted',
          provider: report.provider,
          evidenceDocument: report.evidence,
          evidence: observation.evidence,
        })
      }
    }
    if (!matched) unobserved.push(expectation)
    else compared += 1
  }
  return {
    findings,
    unobserved: [...unobserved].sort(
      (left, right) =>
        left.claim.localeCompare(right.claim) ||
        left.key.localeCompare(right.key),
    ),
    compared,
  }
}

const unobservedCurrentConcepts = (
  graph: SemanticGraph | undefined,
  reports: readonly EvidenceReport[],
): readonly string[] => {
  if (graph === undefined) return []
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const claimsById = new Map(graph.claims.map((claim) => [claim.id, claim]))
  const observed = new Set<string>()
  for (const report of reports) {
    for (const observation of report.observations) {
      if ('subject' in observation) {
        observed.add(observation.subject)
        continue
      }
      const claim = claimsById.get(observation.claim)
      if (claim === undefined) continue
      observed.add(claim.subject)
      if (relationshipIds.has(claim.id) && 'ref' in claim.object) {
        observed.add(claim.object.ref)
      }
    }
  }
  const conceptIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'concept')
      .map(({ id }) => id),
  )
  return graph.claims
    .filter(
      (claim) =>
        claim.predicate === 'yarramate/lifecycle/status' &&
        'value' in claim.object &&
        claim.object.value === 'current' &&
        conceptIds.has(claim.subject) &&
        !observed.has(claim.subject),
    )
    .map(({ subject }) => subject)
    .sort((left, right) => left.localeCompare(right))
}

// An observation claims an artifact when its locator is `repo:<path>`,
// read syntactically: any `#fragment` stripped, a directory claiming
// everything beneath it, any other scheme claiming nothing. Resolution
// and external validity stay with the provider (ADR 0130) — nothing here
// opens a file or checks one exists.
const claimedArtifactPaths = (
  reports: readonly EvidenceReport[],
): ReadonlySet<string> => {
  const claimed = new Set<string>()
  for (const report of reports) {
    for (const observation of report.observations) {
      const uri = observation.evidence.uri
      if (!uri.startsWith('repo:')) continue
      const located = uri.slice('repo:'.length)
      const fragment = located.indexOf('#')
      // Trailing slashes are stripped with a loop, not a regex: an
      // anchored /\/+$/ is polynomial on a locator of many slashes, and
      // locators are library input.
      let path = fragment === -1 ? located : located.slice(0, fragment)
      while (path.endsWith('/')) path = path.slice(0, -1)
      if (path.length > 0) claimed.add(path)
    }
  }
  return claimed
}

const isClaimed = (
  claimed: ReadonlySet<string>,
  artifact: string,
): boolean => {
  if (claimed.has(artifact)) return true
  for (const path of claimed) {
    if (artifact.startsWith(`${path}/`)) return true
  }
  return false
}

interface CoverageOutcome {
  readonly scope?: readonly string[]
  readonly artifacts?: number
  readonly unclaimed?: readonly string[]
  readonly notes: readonly string[]
}

const assessArtifactCoverage = (
  coverage: ArtifactCoverage | undefined,
  reports: readonly EvidenceReport[],
): CoverageOutcome => {
  // An absent argument is a caller that never looked (the strict gate);
  // an unassessed derivation is a reconcile that looked and could not,
  // and says why (ADR 0130, the ADR 0074 parallel).
  if (coverage === undefined) return { notes: [] }
  if (!coverage.assessed) {
    return {
      notes: [`Artifact coverage was not assessed: ${coverage.reason}.`],
    }
  }
  const notes: string[] = []
  if (coverage.scope.length === 0) {
    notes.push(
      'The workspace manifest declares an empty coverage scope, so no artifacts were assessed.',
    )
  }
  // A dead glob is indistinguishable from a typo, and silently
  // contributing nothing is how a mistyped pattern would report full
  // coverage. A note, not a refusal: a coverage scope is a lens, not
  // load-bearing input (ADR 0130).
  for (const { pattern, artifacts } of coverage.scope) {
    if (artifacts.length === 0) {
      notes.push(`Coverage pattern "${pattern}" matched no artifacts.`)
    }
  }
  const artifacts = [
    ...new Set(coverage.scope.flatMap(({ artifacts }) => artifacts)),
  ].sort((left, right) => left.localeCompare(right))
  const claimed = claimedArtifactPaths(reports)
  return {
    scope: coverage.scope.map(({ pattern }) => pattern),
    artifacts: artifacts.length,
    unclaimed: artifacts.filter((artifact) => !isClaimed(claimed, artifact)),
    notes,
  }
}

// A judgment a machine transcribed is not the act the authority
// performed. The recorder is in the model, so the difference is
// derivable here: an authority who wrote the record in their own hand
// names nobody else, and anything else is a claim awaiting confirmation.
const unconfirmedAttestations = (
  graph: SemanticGraph | undefined,
): readonly UnconfirmedAttestationFinding[] => {
  if (graph === undefined) return []
  return graph.claims.flatMap((claim) => {
    if (!claim.predicate.startsWith(ATTESTATION_PREDICATE_PREFIX)) return []
    if (!('value' in claim.object)) return []
    const parts = parseAttestationClaimValue(claim.object.value)
    const recordedBy = parts?.recordedBy
    if (parts === undefined || recordedBy === undefined) return []
    // The authority is qualified; a recorder naming the same subject,
    // long form or short, is that authority signing for themselves.
    const local = parts.by.slice(parts.by.indexOf('#') + 1)
    if (recordedBy === parts.by || recordedBy === local) return []
    return [
      {
        target: { type: 'subject', id: claim.subject } as const,
        result: 'unconfirmed-attestation' as const,
        attestation: {
          topic: claim.predicate.slice(ATTESTATION_PREDICATE_PREFIX.length),
          by: parts.by,
          recordedBy,
          on: parts.on,
        },
        provider: 'model' as const,
        declared: claim.source,
      },
    ]
  })
}

export function reconcileEvidenceReports(
  workspace: string,
  reports: readonly EvidenceReport[],
  graph?: SemanticGraph,
  staleness?: AttestationStaleness,
  coverage?: ArtifactCoverage,
): ReconciliationReport {
  const assertedByClaim = assertedRelationshipsByClaim(graph)
  const unobservedSubjects = unobservedCurrentConcepts(graph, reports)
  const expectations = compareExpectations(graph, reports)
  const unconfirmed = unconfirmedAttestations(graph)
  const assessedCoverage = assessArtifactCoverage(coverage, reports)
  const summary = {
    evidenceDocuments: reports.length,
    observations: 0,
    confirmed: 0,
    findings: 0,
    contradicted: 0,
    unknown: 0,
    notObserved: 0,
    unsupportedAbsences: 0,
    subjectsWithoutEvidence: unobservedSubjects.length,
    // Attestation staleness is assessed only when the caller derived it
    // (the reconcile command); the counter appears exactly then, so a
    // report without it is one that never looked, not one that found
    // nothing.
    ...(staleness === undefined
      ? {}
      : { staleAttestations: staleness.findings.length }),
    // Recorder disagreement is derived from the model alone, so the
    // counter appears whenever there was a graph to read.
    ...(graph === undefined
      ? {}
      : { unconfirmedAttestations: unconfirmed.length }),
    expectationsCompared: expectations.compared,
    expectationsWithoutObservation: expectations.unobserved.length,
    // Coverage counters appear exactly when the scope was assessed
    // (ADR 0130): a report without them never looked; a report carrying
    // zero looked and found everything claimed.
    ...(assessedCoverage.artifacts === undefined
      ? {}
      : {
          artifactsInScope: assessedCoverage.artifacts,
          unclaimedArtifacts: assessedCoverage.unclaimed?.length ?? 0,
        }),
  }
  const findings: ReconciliationFinding[] = [
    ...(staleness?.findings ?? []),
    ...unconfirmed,
  ]
  const absenceNotes: string[] = []
  for (const report of reports) {
    summary.observations += report.observations.length
    for (const observation of report.observations) {
      if (observation.result === 'confirmed') {
        summary.confirmed += 1
        continue
      }
      if (observation.result === 'not-observed') {
        summary.notObserved += 1
        // A not-observed asserts a negative, and is the only result whose
        // message nothing else in the pipeline can check: the locator it
        // carries points at what the author looked at, not at the absence
        // they claim. One naming no search offers a reader nothing to
        // re-run, so it is counted and named rather than left to read like
        // a checked finding (ADR 0107).
        if ((observation.searched ?? []).length === 0) {
          summary.unsupportedAbsences += 1
          const named =
            'subject' in observation ? observation.subject : observation.claim
          absenceNotes.push(
            `The not-observed observation for ${named} names no search, ` +
              `so nothing here can be re-run to test the absence it asserts.`,
          )
        }
      } else {
        summary[observation.result] += 1
      }
      const target =
        'subject' in observation
          ? ({ type: 'subject', id: observation.subject } as const)
          : ({ type: 'claim', id: observation.claim } as const)
      const asserted =
        target.type === 'claim' ? assertedByClaim.get(target.id) : undefined
      findings.push({
        target,
        ...(asserted === undefined ? {} : { asserted }),
        result: observation.result,
        provider: report.provider,
        evidenceDocument: report.evidence,
        evidence: observation.evidence,
      })
    }
  }
  // A disagreeing expectation is an ordinary contradicted finding: same
  // taxonomy, same counters, same strict-check consequence (ADR 0075).
  for (const finding of expectations.findings) {
    summary.contradicted += 1
    findings.push(finding)
  }
  findings.sort((left, right) =>
    left.target.id.localeCompare(right.target.id) ||
    left.target.type.localeCompare(right.target.type) ||
    left.provider.localeCompare(right.provider) ||
    ('evidenceDocument' in left ? left.evidenceDocument : '').localeCompare(
      'evidenceDocument' in right ? right.evidenceDocument : '',
    ) ||
    ('attestation' in left ? left.attestation.topic : '').localeCompare(
      'attestation' in right ? right.attestation.topic : '',
    ) ||
    (expectationOf(left)?.key ?? '').localeCompare(
      expectationOf(right)?.key ?? '',
    ) ||
    (expectationOf(left)?.observed ?? '').localeCompare(
      expectationOf(right)?.observed ?? '',
    ),
  )
  summary.findings = findings.length
  const notes = [
    ...(staleness?.notes ?? []),
    ...absenceNotes,
    ...assessedCoverage.notes,
  ]
  return {
    format: 'yarramate/reconciliation-report/v1',
    workspace,
    summary,
    findings,
    ...(unobservedSubjects.length === 0 ? {} : { unobservedSubjects }),
    ...(expectations.unobserved.length === 0
      ? {}
      : { unobservedExpectations: expectations.unobserved }),
    ...(assessedCoverage.scope === undefined
      ? {}
      : { coverageScope: assessedCoverage.scope }),
    ...(assessedCoverage.unclaimed === undefined ||
    assessedCoverage.unclaimed.length === 0
      ? {}
      : { unclaimedArtifacts: assessedCoverage.unclaimed }),
    ...(notes.length === 0 ? {} : { notes }),
  }
}

/**
 * The responsibility matrix (#557, ADR 0159): RACI over the model, derived
 * the way the RTM is derived and never authored. Rows are subjects; columns
 * are the people the model holds; a cell is the letters one person carries
 * on one row, each letter with the claim that put it there.
 *
 * Accountable is the `yarramate/ownership/owner` claim. Responsible,
 * Consulted and Informed are the three `yarramate/policy@0.2` relationship
 * kinds, read through the lineage so a profile's own subkind counts. A
 * person named as `by` on an attestation of a subject was consulted on it:
 * derived into the cell with the topic and the date, never written back as
 * an edge, and never counted toward a gap.
 *
 * Deterministic: identical inputs give identical bytes, so CI can diff it.
 */
import type {
  GraphClaim,
  ResolvedProfileContext,
  SemanticGraph,
} from './compiler.js'
import {
  ATTESTATION_PREDICATE_PREFIX,
  parseAttestationClaimValue,
} from './graph-claims.js'
import {
  OWNER_PREDICATE,
  isPeopleKind,
  responsibilityLetterOf,
  type ResponsibilityLetter,
} from './responsibility-kinds.js'

export type RaciLetter = 'A' | ResponsibilityLetter

/** Where a letter came from: an authored line a reader can open. */
export interface ResponsibilitySource {
  readonly path: string
  readonly line: number
}

export type ResponsibilityCellSource =
  | { readonly kind: 'owner'; readonly source: ResponsibilitySource }
  | {
      readonly kind: 'relationship'
      readonly relationship: string
      readonly relationshipKind: string
      readonly source: ResponsibilitySource
    }
  | {
      readonly kind: 'attestation'
      readonly topic: string
      readonly on: string
      readonly source: ResponsibilitySource
    }

export interface ResponsibilityCell {
  /** In A, R, C, I order, each at most once. */
  readonly letters: readonly RaciLetter[]
  readonly sources: readonly ResponsibilityCellSource[]
}

export interface ResponsibilityPerson {
  readonly id: string
  readonly name: string
  readonly kind: string
  /**
   * Whether something serves this person. A served actor with no letter is
   * a consumer, not a responsibility holder; `idle` carries the flag so a
   * renderer can leave consumers out.
   */
  readonly served: boolean
}

export interface ResponsibilityRow {
  readonly subject: string
  readonly name: string
  readonly kind: string
  /** By person id; only people with a letter on this row appear. */
  readonly cells: Readonly<Record<string, ResponsibilityCell>>
}

export interface ResponsibilityMatrix {
  readonly format: 'yarramate/responsibility/v1'
  readonly workspace: string
  /** The projection the rows came from, when they came from one. */
  readonly projection?: string
  readonly summary: {
    readonly rows: number
    readonly people: number
    readonly cells: number
    readonly noAccountable: number
    readonly noResponsible: number
    readonly idle: number
  }
  readonly people: readonly ResponsibilityPerson[]
  readonly rows: readonly ResponsibilityRow[]
  readonly gaps: {
    /** Rows with no A. */
    readonly noAccountable: readonly string[]
    /** Rows with no R. A derived C never fills either. */
    readonly noResponsible: readonly string[]
  }
  /** People with no letter on any row of this matrix. */
  readonly idle: readonly ResponsibilityPerson[]
}

export interface ResponsibilityOptions {
  /**
   * The subjects that get a row, in any order; absent, every concept that is
   * not a person. A projection's subjects are the usual source.
   */
  readonly rows?: readonly string[]
  readonly projection?: string
}

const LETTER_ORDER: readonly RaciLetter[] = ['A', 'R', 'C', 'I']

// A subject id is qualified (`doc#local`) only where the local id alone is
// ambiguous, so the document half is empty for most ids.
const documentOf = (subject: string): string => {
  const hash = subject.indexOf('#')
  return hash === -1 ? '' : subject.slice(0, hash)
}

const bySubjectOrder = (left: string, right: string): number =>
  documentOf(left).localeCompare(documentOf(right)) ||
  left.localeCompare(right)

const citation = (claim: GraphClaim): ResponsibilitySource => ({
  path: claim.source.path,
  line: claim.source.line,
})

const localKind = (kind: string): string => kind.slice(kind.indexOf('#') + 1)

interface CellDraft {
  readonly letters: Set<RaciLetter>
  readonly sources: ResponsibilityCellSource[]
}

export function buildResponsibilityMatrix(
  workspace: string,
  graph: SemanticGraph,
  profileContext: ResolvedProfileContext,
  options: ResponsibilityOptions = {},
): ResponsibilityMatrix {
  const conceptIds = new Set(
    graph.subjects.filter(({ type }) => type === 'concept').map(({ id }) => id),
  )
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const values = new Map<string, string>()
  const ownerClaims = new Map<string, GraphClaim>()
  const attestations = new Map<string, GraphClaim[]>()
  const definingClaims: GraphClaim[] = []
  for (const claim of graph.claims) {
    if (relationshipIds.has(claim.id) && 'ref' in claim.object) {
      definingClaims.push(claim)
      continue
    }
    if (claim.predicate === OWNER_PREDICATE && 'ref' in claim.object) {
      ownerClaims.set(claim.subject, claim)
      continue
    }
    if (!('value' in claim.object)) continue
    if (claim.predicate.startsWith(ATTESTATION_PREDICATE_PREFIX)) {
      attestations.set(claim.subject, [
        ...(attestations.get(claim.subject) ?? []),
        claim,
      ])
      continue
    }
    values.set(`${claim.subject} ${claim.predicate}`, claim.object.value)
  }
  const value = (subject: string, predicate: string): string | undefined =>
    values.get(`${subject} ${predicate}`)
  const kindOf = (subject: string): string =>
    value(subject, 'yarramate/concept/kind') ?? ''
  const nameOf = (subject: string): string =>
    value(subject, 'yarramate/concept/name') ?? subject
  const isPerson = (subject: string): boolean => {
    const kind = kindOf(subject)
    return isPeopleKind(profileContext.conceptKindLineages.get(kind), kind)
  }
  const isServing = (kind: string): boolean =>
    (profileContext.relationshipKindLineages.get(kind) ?? [kind])[0] ===
    'yarramate/core@0.1#serving'

  const served = new Set<string>()
  for (const claim of definingClaims) {
    if (isServing(claim.predicate) && 'ref' in claim.object) {
      served.add(claim.object.ref)
    }
  }

  const rowIds = (options.rows ?? [...conceptIds])
    .filter((id) => conceptIds.has(id) && !isPerson(id))
    .sort(bySubjectOrder)
  const rowSet = new Set(rowIds)

  // Every person the model holds is a column; anyone else who carries a
  // letter joins them, so the matrix says what the model says.
  const columns = new Set<string>([...conceptIds].filter(isPerson))
  const cells = new Map<string, Map<string, CellDraft>>()
  const cell = (row: string, person: string): CellDraft => {
    columns.add(person)
    const byPerson = cells.get(row) ?? new Map<string, CellDraft>()
    cells.set(row, byPerson)
    const draft = byPerson.get(person) ?? {
      letters: new Set<RaciLetter>(),
      sources: [],
    }
    byPerson.set(person, draft)
    return draft
  }

  // Owners first, then the edges, then the attestations, so a cell's
  // sources read in the order a person would look for them.
  for (const row of rowIds) {
    const owner = ownerClaims.get(row)
    if (owner === undefined || !('ref' in owner.object)) continue
    const draft = cell(row, owner.object.ref)
    draft.letters.add('A')
    draft.sources.push({ kind: 'owner', source: citation(owner) })
  }
  for (const claim of definingClaims) {
    if (!('ref' in claim.object) || !rowSet.has(claim.object.ref)) continue
    const letter = responsibilityLetterOf(
      profileContext.relationshipKindLineages.get(claim.predicate),
      claim.predicate,
    )
    if (letter === null) continue
    const draft = cell(claim.object.ref, claim.subject)
    draft.letters.add(letter)
    draft.sources.push({
      kind: 'relationship',
      relationship: claim.id,
      relationshipKind: claim.predicate,
      source: citation(claim),
    })
  }
  for (const row of rowIds) {
    for (const attestation of attestations.get(row) ?? []) {
      if (!('value' in attestation.object)) continue
      const parts = parseAttestationClaimValue(attestation.object.value)
      if (parts === undefined) continue
      const draft = cell(row, parts.by)
      draft.letters.add('C')
      draft.sources.push({
        kind: 'attestation',
        topic: attestation.predicate.slice(ATTESTATION_PREDICATE_PREFIX.length),
        on: parts.on,
        source: citation(attestation),
      })
    }
  }

  const personOf = (id: string): ResponsibilityPerson => ({
    id,
    name: nameOf(id),
    kind: kindOf(id),
    served: served.has(id),
  })
  const people = [...columns].sort(bySubjectOrder).map(personOf)
  const lettered = new Set<string>()
  let cellCount = 0
  const rows: ResponsibilityRow[] = rowIds.map((subject) => {
    const byPerson = cells.get(subject) ?? new Map<string, CellDraft>()
    const entries = [...byPerson.entries()].sort(([left], [right]) =>
      bySubjectOrder(left, right),
    )
    const finished: Record<string, ResponsibilityCell> = {}
    for (const [person, draft] of entries) {
      lettered.add(person)
      cellCount += 1
      finished[person] = {
        letters: LETTER_ORDER.filter((letter) => draft.letters.has(letter)),
        sources: draft.sources,
      }
    }
    return {
      subject,
      name: nameOf(subject),
      kind: kindOf(subject),
      cells: finished,
    }
  })
  const has = (row: ResponsibilityRow, letter: RaciLetter): boolean =>
    Object.values(row.cells).some(({ letters }) => letters.includes(letter))
  const noAccountable = rows
    .filter((row) => !has(row, 'A'))
    .map(({ subject }) => subject)
  const noResponsible = rows
    .filter((row) => !has(row, 'R'))
    .map(({ subject }) => subject)
  const idle = people.filter(({ id }) => !lettered.has(id))
  return {
    format: 'yarramate/responsibility/v1',
    workspace,
    ...(options.projection === undefined
      ? {}
      : { projection: options.projection }),
    summary: {
      rows: rows.length,
      people: people.length,
      cells: cellCount,
      noAccountable: noAccountable.length,
      noResponsible: noResponsible.length,
      idle: idle.length,
    },
    people,
    rows,
    gaps: { noAccountable, noResponsible },
    idle,
  }
}

const escapeCell = (text: string): string => text.replaceAll('|', '\\|')

const list = (ids: readonly string[]): string =>
  ids.length === 0 ? 'none' : ids.map((id) => `\`${id}\``).join(', ')

/**
 * The matrix as one markdown table a person reads, with the gaps and the
 * idle people under it. A C that comes only from attestations wears an
 * asterisk, so a standing role and a recorded judgement read differently.
 */
export function renderResponsibilityMarkdown(
  matrix: ResponsibilityMatrix,
): string {
  const lines: string[] = ['# Responsibility matrix', '']
  const where =
    matrix.projection === undefined
      ? ''
      : `, projection \`${matrix.projection}\``
  const rowsWord = matrix.summary.rows === 1 ? 'row' : 'rows'
  const peopleWord = matrix.summary.people === 1 ? 'person' : 'people'
  lines.push(
    `Workspace \`${matrix.workspace}\`${where}: ${matrix.summary.rows} ${rowsWord}, ${matrix.summary.people} ${peopleWord}. Derived from the record; edit the native documents, not this file.`,
    '',
  )
  if (matrix.rows.length === 0) {
    lines.push('_No rows._', '')
  } else {
    const header = [
      'Subject',
      'Kind',
      ...matrix.people.map(({ name }) => escapeCell(name)),
    ]
    lines.push(
      `| ${header.join(' | ')} |`,
      `|${header.map(() => '---').join('|')}|`,
    )
    let attested = false
    for (const row of matrix.rows) {
      const cells = matrix.people.map(({ id }) => {
        const cell = row.cells[id]
        if (cell === undefined) return ''
        return cell.letters
          .map((letter) => {
            if (letter !== 'C') return letter
            if (cell.sources.some(({ kind }) => kind === 'relationship')) {
              return 'C'
            }
            attested = true
            return 'C*'
          })
          .join(' ')
      })
      lines.push(
        `| ${escapeCell(row.name)} (\`${row.subject}\`) | ${localKind(row.kind)} | ${cells.join(' | ')} |`,
      )
    }
    lines.push('')
    if (attested) {
      lines.push(
        '\\* consulted by attestation: a recorded judgement, not a standing role.',
        '',
      )
    }
  }
  lines.push(
    '## Gaps',
    '',
    `- No accountable: ${list(matrix.gaps.noAccountable)}`,
    `- No responsible: ${list(matrix.gaps.noResponsible)}`,
    '',
    '## Idle',
    '',
  )
  if (matrix.idle.length === 0) {
    lines.push('_Everyone holds a letter._')
  } else {
    for (const person of matrix.idle) {
      lines.push(
        `- ${escapeCell(person.name)} (\`${person.id}\`)${person.served ? ', served' : ''}`,
      )
    }
  }
  lines.push('')
  return `${lines.join('\n')}\n`
}

