export const humanDiagnostics = (
  diagnostics: readonly Pick<
    Diagnostic,
    'path' | 'line' | 'column' | 'code' | 'message'
  >[],
) =>
  diagnostics
    .map(
      (diagnostic) =>
        `${diagnostic.path}:${diagnostic.line}:${diagnostic.column} error ${diagnostic.code} ${diagnostic.message}\n`,
    )
    .join('')

export const sortDiagnostics = <T extends Diagnostic>(
  diagnostics: readonly T[],
) =>
  [...diagnostics].sort(
    (left, right) =>
      left.path.localeCompare(right.path) ||
      left.line - right.line ||
      left.column - right.column ||
      left.code.localeCompare(right.code) ||
      left.message.localeCompare(right.message),
  )

export const resolveCliWorkspaceSources = (
  paths: readonly string[],
  cwd: string,
  options: {
    readonly includeAdapterMappings?: boolean
  } = {},
):
  | {
      readonly ok: true
      readonly paths: readonly string[]
      readonly projections: readonly string[]
      readonly evidence: readonly string[]
      readonly contracts: readonly string[]
      /** Pattern documents, which ride in `paths` and are not documents. */
      readonly patterns: readonly string[]
      /**
       * Question catalogues the workspace carries (#345). Handed over rather
       * than resolved-and-dropped, which is the #268 failure recorded below:
       * a category a manifest declares and no verb receives is ignored with
       * no symptom.
       */
      readonly questions: readonly string[]
    }
  | {
      readonly ok: false
      readonly diagnostics: readonly Diagnostic[]
    } => {
  if (paths.length !== 1) {
    return {
      ok: true,
      paths,
      projections: [],
      evidence: [],
      contracts: [],
      patterns: [],
      questions: [],
    }
  }
  const manifestPath = paths[0]
  if (manifestPath === undefined) {
    return {
      ok: true,
      paths,
      projections: [],
      evidence: [],
      contracts: [],
      patterns: [],
      questions: [],
    }
  }
  const source = readFileSync(resolve(cwd, manifestPath), 'utf8')
  if (
    parseDocument(source).get('format') !== 'yarramate/workspace/v1'
  ) {
    return {
      ok: true,
      paths,
      projections: [],
      evidence: [],
      contracts: [],
      patterns: [],
      questions: [],
    }
  }
  const loaded = loadWorkspaceManifest(
    { path: manifestPath, source },
    cwd,
  )
  return loaded.ok
    ? {
        ok: true,
        paths: [
          ...loaded.workspace.profiles,
          // Patterns are compiler input like profiles, and were resolved from
          // the manifest without ever being handed over (#268): a pattern
          // document a workspace declared was silently ignored by every verb,
          // and an instance binding parts then failed YM419 for a pattern that
          // was sitting right there in the manifest. Every test passed because
          // each hands the compiler an explicit source list rather than
          // resolving a workspace - the check that passes was not the check
          // that mattered.
          ...loaded.workspace.patterns,
          ...loaded.workspace.documents,
          ...(options.includeAdapterMappings === true
            ? loaded.workspace.adapterMappings
            : []),
        ],
        projections: loaded.workspace.projections,
        evidence: loaded.workspace.evidence,
        contracts: loaded.workspace.contracts,
        patterns: loaded.workspace.patterns,
        questions: loaded.workspace.questions ?? [],
      }
    : { ok: false, diagnostics: loaded.diagnostics }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://yarramate.org/schema/pattern/v1",
  "title": "YarraMate structural pattern",
  "description": "The shape a concept kind promises: the parts an instance binds and the wiring the compiler mints between them (ADR 0123). A pattern declares structure; a profile declares vocabulary. Expansion is compile-time and lands in the semantic graph, never in a document.",
  "type": "object",
  "additionalProperties": false,
  "required": ["format", "id", "version", "patterns"],
  "properties": {
    "format": {
      "const": "yarramate/pattern/v1"
    },
    "id": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "version": {
      "type": "string",
      "pattern": "^[0-9]+\\.[0-9]+$"
    },
    "patterns": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/pattern"
      }
    }
  },
  "$defs": {
    "pattern": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "parts", "wiring"],
      "properties": {
        "kind": {
          "description": "The globally qualified concept kind this pattern shapes. The kind's anchor is whatever the profile says it specializes; a pattern never restates it.",
          "$ref": "#/$defs/qualifiedKind"
        },
        "parts": {
          "description": "The slots an instance binds, by name. A slot names the kind the bound subject must be, and whether an instance must bind it.",
          "type": "object",
          "minProperties": 1,
          "additionalProperties": false,
          "propertyNames": {
            "$ref": "#/$defs/slotName"
          },
          "patternProperties": {
            "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$": {
              "$ref": "#/$defs/part"
            }
          }
        },
        "ports": {
          "description": "Where a macro-grain edge lands canonically (#268 phase 2, ADR 0124). A relationship authored between two instances whose patterns both declare a port for its kind is expanded: `out` names the slot it leaves from on the source instance, `in` the slot it arrives at on the target. The macro edge itself survives - it is an authored fact, which is what gives a collapsed view edges to draw.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/port"
          }
        },
        "wiring": {
          "description": "The relationships the compiler mints between an instance and its bound parts. Where an authored relationship already says exactly this, nothing is minted. Any other authored relationship between the same pair contradicts the pattern and fails compilation.",
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/wire"
          }
        }
      }
    },
    "part": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind"],
      "properties": {
        "kind": {
          "$ref": "#/$defs/qualifiedKind"
        },
        "required": {
          "description": "An instance that leaves a required slot unbound fails compilation (YM416). Absent means optional.",
          "type": "boolean"
        },
        "kindMatching": {
          "description": "How a bound subject's kind is matched against this part's kind (#449). \"exact\" (the default) admits only that kind. \"descendants\" admits any kind whose lineage includes it, so one slot can admit a family of variant subkinds and choosing the variant is what opens the next set of questions. The word means the same here as on catalogue selectors and on missing-relationship, so it is one vocabulary rather than two. It fails safe: minted wiring is checked against the relationship table using the ACTUAL bound subjects' kinds, not the slot kinds, so a descendant that is not a legal endpoint is still refused by the ordinary relationship check.",
          "enum": ["exact", "descendants"]
        }
      }
    },
    "port": {
      "type": "object",
      "additionalProperties": false,
      "required": ["kind", "out", "in"],
      "properties": {
        "kind": {
          "$ref": "#/$defs/qualifiedKind"
        },
        "out": {
          "description": "The slot a macro edge of this kind leaves from, on the SOURCE instance. Never `self`: an edge that left from the instance would be the macro edge again.",
          "$ref": "#/$defs/slotName"
        },
        "in": {
          "description": "The slot a macro edge of this kind arrives at, on the TARGET instance.",
          "$ref": "#/$defs/slotName"
        }
      }
    },
    "wire": {
      "type": "object",
      "additionalProperties": false,
      "required": ["from", "kind", "to"],
      "properties": {
        "from": {
          "$ref": "#/$defs/endpoint"
        },
        "kind": {
          "$ref": "#/$defs/qualifiedKind"
        },
        "to": {
          "$ref": "#/$defs/endpoint"
        }
      }
    },
    "endpoint": {
      "description": "A slot name declared in `parts`, or `self` for the instance itself.",
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "slotName": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$"
    },
    "qualifiedKind": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9-]*(?:/[a-z][a-z0-9-]*)+@[0-9]+\\.[0-9]+#[a-z][A-Za-z0-9-]*$"
    }
  }
}

import type {
  Diagnostic,
  SemanticGraph,
  WorkspaceSource,
} from './compiler.js'
import {
  diagnosticOrder,
  loadSourceDocument,
  locateSourcePath,
  type SourceLocation,
} from './source-document.js'
import { validateAdapterMapping as validateSchema } from './schema-validation.js'
import adapterMappingSchema from '../schema/yarramate-adapter-mapping.schema.json' with {
  type: 'json',
}



export interface AdapterSubjectMapping {
  readonly native: string
  readonly external: string
  readonly type: 'concept' | 'relationship'
}

export interface AdapterMapping {
  readonly format: 'yarramate/adapter-mapping/v1'
  readonly id: string
  readonly version: string
  readonly adapter: string
  readonly mappings: readonly AdapterSubjectMapping[]
}

type MappingLocation = SourceLocation

interface AdapterMappingLocations {
  readonly id: MappingLocation
  readonly adapter: MappingLocation
  readonly mappings: readonly Readonly<
    Record<'native' | 'external' | 'type', MappingLocation>
  >[]
}

const mappingLocations = new WeakMap<AdapterMapping, AdapterMappingLocations>()

export type AdapterMappingLoadResult =
  | { readonly ok: true; readonly mapping: AdapterMapping }
  | { readonly ok: false; readonly diagnostics: readonly Diagnostic[] }

export type AdapterMappingValidationResult =
  | { readonly ok: true; readonly mapping: AdapterMapping }
  | { readonly ok: false; readonly diagnostics: readonly Diagnostic[] }

export type AdapterMappingsValidationResult =
  | { readonly ok: true; readonly mappings: readonly AdapterMapping[] }
  | { readonly ok: false; readonly diagnostics: readonly Diagnostic[] }

export function loadAdapterMapping(
  source: WorkspaceSource,
): AdapterMappingLoadResult {
  const loaded = loadSourceDocument<AdapterMapping>(
    source,
    validateSchema,
    'Adapter mapping',
  )
  if (!loaded.ok) return loaded
  const { value, yaml, lineCounter } = loaded.document

  const mapping: AdapterMapping = {
    ...value,
    mappings: [...value.mappings].sort(
      (left, right) =>
        left.native.localeCompare(right.native) ||
        left.external.localeCompare(right.external) ||
        left.type.localeCompare(right.type),
    ),
  }
  const locateNode = (
    yamlPath: readonly (string | number)[],
    pointer: string,
  ): MappingLocation =>
    locateSourcePath(
      source.path,
      yaml,
      lineCounter,
      yamlPath,
      pointer,
    )
  mappingLocations.set(mapping, {
    id: locateNode(['id'], '/id'),
    adapter: locateNode(['adapter'], '/adapter'),
    mappings: mapping.mappings.map((entry) => {
      const authoredIndex = value.mappings.indexOf(entry)
      const locate = (
        field: 'native' | 'external' | 'type',
      ): MappingLocation =>
        locateNode(
          ['mappings', authoredIndex, field],
          `/mappings/${authoredIndex}/${field}`,
        )
      return {
        native: locate('native'),
        external: locate('external'),
        type: locate('type'),
      }
    }),
  })
  return { ok: true, mapping }
}

export function adapterMappingLocation(
  mapping: AdapterMapping,
  field: 'id' | 'adapter',
): SourceLocation {
  return (
    mappingLocations.get(mapping)?.[field] ?? {
      path: `${mapping.id}.mapping.yaml`,
      pointer: `/${field}`,
      line: 1,
      column: 1,
    }
  )
}

export function adapterMappingEntryLocation(
  mapping: AdapterMapping,
  entry: AdapterSubjectMapping,
  field: 'native' | 'external' | 'type',
): SourceLocation {
  const index = mapping.mappings.indexOf(entry)
  return (
    mappingLocations.get(mapping)?.mappings[index]?.[field] ?? {
      path: `${mapping.id}.mapping.yaml`,
      pointer: `/mappings/${Math.max(index, 0)}/${field}`,
      line: 1,
      column: 1,
    }
  )
}

export function validateAdapterMapping(
  graph: SemanticGraph,
  mapping: AdapterMapping,
): AdapterMappingValidationResult {
  const subjectTypes = new Map(
    graph.subjects.map(({ id, type }) => [id, type] as const),
  )
  const locations = mappingLocations.get(mapping)?.mappings ?? []
  const diagnostics: Diagnostic[] = []
  const seenNativeSubjects = new Set<string>()
  const seenExternalIdentities = new Set<string>()

  for (const [index, entry] of mapping.mappings.entries()) {
    const fallback = (field: 'native' | 'external' | 'type') => ({
      path: `${mapping.id}.mapping.yaml`,
      pointer: `/mappings/${index}/${field}`,
      line: 1,
      column: 1,
    })
    const nativeLocation = locations[index]?.native ?? fallback('native')
    const externalLocation =
      locations[index]?.external ?? fallback('external')
    const typeLocation = locations[index]?.type ?? fallback('type')
    const actualType = subjectTypes.get(entry.native)
    if (actualType === undefined) {
      diagnostics.push({
        severity: 'error',
        code: 'YM601',
        message: `Native subject "${entry.native}" does not exist`,
        path: nativeLocation.path,
        pointer: nativeLocation.pointer,
        line: nativeLocation.line,
        column: nativeLocation.column,
      })
    } else if (actualType !== entry.type) {
      diagnostics.push({
        severity: 'error',
        code: 'YM602',
        message: `Native subject "${entry.native}" is a ${actualType}, not a ${entry.type}`,
        path: typeLocation.path,
        pointer: typeLocation.pointer,
        line: typeLocation.line,
        column: typeLocation.column,
      })
    }
    if (seenNativeSubjects.has(entry.native)) {
      diagnostics.push({
        severity: 'error',
        code: 'YM603',
        message: `Native subject "${entry.native}" is mapped more than once`,
        path: nativeLocation.path,
        pointer: nativeLocation.pointer,
        line: nativeLocation.line,
        column: nativeLocation.column,
      })
    }
    seenNativeSubjects.add(entry.native)
    if (seenExternalIdentities.has(entry.external)) {
      diagnostics.push({
        severity: 'error',
        code: 'YM604',
        message: `External identity "${entry.external}" is mapped more than once`,
        path: externalLocation.path,
        pointer: externalLocation.pointer,
        line: externalLocation.line,
        column: externalLocation.column,
      })
    }
    seenExternalIdentities.add(entry.external)
  }

  return diagnostics.length === 0
    ? { ok: true, mapping }
    : { ok: false, diagnostics: diagnostics.sort(diagnosticOrder) }
}

export function validateAdapterMappings(
  graph: SemanticGraph,
  mappings: readonly AdapterMapping[],
): AdapterMappingsValidationResult {
  const ordered = [...mappings].sort((left, right) => {
    const identityOrder = `${left.id}@${left.version}`.localeCompare(
      `${right.id}@${right.version}`,
    )
    if (identityOrder !== 0) return identityOrder
    const leftPath = mappingLocations.get(left)?.id.path ?? ''
    const rightPath = mappingLocations.get(right)?.id.path ?? ''
    return leftPath.localeCompare(rightPath)
  })
  const diagnostics: Diagnostic[] = []
  const seenIdentities = new Set<string>()
  const nativeOwnersByAdapter = new Map<
    string,
    Map<string, AdapterMapping>
  >()
  const externalOwnersByAdapter = new Map<
    string,
    Map<string, AdapterMapping>
  >()

  for (const mapping of ordered) {
    const identity = `${mapping.id}@${mapping.version}`
    const validation = validateAdapterMapping(graph, mapping)
    if (!validation.ok) {
      diagnostics.push(...validation.diagnostics)
    }
    if (seenIdentities.has(identity)) {
      const location = mappingLocations.get(mapping)?.id ?? {
        path: `${mapping.id}.mapping.yaml`,
        pointer: '/id',
        line: 1,
        column: 1,
      }
      diagnostics.push({
        severity: 'error',
        code: 'YM605',
        message: `Adapter mapping "${identity}" is declared more than once`,
        ...location,
      })
    }
    seenIdentities.add(identity)

    const nativeOwners =
      nativeOwnersByAdapter.get(mapping.adapter) ??
      new Map<string, AdapterMapping>()
    const externalOwners =
      externalOwnersByAdapter.get(mapping.adapter) ??
      new Map<string, AdapterMapping>()
    nativeOwnersByAdapter.set(mapping.adapter, nativeOwners)
    externalOwnersByAdapter.set(mapping.adapter, externalOwners)
    const locations = mappingLocations.get(mapping)?.mappings ?? []
    for (const [index, entry] of mapping.mappings.entries()) {
      const nativeOwner = nativeOwners.get(entry.native)
      if (nativeOwner !== undefined && nativeOwner !== mapping) {
        const location = locations[index]?.native ?? {
          path: `${mapping.id}.mapping.yaml`,
          pointer: `/mappings/${index}/native`,
          line: 1,
          column: 1,
        }
        diagnostics.push({
          severity: 'error',
          code: 'YM603',
          message: `Native subject "${entry.native}" is mapped more than once for adapter "${mapping.adapter}"`,
          ...location,
        })
      }
      nativeOwners.set(entry.native, nativeOwner ?? mapping)

      const externalOwner = externalOwners.get(entry.external)
      if (externalOwner !== undefined && externalOwner !== mapping) {
        const location = locations[index]?.external ?? {
          path: `${mapping.id}.mapping.yaml`,
          pointer: `/mappings/${index}/external`,
          line: 1,
          column: 1,
        }
        diagnostics.push({
          severity: 'error',
          code: 'YM604',
          message: `External identity "${entry.external}" is mapped more than once for adapter "${mapping.adapter}"`,
          ...location,
        })
      }
      externalOwners.set(entry.external, externalOwner ?? mapping)
    }
  }

  return diagnostics.length === 0
    ? { ok: true, mappings: ordered }
    : { ok: false, diagnostics: diagnostics.sort(diagnosticOrder) }
}

# Product journeys

YarraMate provides one repository-native architecture system for two primary
agent-assisted journeys. Native documents are canonical in both; the
difference is how an architecture proposal begins.

## Discover an existing project

An agent harness starts with implementation and repository evidence:

1. orient to the repository, its boundaries, and its existing YarraMate
   workspace, if any;
2. inspect source and provider observations without treating them as declared
   intent;
3. propose concise native concepts, relationships, states, ownership, and
   constraints;
4. run deterministic checks and correct structural failures;
5. produce focused context and visual projections;
6. reconcile proposed or existing declared claims with available evidence;
7. leave a reviewable Git change for a person to accept, revise, or reject.

The initial workflow may use agent inspection directly. Graphify can later
supply repeatable observed evidence through an optional adapter. Neither path
automatically promotes observations into canonical claims.

### Smallest useful outcome

- a valid `.yarramate/workspace.yaml`;
- one or more concise native architecture documents;
- explicit provenance in the Git change and optional evidence overlays;
- at least one useful projection;
- when visual output is selected, the intended views rendered - natively in a
  visual conversation, or as a current generated LikeC4 project, or both;
- explicit reporting of modelled subjects or flows that the views omit;
- deterministic `check` and context output;
- a deterministic reconciliation report when evidence overlays exist;
- no unreviewed mutation of architectural intent.

## Design a new solution

An agent harness starts with intent rather than implementation:

1. capture drivers, stakeholders, goals, constraints, and required outcomes;
2. identify solution boundaries, capabilities, information, responsibilities,
   and dependencies;
3. explore materially different alternatives without prematurely modelling
   every detail;
4. declare the selected current or target architecture in native documents;
5. check deterministic correctness and render stakeholder-focused views;
6. provide bounded semantic context to implementation agents;
7. reconcile the declared architecture with evidence as the project is built.

The guided methodology should make routine authoring concise and tolerate
partial models. Core validation does not convert missing detail or an
unfashionable design into an error.

### Smallest useful outcome

- agreed drivers and constraints represented as architectural concepts;
- a coherent target solution boundary and its principal relationships;
- alternatives or state transitions recorded only where they aid a decision;
- focused projections suitable for review and agent context;
- when visual output is selected, the intended views rendered by either
  visualization adapter and an explicit rendering-coverage statement;
- valid native documents ready to evolve alongside implementation.

## Maintain an existing model

An agent harness starts from a model that already validates:

1. discover the repository's authored workspace, evidence, projection, and
   adapter paths;
2. establish a passing read-only baseline;
3. find every reference to the subjects or claims being changed;
4. update the smallest coherent set of canonical inputs;
5. verify Core and optional adapters before applying any repair command;
6. review mapping repairs as ordinary tracked authoring changes;
7. require the maintained model and configured adapters to pass before
   handoff.

This journey covers normal evolution such as renames, retired concepts,
changed relationships, and gaps resolved into decisions. It does not introduce
an approval workflow. A mutating synchronization command cannot serve as a CI
verification gate.

## Shared lifecycle

```text
repository evidence ─┐
                     ├─> architecture proposal ─> Git review ─> declared intent
design conversation ─┘                                      │
                                                            v
                                              bounded implementation context
                                                            │
                                                            v
                                               evidence and reconciliation
```

An architecture proposal is a candidate native-document change, not a new
claim origin and not an approval state. Once accepted in Git, its content is
declared architecture. Observations remain evidence; generated diagrams remain
projections.

## Harness boundary

Codex, Claude Code, and other agent harnesses may inspect repositories, invoke
the CLI, edit native documents, and present changes under their existing
permissions. YarraMate supplies deterministic operations and guided
methodology, not an autonomous governance actor.

The portable integration surface is:

- the stable CLI;
- versioned native and workspace schemas;
- machine-readable diagnostics, graph, projection, comparison, and evidence
  results;
- repository-local profiles and projections.

Skills compose these surfaces rather than depending on an undocumented
library helper or a harness-specific architecture format.

The first portable workflow is implemented in
`skills/yarramate-architecture/`. Executable discovery and design examples
live under `test/fixtures/journeys/` and are verified through the stable CLI in
`test/journeys.test.ts`.

