      string,
      | { readonly ok: false }
      | {
          readonly ok: true
          readonly format?: string
          readonly validSchema?: boolean
        }
    >
  >
}

export function loadCoreContract(
  source: WorkspaceSource,
): CoreContractLoadResult {
  const loaded = loadSourceDocument<CoreContract>(
    source,
    validateCoreContract,
    'Core contract',
  )
  if (!loaded.ok) return loaded
  const { value, yaml, lineCounter } = loaded.document
  const diagnostics: Diagnostic[] = []
  const formatIds = new Set<string>()
  value.formats.forEach((format, index) => {
    if (formatIds.has(format.id)) {
      diagnostics.push({
        severity: 'error',
        code: 'YMC101',
        message: `Core contract format "${format.id}" is declared more than once`,
        ...locateSourcePath(
          source.path,
          yaml,
          lineCounter,
          ['formats', index, 'id'],
          `/formats/${index}/id`,
        ),
      })
    }
    formatIds.add(format.id)
  })
  const commandNames = new Set<string>()
  value.commands.forEach((command, index) => {
    if (commandNames.has(command.name)) {
      diagnostics.push({
        severity: 'error',
        code: 'YMC102',
        message: `Core contract command "${command.name}" is declared more than once`,
        ...locateSourcePath(
          source.path,
          yaml,
          lineCounter,
          ['commands', index, 'name'],
          `/commands/${index}/name`,
        ),
      })
    }
    commandNames.add(command.name)
    if (
      command.machineFormat !== undefined &&
      !formatIds.has(command.machineFormat)
    ) {
      diagnostics.push({
        severity: 'error',
        code: 'YMC103',
        message: `Command "${command.name}" references undeclared machine format "${command.machineFormat}"`,
        ...locateSourcePath(
          source.path,
          yaml,
          lineCounter,
          ['commands', index, 'machineFormat'],
          `/commands/${index}/machineFormat`,
        ),
      })
    }
  })
  return diagnostics.length === 0
    ? { ok: true, contract: value }
    : { ok: false, diagnostics: diagnostics.sort(diagnosticOrder) }
}

export function checkCoreContract(
  source: WorkspaceSource,
  surface: CoreContractSurface,
): CoreContractLoadResult {
  const loaded = loadCoreContract(source)
  if (!loaded.ok) return loaded
  const lineCounter = new LineCounter()
  const yaml = parseDocument(source.source, { lineCounter })
  const files = new Set(surface.files)
  const binaries = new Set(surface.packageBinaries)
  const diagnostics: Diagnostic[] = []
  if (!files.has(loaded.contract.packageManifest)) {
    diagnostics.push({
      severity: 'error',
      code: 'YMC204',
      message: `Package manifest "${loaded.contract.packageManifest}" does not exist`,
      ...locateSourcePath(
        source.path,
        yaml,
        lineCounter,
        ['packageManifest'],
        '/packageManifest',
      ),
    })
  } else if (!surface.packageManifestValid) {
    diagnostics.push({
      severity: 'error',
      code: 'YMC205',
      message: `Package manifest "${loaded.contract.packageManifest}" is not a valid JSON object`,
      ...locateSourcePath(
        source.path,
        yaml,
        lineCounter,
        ['packageManifest'],
        '/packageManifest',
      ),
    })
  }
  diagnostics.push(
    ...loaded.contract.formats.flatMap(
    (format, index): Diagnostic[] => {
      const missingSchema: Diagnostic[] = files.has(format.schema)
        ? []
        : [
            {
              severity: 'error',
              code: 'YMC201',
              message: `Schema file "${format.schema}" does not exist`,
              ...locateSourcePath(
                source.path,
                yaml,
                lineCounter,
                ['formats', index, 'schema'],
                `/formats/${index}/schema`,
              ),
            },
          ]
      const schemaSurface = surface.schemas?.[format.schema]
      const invalidSchema: Diagnostic[] =
        files.has(format.schema) &&
        schemaSurface !== undefined &&
        !schemaSurface.ok
          ? [
              {
                severity: 'error',
                code: 'YMC206',
                message: `Schema file "${format.schema}" is not valid JSON`,
                ...locateSourcePath(
                  source.path,
                  yaml,
                  lineCounter,
                  ['formats', index, 'schema'],
                  `/formats/${index}/schema`,
                ),
              },
            ]
          : []
      const mismatchedFormat: Diagnostic[] =
        files.has(format.schema) &&
        schemaSurface?.ok === true &&
        schemaSurface.format !== format.id
          ? [
              {
                severity: 'error',
                code: 'YMC207',
                message:
                  schemaSurface.format === undefined
                    ? `Schema file "${format.schema}" does not declare contracted format "${format.id}"`
                    : `Schema file "${format.schema}" declares format "${schemaSurface.format}" instead of "${format.id}"`,
                ...locateSourcePath(
                  source.path,
                  yaml,
                  lineCounter,
                  ['formats', index, 'id'],
                  `/formats/${index}/id`,
                ),
              },
            ]
          : []
      const invalidJsonSchema: Diagnostic[] =
        files.has(format.schema) &&
        schemaSurface?.ok === true &&
        schemaSurface.validSchema === false
          ? [
              {
                severity: 'error',
                code: 'YMC208',
                message: `Schema file "${format.schema}" is not valid JSON Schema 2020-12`,
                ...locateSourcePath(
                  source.path,
                  yaml,
                  lineCounter,
                  ['formats', index, 'schema'],
                  `/formats/${index}/schema`,
                ),
              },
            ]
          : []
      const expected = `./${format.schema}`
      const invalidExport: Diagnostic[] =
        !surface.packageManifestValid
          ? []
          : surface.packageExports[format.packageExport] === expected
            ? []
            : [
                {
                  severity: 'error',
                  code: 'YMC202',
                  message: `Package export "${format.packageExport}" does not resolve to "${format.schema}"`,
                  ...locateSourcePath(
                    source.path,
                    yaml,
                    lineCounter,
                    ['formats', index, 'packageExport'],
                    `/formats/${index}/packageExport`,
                  ),
                },
              ]
      return [
        ...missingSchema,
        ...invalidSchema,
        ...mismatchedFormat,
        ...invalidJsonSchema,
        ...invalidExport,
      ]
    },
    ),
  )
  loaded.contract.commands.forEach((command, index) => {
    if (
      surface.packageManifestValid &&
      !binaries.has(command.binary)
    ) {
      diagnostics.push({
        severity: 'error',
        code: 'YMC203',
        message: `Package binary "${command.binary}" is not declared`,
        ...locateSourcePath(
          source.path,
          yaml,
          lineCounter,
          ['commands', index, 'binary'],
          `/commands/${index}/binary`,
        ),
      })
    }
  })
  return diagnostics.length === 0
    ? loaded
    : { ok: false, diagnostics: diagnostics.sort(diagnosticOrder) }
}

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { parseDocument } from 'yaml'
import {
  diagnosticJson,
  humanDiagnostics,
  usage,
  type CliResult,
} from './cli-support.js'
import { createFileSystemStore } from './source-store.js'
import { posixDirectoryOf } from './apply-command.js'
import { loadWorkspaceManifest } from './workspace.js'
import { designStepDetailed, type DesignStep } from './tools/design.js'
import type { ToolWorkspace } from './tools/workspace.js'

// The interview itself lives in `tools/design.ts` (ADR 0156): this command
// parses arguments, resolves the manifest against the filesystem, hands the
// same store-backed core the hosted server calls, and renders the human
// form. The JSON form is the core's result, printed.

const localKind = (qualified: string): string => {
  const hash = qualified.lastIndexOf('#')
  return hash === -1 ? qualified : qualified.slice(hash + 1)
}

/**
 * The `missing-claim` predicates that name a CONCEPT FIELD, and the field
 * each one is written through (#430).
 *
 * `missing-claim` matches a raw predicate, and a predicate is not an
 * authoring gesture: `yarramate/attestation/adequacy` is written by adding an
 * attestation, `yarramate/reference/refers-to` by adding a reference, and a
 * profile may mint predicates this engine has never heard of. So the
 * condition cannot map to one operation in general, which is why an adopter
 * wiring it up got a card with no affordance and filed #430.
 *
 * It maps for these three, and only these three, because each is a named
 * field on a concept that `update-concept` writes directly. They are Core's
 * own, closed, and they are every `missing-claim` the shipped catalogue uses
 * — `owner-missing`, `information-unowned`, `concept-undescribed` and
 * `status-missing`. Anything else returns no skeleton, which is ADR 0110's
 * rule holding: a wrong skeleton is never offered.
 *
 * This is the "one new mapping case" ADR 0110 anticipated, not a remedy DSL.
 * The engine still takes no position on which predicates a HOST should render
 * as editable; the trigger carries the predicate and the host decides. This
 * is the CLI rendering its own affordance, the same as the other two cases.
 */
const CONCEPT_FIELD_PREDICATES: Record<
  string,
  { readonly name: string; readonly placeholder: string }
> = {
  'yarramate/ownership/owner': {
    name: 'owner',
    placeholder: '<owning-subject-id>',
  },
  'yarramate/concept/description': {
    name: 'description',
    placeholder: '<one line>',
  },
  'yarramate/lifecycle/status': {
    name: 'status',
    placeholder: '<planned|current|retired>',
  },
}

const skeletonHeader = (
  documentAddress: string,
  op: string,
): readonly string[] => [
  '',
  'Prefilled skeleton (edit the <placeholders>, save as operations.yaml):',
  '  format: yarramate/operations/v1',
  '  operations:',
  `    - op: ${op}`,
  `      document: ${documentAddress}`,
]

// The skeleton is a rendering of the step's trigger (#289), printed only
// when a single condition maps unambiguously onto one operation, so a
// wrong skeleton is never offered; every other trigger leaves the output
// exactly as before. Kinds print as local names: that is the form a
// native document declares.
const renderSkeleton = (
  step: DesignStep,
  documentAddress: string | undefined,
): readonly string[] => {
  if (documentAddress === undefined || step.trigger.length !== 1) return []
  const condition = step.trigger[0]!
  if (condition.condition === 'no-subject-of-kind') {
    const kinds = condition.kinds.map(localKind)
    const alternatives =
      kinds.length > 1 ? `  # or: ${kinds.slice(1).join(', ')}` : ''
    return [
      ...skeletonHeader(documentAddress, 'add-concept'),
      '      concept:',
      '        id: <kebab-case-id>',
      `        kind: ${kinds[0]}${alternatives}`,
      '        name: <one line>',
    ]
  }
  if (
    condition.condition === 'missing-relationship' &&
    step.subject !== undefined
  ) {
    const kinds = condition.kinds.map(localKind)
    const alternatives =
      kinds.length > 1 ? `  # or: ${kinds.slice(1).join(', ')}` : ''
    const swap =
      condition.direction === 'any' ? '  # or swap the endpoints' : ''
    const from =
      condition.direction === 'incoming' ? '<counterpart-id>' : step.subject.id
    const to =
      condition.direction === 'incoming' ? step.subject.id : '<counterpart-id>'
    return [
      ...skeletonHeader(documentAddress, 'add-relationship'),
      '      relationship:',
      '        id: <kebab-case-id>',
      `        kind: ${kinds[0]}${alternatives}`,
      `        from: ${from}${swap}`,
      `        to: ${to}`,
    ]
  }
  if (condition.condition === 'missing-claim' && step.subject !== undefined) {
    const field = CONCEPT_FIELD_PREDICATES[condition.predicate]
    if (field === undefined) return []
    return [
      ...skeletonHeader(documentAddress, 'update-concept'),
      '      concept:',
      `        id: ${step.subject.id.split('#').pop()}`,
      `        ${field.name}: ${field.placeholder}`,
    ]
  }
  return []
}

export function runDesignCommand(
  options: readonly string[],
  cwd: string,
): CliResult {
  const json = options.includes('--json')
  // Facilitation is a rendering preference, not an interview mode: the
  // same step, slice, and envelope, with the plain phrasing preferred in
  // the human question line when the catalogue provides one.
  const facilitate = options.includes('--facilitate')
  let subjectFilter: string | undefined
  let cataloguePath: string | undefined
  const rest: string[] = []
  const withoutJson = options.filter(
    (option) => option !== '--json' && option !== '--facilitate',
  )
  for (let index = 0; index < withoutJson.length; index += 1) {
    const option = withoutJson[index]
    if (option === '--subject' || option === '--catalogue') {
      const value = withoutJson[index + 1]
      if (value === undefined || value.startsWith('-')) {
        return { exitCode: 2, stdout: '', stderr: usage }
      }
      if (option === '--subject') {
        if (subjectFilter !== undefined) {
          return { exitCode: 2, stdout: '', stderr: usage }
        }
        subjectFilter = value
      } else {
        if (cataloguePath !== undefined) {
          return { exitCode: 2, stdout: '', stderr: usage }
        }
        cataloguePath = value
      }
      index += 1
      continue
    }
    if (option === undefined || option.startsWith('-')) {
      return { exitCode: 2, stdout: '', stderr: usage }
    }
    rest.push(option)
  }
  const [workspacePath] = rest
  if (rest.length !== 1 || workspacePath === undefined) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  try {
    const manifestSource = readFileSync(resolve(cwd, workspacePath), 'utf8')
    if (
      parseDocument(manifestSource).get('format') !== 'yarramate/workspace/v1'
    ) {
      return {
        exitCode: 2,
        stdout: '',
        stderr:
          'design requires an explicit workspace manifest (yarramate/workspace/v1)\n',
      }
    }
    const loadedWorkspace = loadWorkspaceManifest(
      { path: workspacePath, source: manifestSource },
      cwd,
    )
    if (!loadedWorkspace.ok) {
      return {
        exitCode: 1,
        stdout: json
          ? diagnosticJson(loadedWorkspace.diagnostics)
          : humanDiagnostics(loadedWorkspace.diagnostics),
        stderr: '',
      }
    }
    const workspace = loadedWorkspace.workspace

    // The base is REPLACED by `--catalogue` and ADDED TO by `questions:`
    // (#345, ADR 0129); the core composes the two.
    const tool: ToolWorkspace = {
      store: createFileSystemStore(cwd),
      workspace,
      manifestDirectory: posixDirectoryOf(workspacePath),
      ...(cataloguePath === undefined
        ? {}
        : {
            catalogue: {
              path: cataloguePath,
              source: readFileSync(resolve(cwd, cataloguePath), 'utf8'),
            },
          }),
    }
    const stepped = designStepDetailed(
      tool,
      subjectFilter === undefined ? {} : { subject: subjectFilter },
    )
    if (!stepped.ok) {
      if (stepped.reason === 'refused') {
        return { exitCode: 1, stdout: '', stderr: `${stepped.message}\n` }
      }
      return {
        exitCode: 1,
        stdout: json
          ? diagnosticJson(stepped.diagnostics)
          : humanDiagnostics(stepped.diagnostics),
        stderr: '',
      }
    }
    const { result, report } = stepped.result
    const { step, slice } = result

    if (json) {
      return {
        exitCode: 0,
        stdout: `${JSON.stringify(result, null, 2)}\n`,
        stderr: '',
      }
    }

    // Read from the REPORT rather than from `progress`, because a wave that
    // has not opened and one with nothing outstanding both count zero (#334).
    // "implementation 0 open" about a gated wave is the same empty-set
    // flattery as the completion sentence below it - which was fixed while
    // this line, directly above it, was not. `progress` keeps its shape: a
    // consumer wanting wave state reads an interrogation report, and a third
    // required field on a published format for a convenience summary is not
    // worth the constructor break.
    const waveSummary = report.waves
      .map((wave) => {
        const open =
          result.progress.waves.find(({ id }) => id === wave.id)?.open ?? 0
        return wave.opened ? `${wave.id} ${open} open` : `${wave.id} not yet`
      })
      .join(' · ')
    const lines: string[] = [
      `Design interview — workspace ${workspace.id} · catalogue ${report.catalogue}`,
      `Waves: ${waveSummary}`,
      '',
    ]
    if (step === null) {
      // "No open questions" has two causes and only one of them is complete
      // (#334). Every wave gated shut asks NOTHING, so a blank model reaches
      // zero without a single question having been put - and claiming the
      // model answers everything the catalogue asks is then flatly false
      // about a catalogue that asked nothing. Completion inferred from an
      // empty set is the same fault the wave rail and the report renderer
      // each carried; this is the sentence an agent reads to decide it is
      // done, so it is the worst place for it.
      const asked = report.waves.some((wave) => wave.questions.length > 0)
      lines.push(
        !asked
          ? 'No wave has opened yet: this catalogue asks nothing until the model has substance. Declare a subject and run this again.'
          : subjectFilter === undefined
            ? 'Interview complete: no open questions. The model answers everything the catalogue asks.'
            : `Interview complete for ${subjectFilter}: no open questions touch it.`,
      )
    } else {
      // --facilitate prefers the workshop phrasing and falls back to the
      // standard one when a question has none; it never blocks.
      const asked =
        facilitate && step.askPlain !== undefined
          ? step.askPlain
          : step.question
      lines.push(
        `Q [${step.wave} · ${step.questionId}] (authority: ${step.authority})`,
        `  ${asked}`,
        `  Why it matters: ${step.materiality}`,
        `  How to answer: ${step.resolution}`,
      )
      if (step.remainingSubjects !== undefined) {
        lines.push(
          `  (${step.remainingSubjects} more subject${step.remainingSubjects === 1 ? '' : 's'} share${step.remainingSubjects === 1 ? 's' : ''} this question)`,
        )
      }
      if (slice !== undefined) {
        lines.push('', 'Subject slice:', '', slice.trimEnd())
      }
      // The skeleton's document address is the manifest-relative form
      // when the first document sits under the manifest directory - the
      // address an author naturally writes and apply accepts (#216) -
      // falling back to the workspace path, which apply also accepts.
      const manifestDirectory = workspacePath.includes('/')
        ? workspacePath.slice(0, workspacePath.lastIndexOf('/'))
        : ''
      const firstDocument = workspace.documents[0]
      const documentAddress =
        firstDocument === undefined
          ? undefined
          : manifestDirectory !== '' &&
              firstDocument.startsWith(`${manifestDirectory}/`)
            ? firstDocument.slice(manifestDirectory.length + 1)
            : firstDocument
      lines.push(
        '',
        'Answer by updating the model (one atomic batch):',
        `  yarramate apply <operations.yaml> ${workspacePath}`,
        ...renderSkeleton(step, documentAddress),
        `Then re-run: yarramate design ${workspacePath}`,
      )
    }
    return { exitCode: 0, stdout: `${lines.join('\n')}\n`, stderr: '' }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import Ajv2020Module from 'ajv/dist/2020.js'
import { shippedCatalogueSource } from './catalogue-sources.js'
import {
  humanDiagnostics,
  resolveCliWorkspaceSources,
  usage,
  type CliResult,
} from './cli-support.js'
import { checkSources } from './tools/check.js'

// The check itself is `checkSources` in `tools/check.ts` (ADR 0156): this
// command resolves the sources against the filesystem, lends the core Ajv
// for the schemas a Core contract names, and renders the two outputs.

// `.default ?? module`, not a bare `.default`: NodeNext sees the raw CJS
// `module.exports` and a bundler the unwrapped class. One shape for all of
// them, so which modules a browser happens to reach is not a thing anyone has
// to keep track of (#252).
const ajv2020Module = Ajv2020Module as unknown as {
  default?: typeof Ajv2020Module
} & typeof Ajv2020Module
const Ajv2020 = ajv2020Module.default ?? ajv2020Module

const schemaCompiles = (schema: object): boolean => {
  try {
    new Ajv2020({ strict: false }).compile(schema)
    return true
  } catch {
    return false
  }
}

export function runCheckCommand(
  options: readonly string[],
  cwd: string,
): CliResult {
  const json = options.includes('--json')
  const strict = options.includes('--strict')
  const paths = options.filter(
    (option) => option !== '--json' && option !== '--strict',
  )
  const unknownOption = paths.find((path) => path.startsWith('-'))
  if (unknownOption !== undefined || paths.length === 0) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  try {
    const resolved = resolveCliWorkspaceSources(paths, cwd, {
      includeAdapterMappings: true,
    })
    if (!resolved.ok) {
      const output = json
        ? `${JSON.stringify(
            {
              format: 'yarramate/check-result/v1',
              ok: false,
              diagnostics: resolved.diagnostics,
            },
            null,
            2,
          )}\n`
        : humanDiagnostics(resolved.diagnostics)
      return { exitCode: 1, stdout: output, stderr: '' }
    }
    const evaluation = checkSources({
      read: (path) => readFileSync(resolve(cwd, path), 'utf8'),
      exists: (path) => existsSync(resolve(cwd, path)),
      paths: resolved.paths,
      projections: resolved.projections,
      evidence: resolved.evidence,
      contracts: resolved.contracts,
      patterns: resolved.patterns,
      questions: resolved.questions,
      catalogueBase: shippedCatalogueSource(),
      strict,
      schemaCompiles,
    })
    const { result } = evaluation

    if (json) {
      return {
        exitCode: result.ok ? 0 : 1,
        stdout: `${JSON.stringify(result, null, 2)}\n`,
        stderr: '',
      }
    }

    if (!result.ok || evaluation.checked === undefined) {
      return {
        exitCode: 1,
        stdout: humanDiagnostics(evaluation.shown),
        stderr: '',
      }
    }

    const counts = result.counted!
    const {
      documents: documentCount,
      profiles: profileCount,
      patterns: patternCount,
      mappings: mappingCount,
      projections: projectionCount,
      evidence: evidenceCount,
      contracts: contractCount,
    } = evaluation.checked
    const checked = [
      `${documentCount} ${documentCount === 1 ? 'document' : 'documents'}`,
      ...(profileCount > 0
        ? [`${profileCount} ${profileCount === 1 ? 'profile' : 'profiles'}`]
        : []),
      ...(patternCount > 0
        ? [`${patternCount} ${patternCount === 1 ? 'pattern' : 'patterns'}`]
        : []),
      ...(mappingCount > 0
        ? [
            `${mappingCount} ${mappingCount === 1 ? 'adapter mapping' : 'adapter mappings'}`,
          ]
        : []),
      ...(projectionCount > 0
        ? [
            `${projectionCount} ${projectionCount === 1 ? 'projection' : 'projections'}`,
          ]
        : []),
      ...(evidenceCount > 0
        ? [
            `${evidenceCount} ${evidenceCount === 1 ? 'evidence document' : 'evidence documents'}`,
          ]
        : []),
      ...(contractCount > 0
        ? [
            `${contractCount} ${contractCount === 1 ? 'Core contract' : 'Core contracts'}`,
          ]
        : []),
    ].join(' and ')
    const strictLine =
      result.strict === undefined
        ? ''
        : result.strict.observations === 0
          ? 'Strict: no evidence observations to evaluate\n'
          : `Strict: ${result.strict.observations} ${result.strict.observations === 1 ? 'observation' : 'observations'}, 0 contradicted\n`
    return {
      exitCode: 0,
      stdout:
        `Checked ${checked} (` +
        `${counts.concepts} ${counts.concepts === 1 ? 'concept' : 'concepts'}, ` +
        `${counts.relationships} ${counts.relationships === 1 ? 'relationship' : 'relationships'}, ` +
        `${counts.states} ${counts.states === 1 ? 'state' : 'states'}` +
        '): no errors\n' +
        strictLine,
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

/**
 * White-labelling (#546, ADR 0158): one value, set once by a host, that
 * names the product on every surface a consumer's users see - the editor
 * shell, the tool list an agent reads, the workbook's cover sheet and the
 * LikeC4 banner. Nothing else changes: record formats, diagnostic codes and
 * the wire protocol are contracts, not branding, and stay `yarramate/...`
 * and `YM...`. Absent, every surface reads exactly as it always has.
 *
 * Pure: no imports, so it sits under every entry (`yarramate/tools`,
 * `yarramate/workbook`, `yarramate/visual-app`) without weight.
 */

export type BrandingLogo =
  /** Inline markup the host wrote; rendered as the host's own SVG. */
  | { readonly svg: string }
  /** An address the page fetches; rendered as an image. */
  | { readonly url: string }

export interface Branding {
  /** "ApertureX", "Halcyon Architecture". Required: a brand without a name is not one. */
  readonly productName: string
  /**
   * For tight chrome: beside the logo in the brand mark, and in the
   * authority line ("Checked Halcyon model"). Defaults to `productName`.
   * `null` draws the logo alone, for a wordmark that already says the name.
   */
  readonly shortName?: string | null
  /** Beside the title in the editor shell. Nothing is drawn without one. */
  readonly logo?: BrandingLogo
  /**
   * One CSS colour for the chrome - the authority mark, the notices, the
   * changeset controls - never the notation: what a node or an edge looks
   * like is the style preset's, and a comparison's added/removed marks keep
   * their own tokens.
   */
  readonly accent?: string
  /** Where the brand mark links. Without it the mark is text, not a link. */
  readonly docsUrl?: string
  /**
   * The line under the product name, on the editor strip, the workbook's
   * cover sheet and the LikeC4 banner. Unset: "Powered by yarramate". A
   * string replaces it; `null` removes it, and with it every other mention
   * of the engine those surfaces make.
   */
  readonly vendorLine?: string | null
  /**
   * The prefix of the tool names an agent reads: `acme` publishes
   * `acme_design`, `acme_apply`, ... Default `yarramate`. An instruction
   * written for `yarramate_design` will not find `acme_design`, so a host
   * that re-prefixes owns its own agent instructions.
   */
  readonly toolPrefix?: string
}

/** `Branding` with every default applied, which is what the surfaces read. */
export interface ResolvedBranding {
  readonly productName: string
  /** `null` when the mark is the logo alone; the authority line then says `productName`. */
  readonly shortName: string | null
  readonly logo?: BrandingLogo
  readonly accent?: string
  readonly docsUrl?: string
  /** `null` when there is none to show. */
  readonly vendorLine: string | null
  readonly toolPrefix: string
  /** False is the unbranded product: every surface as it was before #546. */
  readonly branded: boolean
}

export const YARRAMATE_PRODUCT_NAME = 'YarraMate'
export const YARRAMATE_TOOL_PREFIX = 'yarramate'
export const DEFAULT_VENDOR_LINE = 'Powered by yarramate'

/** What an MCP client accepts in a tool name, applied to the prefix alone. */
const TOOL_PREFIX = /^[A-Za-z0-9][A-Za-z0-9-]*$/

const UNBRANDED: ResolvedBranding = {
  productName: YARRAMATE_PRODUCT_NAME,
  shortName: YARRAMATE_PRODUCT_NAME,
  vendorLine: null,
  toolPrefix: YARRAMATE_TOOL_PREFIX,
  branded: false,
}

/**
 * Applies the defaults. `undefined` is the unbranded product. A value with
 * a blank `productName` or a `toolPrefix` no MCP client could publish is a
 * host's configuration error and throws, at mount or serve time, rather
 * than reaching a person as a blank name or an agent as a broken tool list.
 */
export const resolveBranding = (branding?: Branding): ResolvedBranding => {
  if (branding === undefined) return UNBRANDED
  const productName = branding.productName.trim()
  if (productName === '') {
    throw new TypeError('branding.productName must not be blank')
  }
  const toolPrefix = branding.toolPrefix ?? YARRAMATE_TOOL_PREFIX
  if (!TOOL_PREFIX.test(toolPrefix)) {
    throw new TypeError(
      `branding.toolPrefix "${toolPrefix}" must be letters, digits and hyphens, starting with a letter or digit`,
    )
  }
  const shortName =
    branding.shortName === null ? null : branding.shortName?.trim()
  const vendorLine =
    branding.vendorLine === undefined
      ? DEFAULT_VENDOR_LINE
      : branding.vendorLine === null || branding.vendorLine.trim() === ''
        ? null
        : branding.vendorLine.trim()
  return {
    productName,
    shortName:
      shortName === null
        ? null
        : shortName === undefined || shortName === ''
          ? productName
          : shortName,
    ...(branding.logo === undefined ? {} : { logo: branding.logo }),
    ...(branding.accent === undefined ? {} : { accent: branding.accent }),
    ...(branding.docsUrl === undefined ? {} : { docsUrl: branding.docsUrl }),
    vendorLine,
    toolPrefix,
    branded: true,
  }
}

/**
 * The product name as an identifier segment: the LikeC4 project name is
 * `<slug>-<project id>`, `yarramate-…` unbranded. Lower-case letters,
 * digits and single hyphens; a name with nothing usable in it falls back
 * to the engine's own slug rather than producing an empty segment.
 */
export const brandSlug = (branding: ResolvedBranding): string => {
  if (!branding.branded) return YARRAMATE_TOOL_PREFIX
  // Split on the runs and join what is left: linear, where a trim by
  // `^-+|-+$` is polynomial on a name that is mostly hyphens (CodeQL
  // js/polynomial-redos, the rule that bit #547's walker too).
  const slug = (branding.shortName ?? branding.productName)
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((part) => part !== '')
    .join('-')
  return slug === '' ? YARRAMATE_TOOL_PREFIX : slug
}

