// The interview itself lives in `tools/design.ts` (ADR 0156): this command
// parses arguments, resolves the manifest against the filesystem, hands the
// same store-backed core the hosted server calls, and renders the human
// form. The JSON form is the core's result, printed.

const localKind = (qualified: string): string => {
  const hash = qualified.lastIndexOf('#')
  return hash === -1 ? qualified : qualified.slice(hash + 1)
}

/**
 * The `missing-claim` predicates that name a CONCEPT FIELD, and the field
 * each one is written through (#430).
 *
 * `missing-claim` matches a raw predicate, and a predicate is not an
 * authoring gesture: `yarramate/attestation/adequacy` is written by adding an
 * attestation, `yarramate/reference/refers-to` by adding a reference, and a
 * profile may mint predicates this engine has never heard of. So the
 * condition cannot map to one operation in general, which is why an adopter
 * wiring it up got a card with no affordance and filed #430.
 *
 * It maps for these three, and only these three, because each is a named
 * field on a concept that `update-concept` writes directly. They are Core's
 * own, closed, and they are every `missing-claim` the shipped catalogue uses
 * — `owner-missing`, `information-unowned`, `concept-undescribed` and
 * `status-missing`. Anything else returns no skeleton, which is ADR 0110's
 * rule holding: a wrong skeleton is never offered.
 *
 * This is the "one new mapping case" ADR 0110 anticipated, not a remedy DSL.
 * The engine still takes no position on which predicates a HOST should render
 * as editable; the trigger carries the predicate and the host decides. This
 * is the CLI rendering its own affordance, the same as the other two cases.
 */
const CONCEPT_FIELD_PREDICATES: Record<
  string,
  { readonly name: string; readonly placeholder: string }
> = {
  'yarramate/ownership/owner': {
    name: 'owner',
    placeholder: '<owning-subject-id>',
  },
  'yarramate/concept/description': {
    name: 'description',
    placeholder: '<one line>',
  },
  'yarramate/lifecycle/status': {
    name: 'status',
    placeholder: '<planned|current|retired>',
  },
}

const skeletonHeader = (
  documentAddress: string,
  op: string,
): readonly string[] => [
  '',
  'Prefilled skeleton (edit the <placeholders>, save as operations.yaml):',
  '  format: yarramate/operations/v1',
  '  operations:',
  `    - op: ${op}`,
  `      document: ${documentAddress}`,
]

// The skeleton is a rendering of the step's trigger (#289), printed only
// when a single condition maps unambiguously onto one operation, so a
// wrong skeleton is never offered; every other trigger leaves the output
// exactly as before. Kinds print as local names: that is the form a
// native document declares.
const renderSkeleton = (
  step: DesignStep,
  documentAddress: string | undefined,
): readonly string[] => {
  if (documentAddress === undefined || step.trigger.length !== 1) return []
  const condition = step.trigger[0]!
  if (condition.condition === 'no-subject-of-kind') {
    const kinds = condition.kinds.map(localKind)
    const alternatives =
      kinds.length > 1 ? `  # or: ${kinds.slice(1).join(', ')}` : ''
    return [
      ...skeletonHeader(documentAddress, 'add-concept'),
      '      concept:',
      '        id: <kebab-case-id>',
      `        kind: ${kinds[0]}${alternatives}`,
      '        name: <one line>',
    ]
  }
  if (
    condition.condition === 'missing-relationship' &&
    step.subject !== undefined
  ) {
    const kinds = condition.kinds.map(localKind)
    const alternatives =
      kinds.length > 1 ? `  # or: ${kinds.slice(1).join(', ')}` : ''
    const swap =
      condition.direction === 'any' ? '  # or swap the endpoints' : ''
    const from =
      condition.direction === 'incoming' ? '<counterpart-id>' : step.subject.id
    const to =
      condition.direction === 'incoming' ? step.subject.id : '<counterpart-id>'
    return [
      ...skeletonHeader(documentAddress, 'add-relationship'),
      '      relationship:',
      '        id: <kebab-case-id>',
      `        kind: ${kinds[0]}${alternatives}`,
      `        from: ${from}${swap}`,
      `        to: ${to}`,
    ]
  }
  if (condition.condition === 'missing-claim' && step.subject !== undefined) {
    const field = CONCEPT_FIELD_PREDICATES[condition.predicate]
    if (field === undefined) return []
    return [
      ...skeletonHeader(documentAddress, 'update-concept'),
      '      concept:',
      `        id: ${step.subject.id.split('#').pop()}`,
      `        ${field.name}: ${field.placeholder}`,
    ]
  }
  return []
}

export function runDesignCommand(
  options: readonly string[],
  cwd: string,
): CliResult {
  const json = options.includes('--json')
  // Facilitation is a rendering preference, not an interview mode: the
  // same step, slice, and envelope, with the plain phrasing preferred in
  // the human question line when the catalogue provides one.
  const facilitate = options.includes('--facilitate')
  let subjectFilter: string | undefined
  let cataloguePath: string | undefined
  const rest: string[] = []
  const withoutJson = options.filter(
    (option) => option !== '--json' && option !== '--facilitate',
  )
  for (let index = 0; index < withoutJson.length; index += 1) {
    const option = withoutJson[index]
    if (option === '--subject' || option === '--catalogue') {
      const value = withoutJson[index + 1]
      if (value === undefined || value.startsWith('-')) {
        return { exitCode: 2, stdout: '', stderr: usage }
      }
      if (option === '--subject') {
        if (subjectFilter !== undefined) {
          return { exitCode: 2, stdout: '', stderr: usage }
        }
        subjectFilter = value
      } else {
        if (cataloguePath !== undefined) {
          return { exitCode: 2, stdout: '', stderr: usage }
        }
        cataloguePath = value
      }
      index += 1
      continue
    }
    if (option === undefined || option.startsWith('-')) {
      return { exitCode: 2, stdout: '', stderr: usage }
    }
    rest.push(option)
  }
  const [workspacePath] = rest
  if (rest.length !== 1 || workspacePath === undefined) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  try {
    const manifestSource = readFileSync(resolve(cwd, workspacePath), 'utf8')
    if (
      parseDocument(manifestSource).get('format') !== 'yarramate/workspace/v1'
    ) {
      return {
        exitCode: 2,
        stdout: '',
        stderr:
          'design requires an explicit workspace manifest (yarramate/workspace/v1)\n',
      }
    }
    const loadedWorkspace = loadWorkspaceManifest(
      { path: workspacePath, source: manifestSource },
      cwd,
    )
    if (!loadedWorkspace.ok) {
      return {
        exitCode: 1,
        stdout: json
          ? diagnosticJson(loadedWorkspace.diagnostics)
          : humanDiagnostics(loadedWorkspace.diagnostics),
        stderr: '',
      }
    }
    const workspace = loadedWorkspace.workspace

    // The base is REPLACED by `--catalogue` and ADDED TO by `questions:`
    // (#345, ADR 0129); the core composes the two.
    const tool: ToolWorkspace = {
      store: createFileSystemStore(cwd),
      workspace,
      manifestDirectory: posixDirectoryOf(workspacePath),
      ...(cataloguePath === undefined
        ? {}
        : {
            catalogue: {
              path: cataloguePath,
              source: readFileSync(resolve(cwd, cataloguePath), 'utf8'),
            },
          }),
    }
    const stepped = designStepDetailed(
      tool,
      subjectFilter === undefined ? {} : { subject: subjectFilter },
    )
    if (!stepped.ok) {
      if (stepped.reason === 'refused') {
        return { exitCode: 1, stdout: '', stderr: `${stepped.message}\n` }
      }
      return {
        exitCode: 1,
        stdout: json
          ? diagnosticJson(stepped.diagnostics)
          : humanDiagnostics(stepped.diagnostics),
        stderr: '',
      }
    }
    const { result, report } = stepped.result
    const { step, slice } = result

    if (json) {
      return {
        exitCode: 0,
        stdout: `${JSON.stringify(result, null, 2)}\n`,
        stderr: '',
      }
    }

    // Read from the REPORT rather than from `progress`, because a wave that
    // has not opened and one with nothing outstanding both count zero (#334).
    // "implementation 0 open" about a gated wave is the same empty-set
    // flattery as the completion sentence below it - which was fixed while
    // this line, directly above it, was not. `progress` keeps its shape: a
    // consumer wanting wave state reads an interrogation report, and a third
    // required field on a published format for a convenience summary is not
    // worth the constructor break.
    const waveSummary = report.waves
      .map((wave) => {
        const open =
          result.progress.waves.find(({ id }) => id === wave.id)?.open ?? 0
        return wave.opened ? `${wave.id} ${open} open` : `${wave.id} not yet`
      })
      .join(' · ')
    const lines: string[] = [
      `Design interview — workspace ${workspace.id} · catalogue ${report.catalogue}`,
      `Waves: ${waveSummary}`,
      '',
    ]
    if (step === null) {
      // "No open questions" has two causes and only one of them is complete
      // (#334). Every wave gated shut asks NOTHING, so a blank model reaches
      // zero without a single question having been put - and claiming the
      // model answers everything the catalogue asks is then flatly false
      // about a catalogue that asked nothing. Completion inferred from an
      // empty set is the same fault the wave rail and the report renderer
      // each carried; this is the sentence an agent reads to decide it is
      // done, so it is the worst place for it.
      const asked = report.waves.some((wave) => wave.questions.length > 0)
      lines.push(
        !asked
          ? 'No wave has opened yet: this catalogue asks nothing until the model has substance. Declare a subject and run this again.'
          : subjectFilter === undefined
            ? 'Interview complete: no open questions. The model answers everything the catalogue asks.'
            : `Interview complete for ${subjectFilter}: no open questions touch it.`,
      )
    } else {
      // --facilitate prefers the workshop phrasing and falls back to the
      // standard one when a question has none; it never blocks.
      const asked =
        facilitate && step.askPlain !== undefined
          ? step.askPlain
          : step.question
      lines.push(
        `Q [${step.wave} · ${step.questionId}] (authority: ${step.authority})`,
        `  ${asked}`,
        `  Why it matters: ${step.materiality}`,
        `  How to answer: ${step.resolution}`,
      )
      if (step.remainingSubjects !== undefined) {
        lines.push(
          `  (${step.remainingSubjects} more subject${step.remainingSubjects === 1 ? '' : 's'} share${step.remainingSubjects === 1 ? 's' : ''} this question)`,
        )
      }
      if (slice !== undefined) {
        lines.push('', 'Subject slice:', '', slice.trimEnd())
      }
      // The skeleton's document address is the manifest-relative form
      // when the first document sits under the manifest directory - the
      // address an author naturally writes and apply accepts (#216) -
      // falling back to the workspace path, which apply also accepts.
      const manifestDirectory = workspacePath.includes('/')
        ? workspacePath.slice(0, workspacePath.lastIndexOf('/'))
        : ''
      const firstDocument = workspace.documents[0]
      const documentAddress =
        firstDocument === undefined
          ? undefined
          : manifestDirectory !== '' &&
              firstDocument.startsWith(`${manifestDirectory}/`)
            ? firstDocument.slice(manifestDirectory.length + 1)
            : firstDocument
      lines.push(
        '',
        'Answer by updating the model (one atomic batch):',
        `  yarramate apply <operations.yaml> ${workspacePath}`,
        ...renderSkeleton(step, documentAddress),
        `Then re-run: yarramate design ${workspacePath}`,
      )
    }
    return { exitCode: 0, stdout: `${lines.join('\n')}\n`, stderr: '' }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

// The interrogation engine as a runtime-neutral entry point.
//
// The `.` barrel reaches node:fs, node:path and node:child_process through
// workspace, source-store and attestation-staleness, so a consumer running
// inside a Worker or a Durable Object cannot take the engine from there
// without dragging Node in behind it. This subpath carries the pure engine
// alone: catalogue loading takes a WorkspaceSource, evaluation takes an
// in-memory graph, and a test pins the import graph free of Node builtins.
// The same shape the visual-graph projector uses (`./adapter/visual-graph`).
export {
  INTERROGATION_SEMANTICS_VERSION,
  composeCatalogues,
  qualifiedQuestionId,
  conditionInput,
  evaluateCatalogue,
  loadQuestionCatalogue,
  renderInterrogationReport,
  renderQuestion,
  type CatalogueCompositionResult,
  type ComposedCatalogue,
  type CatalogueCondition,
  type CatalogueEvidenceObservation,
  type CataloguePatternMembership,
  type CataloguePatternVacancy,
  type CatalogueInput,
  type CatalogueLoadResult,
  type CatalogueQuestion,
  type CatalogueSelector,
  type InterrogationReport,
  type InterrogationSummary,
  type OpenSubject,
  type QuestionCatalogue,
  type ReportQuestion,
  type ReportWave,
} from './interrogate-command.js'

import {
  ATTESTATION_PREDICATE_PREFIX,
  parseAttestationClaimValue,
  parseConstraintExpectsValue,
} from './graph-claims.js'
import type {
  GraphClaim,
  ResolvedProfileContext,
  SemanticGraph,
} from './compiler.js'
import { kindLabelOf } from './kind-label.js'
import type { Aspect, Layer } from './profile.js'
export interface CanvasNode {
  readonly id: string // qualified subject id, e.g. "yarramate-engine#compiler-module"
  readonly localId: string // authored id inside its document, e.g. "compiler-module"
  readonly document: string // manifest-relative path, from the subject's kind claim source
  readonly kind: string // resolved kind identity, e.g. "yarramate/core@0.1#applicationComponent"
  readonly kindLabel: string // local id stripped of profile prefix, e.g. "applicationComponent"
  /**
   * The core-vocabulary kind this one resolves to, from
   * `profileContext.conceptKindLineages[0]`, the way an edge already carries
   * its own. The ArchiMate relationship table is keyed on core kinds, so a
   * consumer deciding what may connect two nodes needs this rather than the
   * profile kind it was authored as.
   */
  readonly coreKindLabel: string
  /**
   * The core relationship kinds this node's PATTERN ports, or `[]` where its
   * kind has no pattern with ports (#268 phase 3, ADR 0124).
   *
   * A macro edge needs both ends to port its kind, so an editor offering a
   * palette between two instances intersects the two lists. Two raw groupings
   * permit ten of the eleven kinds, which is no guidance at all; this is what
   * restores the narrowing the relationship table gives everywhere else.
   */
  readonly portKinds: readonly string[]
  readonly layer: Layer | null // from profileContext.conceptKindLayers, null if unresolved
  readonly aspect: Aspect | null // from profileContext.conceptKindAspects, null if unresolved
  readonly name: string
  readonly description: string | null
  readonly aka: readonly string[]
  readonly status: string | null
  readonly owner: string | null // ref
  /**
   * The folder the author filed this subject under, or null. A label, never a
   * directory (ADR 0104): the rail groups by it where it is set and by the
   * subject's ArchiMate layer where it is not.
   */
  readonly folder: string | null
  readonly distinctFrom: readonly string[] // refs
  readonly supersedes: readonly string[] // refs
  readonly constraints: ReadonlyArray<{
    readonly id: string
    readonly ref: string
    readonly expects: { readonly provider: string; readonly key: string; readonly value: string } | null
  }>
  readonly references: ReadonlyArray<{
    readonly id: string
    readonly ref: string
  }>
  readonly presentIn: readonly string[] // refs
  readonly attestations: ReadonlyArray<{
    readonly topic: string
    readonly by: string
    readonly on: string
    readonly recordedBy: string | null
  }>
}

export interface CanvasEdge {
  readonly id: string
  readonly localId: string // authored id inside its document
  readonly document: string // manifest-relative path, from the relationship's kind claim source
  readonly kind: string
  readonly kindLabel: string
  readonly coreKindLabel: string // resolved core-vocabulary kind, from profileContext.relationshipKindLineages[0]
  /**
   * The kind whose reading the edge label speaks (ADR 0159): an extension
   * identity with a reading of its own, else `coreKindLabel`.
   */
  readonly readingKind?: string
  /**
   * The responsibility letter this edge carries (#557): R, C or I for the
   * shipped responsibility kinds and their subkinds, null for every other
   * kind. The canvas draws these only when the view asks (`showResponsibility`).
   */
  readonly responsibility?: ResponsibilityLetter | null
  /**
   * A reading the endpoints decide (ADR 0160): "threatens" for an
   * influence from a risk, "mitigates" for one into a risk, "bears on" for
   * an association from an assumption. Absent, the kind's own reading.
   */
  readonly reading?: string
  readonly from: string // node id
  readonly to: string // node id
  readonly name: string | null
  readonly description: string | null
  readonly mode: string | null
  readonly content: string | null
  readonly status: string | null
  readonly references: ReadonlyArray<{
    readonly id: string
    readonly ref: string
  }>
  readonly presentIn: readonly string[]
}
export interface CanvasGraph {
  readonly nodes: readonly CanvasNode[]
  readonly edges: readonly CanvasEdge[]
}

import { contextualReading, readingKindOf } from './relationship-reading.js'
import { responsibilityLetterOf, type ResponsibilityLetter } from './responsibility-kinds.js'

const CONCEPT_KIND_PREDICATE = 'yarramate/concept/kind'
const CONCEPT_NAME_PREDICATE = 'yarramate/concept/name'
const CONCEPT_DESCRIPTION_PREDICATE = 'yarramate/concept/description'
const CONCEPT_ALIAS_PREDICATE = 'yarramate/concept/alias'
const LIFECYCLE_STATUS_PREDICATE = 'yarramate/lifecycle/status'
const IDENTITY_DISTINCT_FROM_PREDICATE = 'yarramate/identity/distinct-from'
const LINEAGE_SUPERSEDES_PREDICATE = 'yarramate/lineage/supersedes'
const OWNERSHIP_OWNER_PREDICATE = 'yarramate/ownership/owner'
const ORGANISATION_FOLDER_PREDICATE = 'yarramate/organisation/folder'
const CONSTRAINT_REQUIRES_PREDICATE = 'yarramate/constraint/requires'
const REFERENCE_REFERS_TO_PREDICATE = 'yarramate/reference/refers-to'
const STATE_PRESENT_IN_PREDICATE = 'yarramate/state/present-in'

const RELATIONSHIP_NAME_PREDICATE = 'yarramate/relationship/name'
const RELATIONSHIP_DESCRIPTION_PREDICATE = 'yarramate/relationship/description'
const ACCESS_MODE_PREDICATE = 'yarramate/access/mode'
const FLOW_CONTENT_PREDICATE = 'yarramate/flow/content'

// This is compiler-internal data: every claim's object narrows deterministically
// by predicate. A mismatch means a real bug upstream in src/compiler.ts, not
// malformed input this function should tolerate — so it throws rather than
// silently coercing to an empty string.
const claimValue = (claim: GraphClaim): string => {
  if ('value' in claim.object) {
    return claim.object.value
  }
  throw new Error(
    `Expected a value-typed object for claim "${claim.id}" (subject "${claim.subject}", predicate "${claim.predicate}"), got a ref-typed object`,
  )
}

const claimRef = (claim: GraphClaim): string => {
  if ('ref' in claim.object) {
    return claim.object.ref
  }
  throw new Error(
    `Expected a ref-typed object for claim "${claim.id}" (subject "${claim.subject}", predicate "${claim.predicate}"), got a value-typed object`,
  )
}

// The compiler qualifies every subject id as `<document id>#<authored id>`
// (`qualifyReference` in src/compiler.ts), and a document's authored ids never
// contain `#`. An operation addresses a subject by the id someone wrote in the
// file, not by the qualified identity the compile derived, so the projection
// carries both rather than leaving the browser to re-derive one from the other.
const authoredIdOf = (subjectId: string): string => {
  const boundary = subjectId.indexOf('#')
  return boundary === -1 ? subjectId : subjectId.slice(boundary + 1)
}

const compareById = <T extends { readonly id: string }>(left: T, right: T) =>
  left.id.localeCompare(right.id)

const groupClaimsBySubject = (
  claims: readonly GraphClaim[],
): Map<string, GraphClaim[]> => {
  const groups = new Map<string, GraphClaim[]>()
  for (const claim of claims) {
    const group = groups.get(claim.subject)
    if (group === undefined) {
      groups.set(claim.subject, [claim])
    } else {
      group.push(claim)
    }
  }
  return groups
}

const projectConcept = (
  subjectId: string,
  claims: readonly GraphClaim[],
  profileContext: ResolvedProfileContext,
): CanvasNode => {
  const kindClaim = claims.find((claim) => claim.predicate === CONCEPT_KIND_PREDICATE)
  if (kindClaim === undefined) {
    throw new Error(
      `Concept "${subjectId}" is missing its required yarramate/concept/kind claim`,
    )
  }
  const kind = claimValue(kindClaim)

  const nameClaim = claims.find((claim) => claim.predicate === CONCEPT_NAME_PREDICATE)
  if (nameClaim === undefined) {
    throw new Error(
      `Concept "${subjectId}" is missing its required yarramate/concept/name claim`,
    )
  }

  const descriptionClaim = claims.find(
    (claim) => claim.predicate === CONCEPT_DESCRIPTION_PREDICATE,
  )
  const statusClaim = claims.find((claim) => claim.predicate === LIFECYCLE_STATUS_PREDICATE)
  const ownerClaim = claims.find((claim) => claim.predicate === OWNERSHIP_OWNER_PREDICATE)
  const folderClaim = claims.find(
    (claim) => claim.predicate === ORGANISATION_FOLDER_PREDICATE,
  )

  const constraints = claims
    .filter((claim) => claim.predicate === CONSTRAINT_REQUIRES_PREDICATE)
    .map((requiresClaim) => {
      // The constraint's local id lives between the `~constraint-` marker
      // and the end of the requires claim's own id; the paired expects
      // claim (if the constraint declared one) reuses that same local id
      // under a `~expects-` marker in the same claim group.
      const localId = requiresClaim.id.split('~constraint-')[1]
      if (localId === undefined) {
        throw new Error(
          `Constraint claim "${requiresClaim.id}" on concept "${subjectId}" does not follow the "<subject>~constraint-<id>" id convention`,
        )
      }
      const expectsClaim = claims.find(
        (claim) => claim.id === `${subjectId}~expects-${localId}`,
      )
      let expects: { readonly provider: string; readonly key: string; readonly value: string } | null
      if (expectsClaim === undefined) {
        expects = null
      } else {
        const parsed = parseConstraintExpectsValue(claimValue(expectsClaim))
        if (parsed === undefined) {
          throw new Error(
            `Constraint expects claim "${expectsClaim.id}" on concept "${subjectId}" does not follow the "provider key value" encoding`,
          )
        }
        expects = parsed
      }
      return {
        id: localId,
        ref: claimRef(requiresClaim),
        expects,
      }
    })

  const attestations = claims
    .filter((claim) => claim.predicate.startsWith(ATTESTATION_PREDICATE_PREFIX))
    .map((claim) => {
      const parsed = parseAttestationClaimValue(claimValue(claim))
      if (parsed === undefined) {
        throw new Error(
          `Attestation claim "${claim.id}" on concept "${subjectId}" does not follow the "by on [recordedBy]" encoding`,
        )
      }
      return {
        topic: claim.predicate.slice(ATTESTATION_PREDICATE_PREFIX.length),
        by: parsed.by,
        on: parsed.on,
        recordedBy: parsed.recordedBy ?? null,
      }
    })

  return {
    id: subjectId,
    localId: authoredIdOf(subjectId),
    document: kindClaim.source.path,
    kind,
    kindLabel: kindLabelOf(kind),
    coreKindLabel: kindLabelOf(
      profileContext.conceptKindLineages.get(kind)?.[0] ?? kind,
    ),
    portKinds: profileContext.patternPortKinds.get(kind) ?? [],
    layer: (profileContext.conceptKindLayers.get(kind) as Layer | undefined) ?? null,
    aspect: (profileContext.conceptKindAspects.get(kind) as Aspect | undefined) ?? null,
    name: claimValue(nameClaim),
    description: descriptionClaim === undefined ? null : claimValue(descriptionClaim),
    aka: claims
      .filter((claim) => claim.predicate === CONCEPT_ALIAS_PREDICATE)
      .map(claimValue)
      .sort(),
    status: statusClaim === undefined ? null : claimValue(statusClaim),
    owner: ownerClaim === undefined ? null : claimRef(ownerClaim),
    folder: folderClaim === undefined ? null : claimValue(folderClaim),
    distinctFrom: claims
      .filter((claim) => claim.predicate === IDENTITY_DISTINCT_FROM_PREDICATE)
      .map(claimRef)
      .sort(),
    supersedes: claims
      .filter((claim) => claim.predicate === LINEAGE_SUPERSEDES_PREDICATE)
      .map(claimRef)
      .sort(),
    constraints,
    references: claims
      .filter((claim) => claim.predicate === REFERENCE_REFERS_TO_PREDICATE)
      .map((referencesClaim) => {
        const localId = referencesClaim.id.split('~reference-')[1]
        if (localId === undefined) {
          throw new Error(
            `Reference claim "${referencesClaim.id}" on concept "${subjectId}" does not follow the "<subject>~reference-<id>" id convention`,
          )
        }
        return {
          id: localId,
          ref: claimRef(referencesClaim),
        }
      })
      .sort((left, right) => left.ref.localeCompare(right.ref)),
    presentIn: claims
      .filter((claim) => claim.predicate === STATE_PRESENT_IN_PREDICATE)
      .map(claimRef)
      .sort(),
    attestations,
  }
}

const projectRelationship = (
  relationshipId: string,
  allClaims: readonly GraphClaim[],
  ownClaims: readonly GraphClaim[],
  profileContext: ResolvedProfileContext,
  conceptKindOf: ReadonlyMap<string, string> = new Map(),
): CanvasEdge => {
  // A relationship's defining claim is asymmetric: its id is the
  // relationship's subject id, but its own `subject` field is the
  // from-concept, so it lives in the from-concept's claim group, not this
  // relationship's — it has to be found by scanning every claim.
  const definingClaim = allClaims.find((claim) => claim.id === relationshipId)
  if (definingClaim === undefined) {
    throw new Error(`Relationship "${relationshipId}" is missing its defining claim`)
  }
  const kind = definingClaim.predicate
  const lineage = profileContext.relationshipKindLineages.get(kind)
  const coreKindLabel = kindLabelOf(lineage?.[0] ?? kind)
  const endpointLineage = (subject: string): readonly string[] | undefined => {
    const conceptKind = conceptKindOf.get(subject)
    return conceptKind === undefined
      ? undefined
      : profileContext.conceptKindLineages.get(conceptKind)
  }
  const reading = contextualReading(
    endpointLineage(definingClaim.subject),
    endpointLineage(claimRef(definingClaim)),
    coreKindLabel,
  )

  const nameClaim = ownClaims.find((claim) => claim.predicate === RELATIONSHIP_NAME_PREDICATE)
  const descriptionClaim = ownClaims.find(
    (claim) => claim.predicate === RELATIONSHIP_DESCRIPTION_PREDICATE,
  )
  const modeClaim = ownClaims.find((claim) => claim.predicate === ACCESS_MODE_PREDICATE)
  const contentClaim = ownClaims.find((claim) => claim.predicate === FLOW_CONTENT_PREDICATE)
  const statusClaim = ownClaims.find((claim) => claim.predicate === LIFECYCLE_STATUS_PREDICATE)

  return {
    id: relationshipId,
    localId: authoredIdOf(relationshipId),
    document: definingClaim.source.path,
    kind,
    kindLabel: kindLabelOf(kind),
    coreKindLabel,
    readingKind: readingKindOf(lineage, coreKindLabel),
    responsibility: responsibilityLetterOf(lineage, kind),
    ...(reading === undefined ? {} : { reading }),
    from: definingClaim.subject,
    to: claimRef(definingClaim),
    name: nameClaim === undefined ? null : claimValue(nameClaim),
    description: descriptionClaim === undefined ? null : claimValue(descriptionClaim),
    mode: modeClaim === undefined ? null : claimValue(modeClaim),
    content: contentClaim === undefined ? null : claimValue(contentClaim),
    status: statusClaim === undefined ? null : claimValue(statusClaim),
    references: ownClaims
      .filter((claim) => claim.predicate === REFERENCE_REFERS_TO_PREDICATE)
      .map((referencesClaim) => {
        const localId = referencesClaim.id.split('~reference-')[1]
        if (localId === undefined) {
          throw new Error(
            `Reference claim "${referencesClaim.id}" on relationship "${relationshipId}" does not follow the "<subject>~reference-<id>" id convention`,
          )
        }
        return {
          id: localId,
          ref: claimRef(referencesClaim),
        }
      })
      .sort((left, right) => left.ref.localeCompare(right.ref)),
    presentIn: ownClaims
      .filter((claim) => claim.predicate === STATE_PRESENT_IN_PREDICATE)
      .map(claimRef)
      .sort(),
  }
}

export function projectGraphForCanvas(
  graph: SemanticGraph,
  profileContext: ResolvedProfileContext,
): CanvasGraph {
  const claimsBySubject = groupClaimsBySubject(graph.claims)
  // Each concept's authored kind, for the readings an edge's endpoints decide.
  const conceptKindOf = new Map<string, string>()
  for (const claim of graph.claims) {
    if (claim.predicate === CONCEPT_KIND_PREDICATE && 'value' in claim.object) {
      conceptKindOf.set(claim.subject, claim.object.value)
    }
  }

  const nodes: CanvasNode[] = []
  const edges: CanvasEdge[] = []

  for (const subject of graph.subjects) {
    const ownClaims = claimsBySubject.get(subject.id) ?? []
    if (subject.type === 'concept') {
      nodes.push(projectConcept(subject.id, ownClaims, profileContext))
    } else {
      edges.push(
        projectRelationship(subject.id, graph.claims, ownClaims, profileContext, conceptKindOf),
      )
    }
  }

  nodes.sort(compareById)
  edges.sort(compareById)

  return { nodes, edges }
}

import type {
  AdapterMapping,
  AdapterSubjectMapping,
} from '../adapter-mapping.js'
import type { EvidenceDocument, EvidenceObservation } from '../evidence.js'

export interface GraphifyGraph {
  readonly nodes: readonly {
    readonly id: string
  }[]
  readonly edges?: readonly {
    readonly id: string
    readonly source: string
    readonly target: string
  }[]
}

export interface GraphifyObservationIssue {
  readonly code: 'YMG101' | 'YMG102'
  readonly message: string
  readonly mapping?: AdapterSubjectMapping
}

export type GraphifyObservationResult =
  | { readonly ok: true; readonly evidence: EvidenceDocument }
  | { readonly ok: false; readonly issues: readonly GraphifyObservationIssue[] }

export function observeGraphify(
  graph: GraphifyGraph,
  mapping: AdapterMapping,
  identity: { readonly id: string; readonly version: string },
): GraphifyObservationResult {
  if (mapping.adapter !== 'graphify') {
    return {
      ok: false,
      issues: [{
        code: 'YMG101',
        message: `Adapter mapping "${mapping.id}@${mapping.version}" belongs to "${mapping.adapter}", not "graphify"`,
      }],
    }
  }
  const relationshipMappings = mapping.mappings.filter(
    ({ type }) => type === 'relationship',
  )
  if (relationshipMappings.length > 0) {
    return {
      ok: false,
      issues: relationshipMappings.map((entry) => ({
        code: 'YMG102',
        message: `Graphify node evidence cannot evaluate relationship subject "${entry.native}"`,
        mapping: entry,
      })),
    }
  }
  const nodeIds = new Set(graph.nodes.map(({ id }) => id))
  const observations: EvidenceObservation[] = mapping.mappings.map(
    (entry) =>
      nodeIds.has(entry.external)
        ? {
            subject: entry.native,
            result: 'confirmed',
            evidence: { uri: `graphify:${entry.external}` },
          }
        : {
            subject: entry.native,
            result: 'not-observed',
            evidence: {
              uri: `graphify:${entry.external}`,
              message: `Graphify node "${entry.external}" was not observed`,
            },
          },
  )
  return {
    ok: true,
    evidence: {
      format: 'yarramate/evidence/v1',
      id: identity.id,
      version: identity.version,
      provider: 'graphify',
      observations,
    },
  }
}

import { isAlias, isMap, isScalar, isSeq, parseDocument } from 'yaml'

/**
 * Every place a subject address can appear on disk, and the surgery that moves
 * one. A rename is only honest if it is total: an address left behind is a
 * dangling reference or, worse, a selector that silently stops matching. The
 * enumeration below is the single statement of where those addresses live, and
 * `test/subject-references.test.ts` derives the same set from the JSON Schemas
 * so a new reference field cannot be added without landing here too.
 */

/** The four on-disk document kinds that can name a subject. */
export type SubjectReferenceGroup =
  | 'document'
  | 'projection'
  | 'evidence'
  | 'adapter-mapping'

/**
 * How the address is spelled at a position.
 * - `declaration`: the subject's own local id, always bare, in its own document.
 * - `reference`: bare local id (meaning "this document") or fully qualified.
 * - `qualified`: always `document#local`, optionally with a `~aspect` suffix
 *   (claim addresses are minted that way - see `compiler.ts`).
 */
export type SubjectReferenceForm = 'declaration' | 'reference' | 'qualified'

export interface SubjectReferencePosition {
  readonly group: SubjectReferenceGroup
  /**
   * Key path from the document root; `*` matches every element of a
   * collection, which is every index of a sequence and every value of a
   * mapping whose keys are open. Both spell `*` because the schema, not the
   * position, is what decides which one a path lands on: `items` and
   * `patternProperties` are the same shape of "and now, each of these".
   */
  readonly path: readonly string[]
  readonly form: SubjectReferenceForm
}

export const SUBJECT_REFERENCE_POSITIONS: readonly SubjectReferencePosition[] =
  [
    { group: 'document', path: ['concepts', '*', 'id'], form: 'declaration' },
    { group: 'document', path: ['concepts', '*', 'owner'], form: 'reference' },
    {
      group: 'document',
      path: ['concepts', '*', 'distinctFrom', '*'],
      form: 'reference',
    },
    {
      group: 'document',
      path: ['concepts', '*', 'supersedes', '*'],
      form: 'reference',
    },
    // The scoped succession form, `{ subject, inRespectOf }` (ADR 0109). A
    // rename has to move this one too, or a scoped succession would silently
    // keep pointing at the old address while the bare form beside it moved.
    {
      group: 'document',
      path: ['concepts', '*', 'supersedes', '*', 'subject'],
      form: 'reference',
    },
    {
      group: 'document',
      path: ['concepts', '*', 'constraints', '*', 'ref'],
      form: 'reference',
    },
    // The subjects bound into a pattern instance's slots (ADR 0123). Keyed by
    // slot name rather than indexed, which is why it went missing: this is the
    // only address in any of the four schemas that lives in a mapping, and the
    // completeness walker below derived only sequences.
    {
      group: 'document',
      path: ['concepts', '*', 'parts', '*'],
      form: 'reference',
    },
    {
      group: 'document',
      path: ['concepts', '*', 'references', '*', 'ref'],
      form: 'reference',
    },
    {
      group: 'document',
      path: ['concepts', '*', 'attestations', '*', 'by'],
      form: 'reference',
    },
    {
      group: 'document',
      path: ['relationships', '*', 'id'],
      form: 'declaration',
    },
    {
      group: 'document',
      path: ['relationships', '*', 'from'],
      form: 'reference',
    },
    { group: 'document', path: ['relationships', '*', 'to'], form: 'reference' },
    {
      group: 'document',
      path: ['relationships', '*', 'references', '*', 'ref'],
      form: 'reference',
    },
    {
      group: 'projection',
      path: ['query', 'subjects', '*'],
