    2,
  )}\n`

const checkJson = (
  ok: boolean,
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): string =>
  `${JSON.stringify(
    {
      format: 'yarramate/likec4-check-result/v1',
      ok,
      diagnostics,
    },
    null,
    2,
  )}\n`

const unmappedSubjectPreviewLength = 3

const summarizeUnmappedSubjects = (
  diagnostics: readonly LikeC4PreparationDiagnostic[],
): readonly LikeC4PreparationDiagnostic[] =>
  (
    [
      ['YMLC102', 'concepts'],
      ['YMLC111', 'relationships'],
    ] as const
  ).reduce<readonly LikeC4PreparationDiagnostic[]>(
    (current, [code, noun]) => {
      const unmapped = current.filter(
        (diagnostic) => diagnostic.code === code,
      )
      if (unmapped.length <= unmappedSubjectPreviewLength) return current
      const preview = unmapped
        .slice(0, unmappedSubjectPreviewLength)
        .map((diagnostic) =>
          'subject' in diagnostic && diagnostic.subject !== undefined
            ? `"${diagnostic.subject}"`
            : `"${diagnostic.path}:${diagnostic.line}"`,
        )
        .join(', ')
      const summary: LikeC4PreparationDiagnostic = {
        ...unmapped[0]!,
        message:
          `${unmapped.length} projected ${noun} have no LikeC4 mapping ` +
          `(first: ${preview}); run "yarramate-likec4 map --sync" to add ` +
          'the missing mappings',
      }
      let summarized = false
      return current.flatMap((diagnostic) => {
        if (diagnostic.code !== code) return [diagnostic]
        if (summarized) return []
        summarized = true
        return [summary]
      })
    },
    diagnostics,
  )

const lowerCamel = (value: string) =>
  value.replaceAll(/-([a-z0-9])/g, (_, character: string) =>
    character.toUpperCase(),
  )

const runLikeC4MapSync = (
  args: readonly string[],
  cwd: string,
): CliResult => {
  const sync = args[0]
  const prune = args[1] === '--prune'
  const mappingPath = args[prune ? 2 : 1]
  const sourcePaths = args.slice(prune ? 3 : 2)
  if (
    sync !== '--sync' ||
    mappingPath === undefined ||
    mappingPath.startsWith('-') ||
    sourcePaths.length === 0 ||
    sourcePaths.some((path) => path.startsWith('-'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  try {
    const resolved = resolveCliWorkspaceSources(sourcePaths, cwd)
    if (!resolved.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(resolved.diagnostics),
        stderr: '',
      }
    }
    const compilation = compileWorkspace(
      resolved.paths.map((path) => ({
        path,
        source: readFileSync(resolve(cwd, path), 'utf8'),
      })),
    )
    if (!compilation.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(compilation.diagnostics),
        stderr: '',
      }
    }
    const absoluteMappingPath = resolve(cwd, mappingPath)
    const original = readFileSync(absoluteMappingPath, 'utf8')
    const loaded = loadAdapterMapping({
      path: mappingPath,
      source: original,
    })
    if (!loaded.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(loaded.diagnostics),
        stderr: '',
      }
    }
    if (loaded.mapping.adapter !== 'likec4') {
      const location = adapterMappingLocation(loaded.mapping, 'adapter')
      return {
        exitCode: 1,
        stdout: diagnosticJson([{
          severity: 'error',
          code: 'YMLC101',
          message: `Adapter mapping targets "${loaded.mapping.adapter}", not "likec4"`,
          ...location,
        }]),
        stderr: '',
      }
    }
    const graphSubjects = new Set(
      compilation.graph.subjects.map(({ id }) => id),
    )
    const staleCount = loaded.mapping.mappings.filter(
      ({ native }) => !graphSubjects.has(native),
    ).length
    const validation = validateAdapterMapping(
      compilation.graph,
      loaded.mapping,
    )
    const blockingDiagnostics = validation.ok
      ? []
      : validation.diagnostics.filter(({ code }) => code !== 'YM601')
    if (blockingDiagnostics.length > 0) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(blockingDiagnostics),
        stderr: '',
      }
    }
    const mapped = new Set(
      loaded.mapping.mappings.map(({ native }) => native),
    )
    const claimedExternal = new Set(
      loaded.mapping.mappings
        .filter(({ native }) => !prune || graphSubjects.has(native))
        .map(({ external }) => external),
    )
    const architectureStates = new Set(
      compilation.graph.claims
        .filter(({ predicate }) => predicate === 'yarramate/state/type')
        .map(({ subject }) => subject),
    )
    const additions = compilation.graph.subjects
      .filter(
        ({ id }) => !mapped.has(id) && !architectureStates.has(id),
      )
      .map((subject) => {
        // A subject id is the authored id, unique across the workspace, so it
        // is the whole name. The document-prefixed fallback that used to break
        // ties has nothing left to disambiguate; two ids can still collapse
        // onto one camel-case name (`foo-bar` and `fooBar`), and the numeric
        // suffix below has always been what separates those.
        let external = lowerCamel(subject.id)
        let suffix = 2
        const base = external
        while (claimedExternal.has(external)) {
          external = `${base}_${suffix}`
          suffix += 1
        }
        claimedExternal.add(external)
        return {
          native: subject.id,
          external,
          type: subject.type,
        }
      })
    if (additions.length === 0 && (!prune || staleCount === 0)) {
      return {
        exitCode: 0,
        stdout:
          staleCount === 0
            ? `LikeC4 mapping ${mappingPath} is already synchronized\n`
            : `LikeC4 mapping ${mappingPath} has ${staleCount} stale ${staleCount === 1 ? 'mapping' : 'mappings'} (use --prune)\n`,
        stderr: '',
      }
    }
    const document = parseDocument(original)
    const mappings = document.getIn(['mappings'], true)
    if (prune && isSeq(mappings)) {
      const firstMappingWasPruned =
        mappings.items.length > 0 &&
        isMap(mappings.items[0]) &&
        !graphSubjects.has(String(mappings.items[0].get('native')))
      mappings.items = mappings.items.filter(
        (item) =>
          !isMap(item) ||
          graphSubjects.has(String(item.get('native'))),
      )
      if (firstMappingWasPruned) mappings.commentBefore = undefined
    }
    for (const addition of additions) {
      document.addIn(['mappings'], addition)
    }
    if (isSeq(mappings)) mappings.flow = false
    const candidate = document.toString({ lineWidth: 0 })
    const candidateMapping = loadAdapterMapping({
      path: mappingPath,
      source: candidate,
    })
    if (!candidateMapping.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(candidateMapping.diagnostics),
        stderr: '',
      }
    }
    const candidateValidation = validateAdapterMapping(
      compilation.graph,
      candidateMapping.mapping,
    )
    const candidateBlockingDiagnostics = candidateValidation.ok
      ? []
      : candidateValidation.diagnostics.filter(
          ({ code }) => prune || code !== 'YM601',
        )
    if (candidateBlockingDiagnostics.length > 0) {
      return {
        exitCode: 1,
        stdout: diagnosticJson(candidateBlockingDiagnostics),
        stderr: '',
      }
    }
    const staged = stageFile(absoluteMappingPath, candidate)
    try {
      staged.publish()
    } finally {
      staged.cleanup()
    }
    return {
      exitCode: 0,
      stdout: prune
        ? additions.length > 0
          ? `Added ${additions.length} and pruned ${staleCount} stale LikeC4 ${staleCount === 1 ? 'mapping' : 'mappings'} in ${mappingPath}\n`
          : `Pruned ${staleCount} stale LikeC4 ${staleCount === 1 ? 'mapping' : 'mappings'} from ${mappingPath}\n`
        : `Added ${additions.length} LikeC4 ${additions.length === 1 ? 'mapping' : 'mappings'} to ${mappingPath}` +
          (staleCount === 0
            ? '\n'
            : `; left ${staleCount} stale ${staleCount === 1 ? 'mapping' : 'mappings'} (use --prune)\n`),
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

// Ownership fields never gate updates: a marker of either format version
// plus intact output digests proves the directory is entirely
// machine-generated, so regenerating after the inputs changed loses nothing.
const readGeneratedProjectMarker = (
  markerPath: string,
): Readonly<Record<string, unknown>> | undefined => {
  let marker: unknown
  try {
    marker = JSON.parse(readFileSync(markerPath, 'utf8'))
  } catch {
    return undefined
  }
  return validateGeneratedProjectMarker(marker) ||
    validateGeneratedProjectV2Marker(marker) ||
    validateGeneratedProjectPreFlattenMarker(marker) ||
    validateGeneratedProjectV2PreFlattenMarker(marker)
    ? (marker as Readonly<Record<string, unknown>>)
    : undefined
}

const changedGeneratedFile = (
  projectPath: string,
  marker: Readonly<Record<string, unknown>>,
): string | undefined => {
  // Markers written before output digests existed are accepted once and
  // upgraded on regeneration.
  if (marker['digests'] === undefined) return undefined
  const digests = marker['digests'] as Readonly<Record<string, string>>
  return generatedFileNames.find((file) => {
    const path = resolve(projectPath, file)
    return (
      !existsSync(path) || sha256(readFileSync(path)) !== digests[file]
    )
  })
}

const publishGeneratedProject = (
  cwd: string,
  outputDirectory: string,
  input: {
    readonly projectName: string
    readonly title: string
    readonly modelSource: string
    readonly ownership: Readonly<Record<string, unknown>>
    readonly inputDigests: Readonly<Record<string, string>>
  },
): CliResult => {
  const projectPath = resolve(cwd, outputDirectory)
  const markerPath = resolve(projectPath, 'yarramate.generated.json')
  const updating = existsSync(projectPath)
  if (updating) {
    const projectStat = lstatSync(projectPath)
    if (projectStat.isSymbolicLink() || !projectStat.isDirectory()) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Output directory already exists: ${projectPath}\n`,
      }
    }
    const unsafeFile = [
      markerPath,
      ...generatedFileNames.map((file) => resolve(projectPath, file)),
    ].find((path) => {
      if (!existsSync(path)) return false
      const stat = lstatSync(path)
      return stat.isSymbolicLink() || !stat.isFile()
    })
    if (unsafeFile !== undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Generated project contains an unsafe file: ${unsafeFile}\n`,
      }
    }
    const marker = readGeneratedProjectMarker(markerPath)
    if (marker === undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Output directory exists but is not a YarraMate-generated project: ${projectPath}\n`,
      }
    }
    const changedFile = changedGeneratedFile(projectPath, marker)
    if (changedFile !== undefined) {
      return {
        exitCode: 2,
        stdout: '',
        stderr: `Generated project file has changed: ${resolve(projectPath, changedFile)}\n`,
      }
    }
  } else {
    mkdirSync(projectPath, { recursive: true })
  }
  const specificationSource = readFileSync(
    fileURLToPath(
      new URL(
        '../../assets/likec4/specification.likec4',
        import.meta.url,
      ),
    ),
  )
  const configSource = `${JSON.stringify(
    {
      $schema: 'https://likec4.dev/schemas/config.json',
      name: input.projectName,
      title: input.title,
    },
    null,
    2,
  )}\n`
  const markerSource = `${JSON.stringify(
    {
      ...input.ownership,
      files: [
        'likec4.config.json',
        'model.likec4',
        'specification.likec4',
      ],
      digests: {
        'likec4.config.json': sha256(configSource),
        'model.likec4': sha256(input.modelSource),
        'specification.likec4': sha256(specificationSource),
      },
      inputDigests: input.inputDigests,
    },
    null,
    2,
  )}\n`
  publishFiles([
    {
      destination: resolve(projectPath, 'likec4.config.json'),
      value: configSource,
    },
    {
      destination: resolve(projectPath, 'model.likec4'),
      value: input.modelSource,
    },
    {
      destination: resolve(projectPath, 'specification.likec4'),
      value: specificationSource,
    },
    { destination: markerPath, value: markerSource },
  ])
  return {
    exitCode: 0,
    stdout: updating
      ? `Updated LikeC4 project at ${projectPath}\n`
      : `Wrote LikeC4 project to ${projectPath}\n`,
    stderr: '',
  }
}

// Freshness is a pure digest comparison between the marker and the would-be
// export; nothing on disk is written or semantically judged.
const checkGeneratedProject = (
  cwd: string,
  outputDirectory: string,
  input: {
    readonly modelSource: string
    readonly inputDigests: Readonly<Record<string, string>>
  },
): CliResult => {
  const projectPath = resolve(cwd, outputDirectory)
  if (!existsSync(projectPath)) {
    return {
      exitCode: 1,
      stdout: 'Generated LikeC4 output: absent\n',
      stderr: '',
    }
  }
  const marker = readGeneratedProjectMarker(
    resolve(projectPath, 'yarramate.generated.json'),
  )
  if (marker === undefined) {
    return {
      exitCode: 2,
      stdout: '',
      stderr: `Output directory exists but is not a YarraMate-generated project: ${projectPath}\n`,
    }
  }
  const changedFile = changedGeneratedFile(projectPath, marker)
  if (changedFile !== undefined) {
    return {
      exitCode: 1,
      stdout:
        'Generated LikeC4 output: modified\n' +
        'Reason:\n' +
        `- generated file changed: ${resolve(projectPath, changedFile)}\n` +
        'Safe to regenerate: no\n',
      stderr: '',
    }
  }
  const recordedInputs = marker['inputDigests'] as
    | Readonly<Record<string, string>>
    | undefined
  const reasons: string[] = []
  if (recordedInputs === undefined) {
    reasons.push('marker predates input digests')
  } else {
    const inputPaths = [
      ...new Set([
        ...Object.keys(recordedInputs),
        ...Object.keys(input.inputDigests),
      ]),
    ].sort()
    for (const path of inputPaths) {
      const recorded = recordedInputs[path]
      const current = input.inputDigests[path]
      if (recorded === undefined) reasons.push(`input added: ${path}`)
      else if (current === undefined) {
        reasons.push(`input removed: ${path}`)
      } else if (recorded !== current) {
        reasons.push(`input changed: ${path}`)
      }
    }
  }
  const digests = marker['digests'] as
    | Readonly<Record<string, string>>
    | undefined
  if (
    digests !== undefined &&
    sha256(input.modelSource) !== digests['model.likec4']
  ) {
    reasons.push('model source changed')
  }
  if (reasons.length === 0) {
    return {
      exitCode: 0,
      stdout: 'Generated LikeC4 output: fresh\n',
      stderr: '',
    }
  }
  return {
    exitCode: 1,
    stdout:
      'Generated LikeC4 output: stale\n' +
      'Reason:\n' +
      reasons.map((reason) => `- ${reason}\n`).join('') +
      'Safe to regenerate: yes\n',
    stderr: '',
  }
}

export function runLikeC4Cli(
  args: readonly string[],
  cwd: string = process.cwd(),
): CliResult {
  if (args[0] === '--version') {
    return versionResult('yarramate-likec4')
  }
  if (args[0] === 'map') {
    return runLikeC4MapSync(args.slice(1), cwd)
  }
  const checkFreshness =
    args[0] === 'export-project' && args.includes('--check')
  const [command, projectionPath, mappingPath, ...options] = checkFreshness
    ? args.filter((argument) => argument !== '--check')
    : args
  let projectDefinitionMode = false
  if (
    (command === 'check' || command === 'export-project') &&
    projectionPath !== undefined
  ) {
    try {
      projectDefinitionMode =
        parseDocument(
          readFileSync(resolve(cwd, projectionPath), 'utf8'),
        ).get('format') === 'yarramate/likec4-project/v1'
    } catch {
      projectDefinitionMode = false
    }
  }
  const outputDirectory =
    command === 'export-project'
      ? projectDefinitionMode
        ? mappingPath
        : options[0]
      : undefined
  const sourceOptions =
    projectDefinitionMode && command === 'check'
      ? [mappingPath, ...options].filter(
          (value): value is string => value !== undefined,
        )
      : command === 'export-project'
      ? projectDefinitionMode
        ? options
        : options.slice(1)
      : options
  const json = command === 'check' && sourceOptions.includes('--json')
  let invalidOptions = false
  let kindMappingPath: string | undefined
  let comparison:
    | { readonly from: string; readonly to: string }
    | undefined
  let changedRange: string | undefined
  const sourcePaths: string[] = []
  for (let index = 0; index < sourceOptions.length; index += 1) {
    const option = sourceOptions[index]!
    if (option === '--json') {
      if (command !== 'check') invalidOptions = true
      continue
    }
    if (option === '--kinds') {
      const value = sourceOptions[index + 1]
      if (
        value === undefined ||
        value.startsWith('-') ||
        kindMappingPath !== undefined
      ) {
        invalidOptions = true
      } else {
        kindMappingPath = value
        index += 1
      }
      continue
    }
    if (option === '--changed') {
      const value = sourceOptions[index + 1]
      if (
        value === undefined ||
        value.startsWith('-') ||
        changedRange !== undefined
      ) {
        invalidOptions = true
      } else {
        changedRange = value
        index += 1
      }
      continue
    }
    if (option === '--compare') {
      const from = sourceOptions[index + 1]
      const to = sourceOptions[index + 2]
      if (
        from === undefined ||
        to === undefined ||
        from.startsWith('-') ||
        to.startsWith('-') ||
        comparison !== undefined
      ) {
        invalidOptions = true
      } else {
        comparison = { from, to }
        index += 2
      }
      continue
    }
    if (option.startsWith('-')) invalidOptions = true
    else sourcePaths.push(option)
  }
  if (
    (command !== 'check' &&
      command !== 'export' &&
      command !== 'export-project') ||
    projectionPath === undefined ||
    (!projectDefinitionMode && mappingPath === undefined) ||
    (projectDefinitionMode &&
      command === 'export-project' &&
      mappingPath === undefined) ||
    (command === 'export-project' && outputDirectory === undefined) ||
    (projectDefinitionMode &&
      (kindMappingPath !== undefined || comparison !== undefined)) ||
    (changedRange !== undefined &&
      !(projectDefinitionMode && command === 'export-project')) ||
    invalidOptions ||
    sourcePaths.length === 0 ||
    sourcePaths.some((argument) => argument.startsWith('-'))
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  const diagnosticOutput = (
    diagnostics: Parameters<typeof diagnosticJson>[0],
  ) =>
    json
      ? checkJson(false, diagnostics)
      : diagnosticJson(
          command === 'check'
            ? summarizeUnmappedSubjects(diagnostics)
            : diagnostics,
        )

  try {
    const resolved = resolveCliWorkspaceSources(sourcePaths, cwd)
    if (!resolved.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticOutput(resolved.diagnostics),
        stderr: '',
      }
    }
    const sources = resolved.paths.map((path) => ({
      path,
      source: readFileSync(resolve(cwd, path), 'utf8'),
    }))
    if (projectDefinitionMode) {
      const projectSource = {
        path: projectionPath,
        source: readFileSync(resolve(cwd, projectionPath), 'utf8'),
      }
      const projectDirectory = dirname(resolve(cwd, projectionPath))
      // The git-derived review overlay is the CLI's own: it needs a
      // repository. Everything after it runs the same pure pipeline the
      // path-free entry runs (ADR 0156).
      let gitChange
      if (changedRange !== undefined) {
        const modelDocuments = sources.flatMap((candidate) => {
          const parsed = parseDocument(candidate.source)
          if (parsed.get('format') !== 'yarramate/v1') return []
          const documentId = parsed.get('id')
          return typeof documentId === 'string'
            ? [{ ...candidate, documentId }]
            : []
        })
        const derived = deriveChangedSubjects(
          cwd,
          changedRange,
          modelDocuments,
        )
        if (!derived.ok) {
          return { exitCode: 2, stdout: '', stderr: `${derived.message}\n` }
        }
        const all = [
          ...derived.changed.concepts,
          ...derived.changed.relationships,
        ]
        gitChange = {
          range: derived.changed.range,
          added: derived.changed.added,
          modified: all.filter(
            (id) => !derived.changed.added.includes(id),
          ),
        }
      }
      const exported = exportLikeC4ProjectFromSources({
        project: projectSource,
        sources,
        readReference: (path) => {
          try {
            return {
              path,
              source: readFileSync(resolve(projectDirectory, path), 'utf8'),
            }
          } catch {
            return undefined
          }
        },
        requireMappedRelationships: command === 'check',
        ...(gitChange === undefined ? {} : { gitChange }),
      })
      if (!exported.ok) {
        return {
          exitCode: 1,
          stdout: diagnosticOutput(exported.diagnostics),
          stderr: '',
        }
      }
      if (command === 'check') {
        return {
          exitCode: 0,
          stdout: json
            ? checkJson(true, [])
            : `Checked LikeC4 project ${exported.projectIdentity}: no errors\n`,
          stderr: '',
        }
      }
      const inputDigests = inputDigestsOf(exported.inputs)
      if (checkFreshness) {
        return checkGeneratedProject(cwd, outputDirectory!, {
          modelSource: exported.modelSource,
          inputDigests,
        })
      }
      return publishGeneratedProject(cwd, outputDirectory!, {
        projectName: projectNameOf(exported.projectIdentity),
        title: exported.project.title,
        modelSource: exported.modelSource,
        ownership: { ...ownershipOf(exported) },
        inputDigests,
      })
    }
    const projectionSource = {
      path: projectionPath,
      source: readFileSync(resolve(cwd, projectionPath), 'utf8'),
    }
    const mappingSource = {
      path: mappingPath!,
      source: readFileSync(resolve(cwd, mappingPath!), 'utf8'),
    }
    const kindMappingSource =
      kindMappingPath === undefined
        ? undefined
        : {
            path: kindMappingPath,
            source: readFileSync(resolve(cwd, kindMappingPath), 'utf8'),
          }
    const prepared = prepareLikeC4Export({
      sources,
      projection: projectionSource,
      subjectMapping: mappingSource,
      ...(kindMappingSource === undefined
        ? {}
        : { kindMapping: kindMappingSource }),
      ...(comparison === undefined ? {} : { comparison }),
      vocabulary: command === 'export' ? 'consumer' : 'bundled',
      requireMappedRelationships: command === 'check',
    })
    if (!prepared.ok) {
      return {
        exitCode: 1,
        stdout: diagnosticOutput(prepared.diagnostics),
        stderr: '',
      }
    }
    if (command === 'check') {
      return {
        exitCode: 0,
        stdout: json
          ? checkJson(true, [])
          : `Checked LikeC4 export ${prepared.projection.projection}: no errors\n`,
        stderr: '',
      }
    }
    if (command === 'export') {
      return { exitCode: 0, stdout: prepared.source, stderr: '' }
    }

    const projectionIdentity = prepared.projection.projection
    const mappingIdentity = `${prepared.subjectMapping.id}@${prepared.subjectMapping.version}`
    const kindMappingIdentity =
      prepared.kindMapping === undefined
        ? undefined
        : `${prepared.kindMapping.id}@${prepared.kindMapping.version}`
    const comparisonIdentity = comparison
    const inputDigests = inputDigestsOf([
      projectionSource,
      mappingSource,
      ...(kindMappingSource === undefined ? [] : [kindMappingSource]),
      ...sources,
    ])
    if (checkFreshness) {
      return checkGeneratedProject(cwd, outputDirectory!, {
        modelSource: prepared.source,
        inputDigests,
      })
    }
    return publishGeneratedProject(cwd, outputDirectory!, {
      projectName: ['yarramate', projectionIdentity]
        .join('-')
        .replaceAll(/[^A-Za-z0-9_-]/g, '-'),
      title:
        prepared.projection.presentation?.title ??
        projectionIdentity.slice(0, projectionIdentity.lastIndexOf('@')),
      modelSource: prepared.source,
      ownership: {
        format: 'yarramate/likec4-generated-project/v1',
        projection: projectionIdentity,
        mapping: mappingIdentity,
        ...(kindMappingIdentity === undefined
          ? {}
          : { kindMapping: kindMappingIdentity }),
        ...(comparisonIdentity === undefined
          ? {}
          : { comparison: comparisonIdentity }),
      },
      inputDigests,
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

if (isMainModule(import.meta.url, process.argv[1])) {
  const result = runLikeC4Cli(process.argv.slice(2))
  process.stdout.write(result.stdout)
  process.stderr.write(result.stderr)
  process.exitCode = result.exitCode
}

import type {
  ReconciliationFinding,
  ReconciliationReport,
} from './reconciliation.js'

/**
 * The reconciliation report for a person (#526, ADR 0153).
 *
 * The JSON report is the contract (EVIDENCE.md) and stays the verb's
 * default; this is the same report said in lines, in the same order, with
 * nothing added and nothing judged. Every count the summary carries is on
 * the first lines; every finding is one line, plus its message where the
 * provider left one; the lists that follow appear only when they hold
 * something, and the notes close, because they are what the report says
 * about its own limits.
 */
export const reconciliationReportText = (
  report: ReconciliationReport,
): string => {
  const { summary } = report
  const lines: string[] = []
  const row = (label: string, ...cells: readonly string[]): void => {
    lines.push(`${label.padEnd(16)}${cells.join('  ')}`)
  }
  row('reconciliation', report.workspace)
  row(
    'observations',
    String(summary.observations),
    `confirmed ${summary.confirmed}`,
    `contradicted ${summary.contradicted}`,
    `unknown ${summary.unknown}`,
    `not observed ${summary.notObserved}`,
    ...(summary.unsupportedAbsences === undefined
      ? []
      : [`unsupported absences ${summary.unsupportedAbsences}`]),
  )
  if (
    summary.staleAttestations !== undefined ||
    summary.unconfirmedAttestations !== undefined
  ) {
    row(
      'attestations',
      `stale ${summary.staleAttestations ?? 0}`,
      `unconfirmed ${summary.unconfirmedAttestations ?? 0}`,
    )
  }
  row(
    'expectations',
    `compared ${summary.expectationsCompared}`,
    `without observation ${summary.expectationsWithoutObservation}`,
  )
  row('subjects', `without evidence ${summary.subjectsWithoutEvidence}`)
  row(
    'artifacts',
    ...(summary.artifactsInScope === undefined
      ? ['not assessed']
      : [
          `in scope ${summary.artifactsInScope}`,
          `unclaimed ${summary.unclaimedArtifacts ?? 0}`,
        ]),
  )
  row('findings', String(summary.findings))

  const section = (title: string, body: readonly string[]): void => {
    if (body.length === 0) return
    lines.push('', title)
    lines.push(...body)
  }
  section(
    'Findings',
    report.findings.flatMap((finding) => findingLines(finding)),
  )
  section(
    'Subjects without evidence',
    (report.unobservedSubjects ?? []).map((id) => `  ${id}`),
  )
  section(
    'Expectations without observation',
    (report.unobservedExpectations ?? []).map(
      (expectation) =>
        `  ${expectation.subject}  ${expectation.provider}/${expectation.key} expected ${expectation.expected}  ${expectation.declared.path}:${expectation.declared.line}`,
    ),
  )
  section(
    'Unclaimed artifacts',
    (report.unclaimedArtifacts ?? []).map((path) => `  ${path}`),
  )
  section(
    'Coverage scope',
    (report.coverageScope ?? []).map((pattern) => `  ${pattern}`),
  )
  section(
    'Notes',
    (report.notes ?? []).map((note) => `  ${note}`),
  )
  return `${lines.join('\n')}\n`
}

const findingLines = (finding: ReconciliationFinding): readonly string[] => {
  const label = finding.result.replace(/-/g, ' ').padEnd(24)
  if (finding.result === 'stale-attestation') {
    const changed =
      finding.changedAt === undefined
        ? ''
        : `; the subject's wording changed ${finding.changedAt}`
    return [
      `  ${label}${finding.target.id}  ${finding.attestation.topic}, by ${finding.attestation.by} on ${finding.attestation.on}${changed}  ${finding.evidence.uri}`,
    ]
  }
  if (finding.result === 'unconfirmed-attestation') {
    return [
      `  ${label}${finding.target.id}  ${finding.attestation.topic}, by ${finding.attestation.by}, recorded by ${finding.attestation.recordedBy} on ${finding.attestation.on}  ${finding.declared.path}:${finding.declared.line}`,
    ]
  }
  const head = `  ${label}${finding.target.type === 'claim' ? 'claim ' : ''}${finding.target.id}  ${finding.provider}, ${finding.evidenceDocument}  ${finding.evidence.uri}`
  const detail: string[] = []
  if (finding.asserted !== undefined) {
    detail.push(
      `    asserts ${finding.asserted.from} -${finding.asserted.kind}-> ${finding.asserted.to}`,
    )
  }
  if (finding.expectation !== undefined) {
    detail.push(
      `    expected ${finding.expectation.key} = ${finding.expectation.expected}, observed ${finding.expectation.observed}  ${finding.expectation.declared.path}:${finding.expectation.declared.line}`,
    )
  }
  if (finding.evidence.message !== undefined) {
    detail.push(`    ${finding.evidence.message}`)
  }
  return [head, ...detail]
}

