import { spawnSync } from 'node:child_process'
import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseDocument } from 'yaml'
import { deriveChangedSubjects } from './changed.js'
import {
  humanDiagnostics,
  usage,
  type CliResult,
} from './cli-support.js'
import type { Diagnostic } from './compiler.js'
import { evaluateProjection, renderProjectionMarkdown } from './projection.js'
import { createFileSystemStore } from './source-store.js'
import { posixDirectoryOf } from './apply-command.js'
import {
  briefsFromResult,
  exportBriefs,
  exportGraph,
  exportMarkdown,
  exportGovernance,
  exportResponsibility,
  exportRtm,
  exportWorkbook,
} from './tools/export.js'
import {
  compileOf,
  readSource,
  type ToolFailure,
  type ToolWorkspace,
} from './tools/workspace.js'
import { loadWorkspaceManifest } from './workspace.js'

// Every kind is derived in `tools/export.ts` (ADR 0156): this command
// parses arguments, resolves the manifest against the filesystem, and
// writes what the core hands back where `--out` says. The git-derived
// review slice (`--changed`) is the CLI's own and reuses the same pieces;
// the LikeC4 kind delegates to the `yarramate-likec4` binary, as before.

const here = dirname(fileURLToPath(import.meta.url))
const likec4AdapterEntry = join(here, 'adapters', 'likec4-cli.js')

interface ParsedExport {
  readonly positionals: readonly string[]
  readonly out?: string
  readonly budget?: number
  readonly changed?: string
  readonly json: boolean
}

const parseExportOptions = (
  options: readonly string[],
): ParsedExport | undefined => {
  const positionals: string[] = []
  let out: string | undefined
  let budget: number | undefined
  let changed: string | undefined
  let json = false
  for (let index = 0; index < options.length; index += 1) {
    const option = options[index]
    if (option === '--json') {
      json = true
      continue
    }
    if (
      option === '--out' ||
      option === '--budget' ||
      option === '--changed'
    ) {
      const value = options[index + 1]
      if (value === undefined || value.startsWith('-')) return undefined
      if (option === '--out') {
        if (out !== undefined) return undefined
        out = value
      } else if (option === '--changed') {
        if (changed !== undefined) return undefined
        changed = value
      } else {
        if (budget !== undefined || !/^[1-9][0-9]*$/.test(value)) {
          return undefined
        }
        budget = Number(value)
      }
      index += 1
      continue
    }
    if (option === undefined || option.startsWith('-')) return undefined
    positionals.push(option)
  }
  return {
    positionals,
    ...(out === undefined ? {} : { out }),
    ...(budget === undefined ? {} : { budget }),
    ...(changed === undefined ? {} : { changed }),
    json,
  }
}

export function runExportCommand(
  options: readonly string[],
  cwd: string,
): CliResult {
  const [kind, ...rest] = options
  if (
    kind === undefined ||
    ![
      'graph',
      'markdown',
      'briefs',
      'rtm',
      'responsibility',
      'governance',
      'likec4',
      'xlsx',
    ].includes(kind)
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }
  const parsed = parseExportOptions(rest)
  if (parsed === undefined) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  if (kind === 'likec4') {
    const [projectDefinition, outputDirectory, workspacePath] =
      parsed.positionals
    if (
      parsed.positionals.length !== 3 ||
      projectDefinition === undefined ||
      outputDirectory === undefined ||
      workspacePath === undefined ||
      parsed.out !== undefined ||
      parsed.budget !== undefined ||
      parsed.json
    ) {
      return { exitCode: 2, stdout: '', stderr: usage }
    }
    const changedArguments =
      parsed.changed === undefined ? [] : ['--changed', parsed.changed]
    if (!existsSync(likec4AdapterEntry)) {
      return {
        exitCode: 2,
        stdout: '',
        stderr:
          `LikeC4 adapter entry not found at ${likec4AdapterEntry}; ` +
          'run from the installed package or use the yarramate-likec4 binary directly\n',
      }
    }
    const delegated = spawnSync(
      process.execPath,
      [
        likec4AdapterEntry,
        'export-project',
        projectDefinition,
        outputDirectory,
        workspacePath,
        ...changedArguments,
      ],
      { cwd, encoding: 'utf8' },
    )
    const exitCode = delegated.status === 0 ? 0 : delegated.status === 1 ? 1 : 2
    return {
      exitCode,
      stdout: delegated.stdout ?? '',
      stderr: delegated.stderr ?? '',
    }
  }

  const usesChanged = parsed.changed !== undefined
  const wholeWorkspace = kind === 'graph' || kind === 'rtm' || kind === 'governance'
  const expectedPositionals = wholeWorkspace || usesChanged ? 1 : 2
  const workspacePath = parsed.positionals[expectedPositionals - 1]
  const projectionPath =
    wholeWorkspace || usesChanged ? undefined : parsed.positionals[0]
  if (
    parsed.positionals.length !== expectedPositionals ||
    workspacePath === undefined ||
    parsed.json ||
    (usesChanged && (wholeWorkspace || kind === 'responsibility')) ||
    (parsed.budget !== undefined && kind !== 'briefs') ||
    ((kind === 'briefs' ||
      kind === 'rtm' ||
      kind === 'responsibility' ||
      kind === 'governance' ||
      kind === 'xlsx') &&
      parsed.out === undefined)
  ) {
    return { exitCode: 2, stdout: '', stderr: usage }
  }

  try {
    const manifestSource = readFileSync(resolve(cwd, workspacePath), 'utf8')
    if (
      parseDocument(manifestSource).get('format') !== 'yarramate/workspace/v1'
    ) {
      return {
        exitCode: 2,
        stdout: '',
        stderr:
          'export requires an explicit workspace manifest (yarramate/workspace/v1)\n',
      }
    }
    const failed = (diagnostics: readonly Diagnostic[]): CliResult => ({
      exitCode: 1,
      stdout: humanDiagnostics(diagnostics),
      stderr: '',
    })
    const failedTool = (failure: ToolFailure): CliResult =>
      failure.reason === 'diagnostics'
        ? failed(failure.diagnostics)
        : { exitCode: 2, stdout: '', stderr: `${failure.message}\n` }
    const loadedWorkspace = loadWorkspaceManifest(
      { path: workspacePath, source: manifestSource },
      cwd,
    )
    if (!loadedWorkspace.ok) return failed(loadedWorkspace.diagnostics)
    const workspace = loadedWorkspace.workspace
    const tool: ToolWorkspace = {
      store: createFileSystemStore(cwd),
      workspace,
      manifestDirectory: posixDirectoryOf(workspacePath),
    }
    const writeText = (path: string, text: string): void => {
      const outPath = resolve(cwd, path)
      mkdirSync(dirname(outPath), { recursive: true })
      writeFileSync(outPath, text, 'utf8')
    }

    if (kind === 'rtm') {
      const exported = exportRtm(tool)
      if (!exported.ok) return failedTool(exported)
      const { markdown, rtm } = exported.result
      writeText(join(parsed.out!, 'RTM.md'), markdown)
      writeText(join(parsed.out!, 'rtm.json'), `${JSON.stringify(rtm, null, 2)}\n`)
      return {
        exitCode: 0,
        stdout:
          `Wrote RTM.md and rtm.json (${rtm.summary.rows} row${
            rtm.summary.rows === 1 ? '' : 's'
          }, ${rtm.summary.gaps} gap${
            rtm.summary.gaps === 1 ? '' : 's'
          }) to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'governance') {
      const exported = exportGovernance(tool)
      if (!exported.ok) return failedTool(exported)
      const { markdown, log } = exported.result
      writeText(join(parsed.out!, 'GOVERNANCE.md'), markdown)
      writeText(join(parsed.out!, 'governance.json'), `${JSON.stringify(log, null, 2)}\n`)
      const gaps =
        log.summary.unowned + log.summary.unmitigated + log.summary.unconfirmed + log.summary.unreviewed
      return {
        exitCode: 0,
        stdout: `Wrote GOVERNANCE.md and governance.json (${log.summary.rows} row${
          log.summary.rows === 1 ? '' : 's'
        }, ${gaps} gap${gaps === 1 ? '' : 's'}) to ${parsed.out}\n`,
        stderr: '',
      }
    }
    if (kind === 'responsibility') {
      const exported = exportResponsibility(tool, projectionPath!)
      if (!exported.ok) return failedTool(exported)
      const { markdown, matrix } = exported.result
      writeText(join(parsed.out!, 'RESPONSIBILITY.md'), markdown)
      writeText(
        join(parsed.out!, 'responsibility.json'),
        `${JSON.stringify(matrix, null, 2)}\n`,
      )
      const gaps = matrix.summary.noAccountable + matrix.summary.noResponsible
      return {
        exitCode: 0,
        stdout:
          `Wrote RESPONSIBILITY.md and responsibility.json (${matrix.summary.rows} row${
            matrix.summary.rows === 1 ? '' : 's'
          }, ${gaps} gap${gaps === 1 ? '' : 's'}) to ${parsed.out}\n`,
        stderr: '',
      }
    }
    if (kind === 'graph') {
      const exported = exportGraph(tool)
      if (!exported.ok) return failedTool(exported)
      if (parsed.out === undefined) {
        return { exitCode: 0, stdout: exported.result.json, stderr: '' }
      }
      writeText(parsed.out, exported.result.json)
      return {
        exitCode: 0,
        stdout: `Wrote graph to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'xlsx') {
      const exported = exportWorkbook(tool, projectionPath!)
      if (!exported.ok) return failedTool(exported)
      const outPath = resolve(cwd, parsed.out!)
      mkdirSync(dirname(outPath), { recursive: true })
      writeFileSync(outPath, exported.result.bytes)
      return {
        exitCode: 0,
        stdout: `Wrote workbook to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'markdown' && parsed.changed === undefined) {
      const exported = exportMarkdown(tool, projectionPath!)
      if (!exported.ok) return failedTool(exported)
      if (parsed.out === undefined) {
        return { exitCode: 0, stdout: exported.result.markdown, stderr: '' }
      }
      writeText(parsed.out, exported.result.markdown)
      return {
        exitCode: 0,
        stdout: `Wrote markdown to ${parsed.out}\n`,
        stderr: '',
      }
    }

    if (kind === 'briefs' && parsed.changed === undefined) {
      const exported = exportBriefs(
        tool,
        projectionPath!,
        parsed.budget === undefined ? {} : { budget: parsed.budget },
      )
      if (!exported.ok) return failedTool(exported)
      for (const { path, markdown } of exported.result.files) {
        writeText(join(parsed.out!, path), markdown)
      }
      const count = exported.result.concepts
      return {
        exitCode: 0,
        stdout: `Wrote ${count} brief${count === 1 ? '' : 's'} and INDEX.md to ${parsed.out}\n`,
        stderr: '',
      }
    }

    // --changed: the review slice, seeded by what git says moved (ADR
    // 0065). The CLI's own, because it needs a repository; it renders and
    // writes through the same pieces the store-backed kinds use.
    const compilation = compileOf(tool)
    if (!compilation.ok) return failedTool(compilation)
    const { compiled } = compilation
    const documentIdByPath = new Map(
      compiled.graph.documents.map(({ id, source }) => [source, id]),
    )
    const derived = deriveChangedSubjects(
      cwd,
      parsed.changed!,
      workspace.documents.map((path) => ({
        ...readSource(tool, path),
        documentId: documentIdByPath.get(path) ?? path,
      })),
    )
    if (!derived.ok) {
      return { exitCode: 2, stdout: '', stderr: `${derived.message}\n` }
    }
    const endpoints = new Set<string>()
    for (const relationshipId of derived.changed.relationships) {
      const claim = compiled.graph.claims.find(
        (candidate) =>
          candidate.id === relationshipId && 'ref' in candidate.object,
      )
      if (claim !== undefined && 'ref' in claim.object) {
        endpoints.add(claim.subject)
        endpoints.add(claim.object.ref)
      }
    }
    const seeds = [
      ...new Set([...derived.changed.concepts, ...endpoints]),
    ].sort()
    const result = evaluateProjection(
      compiled.graph,
      {
        format: 'yarramate/projection/v1',
        id: 'review-slice',
        version: '0.0',
        query: { subjects: seeds, relationships: 'connected' },
        presentation: {
          title: `Review slice ${parsed.changed}`,
          description:
            `Connected neighbourhood of the subjects changed in ` +
            `${parsed.changed}.`,
        },
      },
      compiled.profileContext,
    )

    if (kind === 'markdown') {
      const rendered = renderProjectionMarkdown(result, compiled.profileContext)
      if (parsed.out === undefined) {
        return { exitCode: 0, stdout: rendered, stderr: '' }
      }
      writeText(parsed.out, rendered)
      return {
        exitCode: 0,
        stdout: `Wrote markdown to ${parsed.out}\n`,
        stderr: '',
      }
    }

    const briefs = briefsFromResult(
      compiled,
      result,
      parsed.budget === undefined ? {} : { budget: parsed.budget },
    )
    for (const { path, markdown } of briefs.files) {
      writeText(join(parsed.out!, path), markdown)
    }
    return {
      exitCode: 0,
      stdout: `Wrote ${briefs.concepts} brief${briefs.concepts === 1 ? '' : 's'} and INDEX.md to ${parsed.out}\n`,
      stderr: '',
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    return { exitCode: 2, stdout: '', stderr: `${message}\n` }
  }
}

import { fileURLToPath } from 'node:url'
import { defineConfig } from 'vite'

/**
 * Builds the browser application the session server serves, and nothing else.
 *
 * The output is self-contained by construction: relative asset URLs, flat
 * hashed file names the server's asset route admits, and no external origin,
 * because the page runs under a policy that allows only `'self'`.
 */
export default defineConfig({
  root: fileURLToPath(new URL('./src/visual-app/', import.meta.url)),
  base: './',
  // The layout worker (#490): `main.tsx` imports `elkjs/lib/elk-worker.min.js?worker`
  // and vite emits it as one more flat, hashed asset under `assets/`, which the
  // session server's asset route serves like the rest. As a module worker the
  // file is bundled the way the page is; the classic (iife) form built the
  // same file behind a warning about an export name it does not have.
  worker: { format: 'es' },
  build: {
    outDir: fileURLToPath(new URL('./dist/visual-app/', import.meta.url)),
    // Only this directory: `build:node` writes the rest of `dist`.
    emptyOutDir: true,
    assetsDir: 'assets',
    assetsInlineLimit: 0,
    modulePreload: { polyfill: false },
    target: 'es2022',
    sourcemap: false,
    reportCompressedSize: false,
    rollupOptions: {
      output: {
        entryFileNames: 'assets/[name]-[hash].js',
        chunkFileNames: 'assets/[name]-[hash].js',
        assetFileNames: 'assets/[name]-[hash][extname]',
      },
    },
  },
})

import { isDeclaredNonGoal } from './brief.js'
import type {
  Diagnostic,
  GraphClaim,
  ResolvedProfileContext,
  SemanticGraph,
  WorkspaceSource,
} from './compiler.js'
import { loadSourceDocument } from './source-document.js'
import { similarity } from './subject-identity.js'
import projectionSchema from '../schema/yarramate-projection.schema.json' with {
  type: 'json',
}

// `ajv/dist/2020.js` is CJS, and its default-export shape is resolved
// differently under this repo's two tsconfigs: NodeNext (root) sees the raw
// `module.exports` (needs `.default`), Bundler+esModuleInterop
// (tsconfig.visual.json) sees the already-unwrapped class. The `??` picks
// whichever arrived; the type is normalized the same way.
//
// A STATIC import, never `createRequire`. A bundler cannot follow
// `createRequire`, so loading Ajv that way put `(0, cre.createRequire)(...)`
// into the browser bundle, where it is not a function - which is exactly how
// this module became unimportable from a browser, and why the editor could
// only ever run behind a Node process (#252).


export type LifecycleStatus = 'planned' | 'current' | 'retired'

export interface ProjectionDefinition {
  readonly format: 'yarramate/projection/v1'
  readonly id: string
  readonly version: string
  readonly query: {
    readonly subjects?: readonly string[]
    /**
     * Pattern instances whose CONTENTS this query wants (#473, ADR 0144).
     *
     * Each id names an instance, and the facet selects that instance together
     * with everything the fold tree would draw inside it - the same closure
     * `presentation.fold: instances` collapses into one box, read through the
     * view's own `nesting`. A view that wanted the box wanted what is in it.
     *
     * This is the ONE facet that adds rather than narrows, and it is why
     * `subjects` and this are read as a single identity facet whose values
     * combine with OR (`docs/PROJECTIONS.md`). Every other field still ANDs
     * over the union: `instances` says which subjects are in play, and `kinds`
     * or `statuses` narrow that set the way they always did.
     *
     * Hand-listing the members instead is what this replaces, and the list goes
     * stale the moment the pattern binds another slot. The names here are the
     * instance, not its parts, so the view follows the model.
     */
    readonly instances?: readonly string[]
    /**
     * Subjects this query would otherwise select and the author has taken out
     * (#267, ADR 0122). A facet view states a rule, and every interesting rule
     * has an exception someone would rather state than abandon the rule for;
     * this is where that exception is written down instead of being the silent
     * absence a hand-enumerated list produces. Applied after every other facet
     * AND after `relationships: connected` expansion, so an excluded subject is
     * out whichever way it would have come back in.
     */
    readonly exclude?: readonly string[]
    readonly documents?: readonly string[]
    readonly kinds?: readonly string[]
    readonly layers?: readonly string[]
    readonly statuses?: readonly LifecycleStatus[]
    readonly excludeStatuses?: readonly LifecycleStatus[]
    readonly states?: readonly string[]
    readonly owners?: readonly string[]
    readonly constraints?: readonly string[]
    readonly relationshipKinds?: readonly string[]
    readonly kindMatching?: 'exact' | 'descendants'
    readonly relationships?: 'between' | 'connected' | 'none'
    readonly isolatedConcepts?: 'include' | 'exclude'
  }
  readonly presentation?: {
    readonly title?: string
    readonly description?: string
    /**
     * How this view arranges itself: `layered`, `routed`, `served-by` or
     * `bands`, a ladder where each keeps everything below it (ADR 0147). A
     * view that says nothing lays out `served-by`. The canvas offers the
     * choice on screen and a save writes what is in force.
     */
    readonly layout?: LayoutMode
    /**
     * Which way this view runs its layers. Read by the LikeC4 export for its
     * `autoLayout` and by the canvas for ELK's `elk.direction` (ADR 0121); a
     * view that says nothing runs `top-down`, which is what ArchiMate's layer
     * bands read as.
     */
    readonly direction?: LayoutDirection
    /**
     * The relationship kinds that draw as nesting in this view, in precedence
     * order (ADR 0101). Absent means `['composition']`, which is the behaviour
     * that shipped before a view could say; `[]` draws everything as a line.
     */
    readonly nesting?: readonly NestingKind[]
    /**
     * Whether this view draws pattern instances FOLDED by default (#473).
     *
     * `instances` collapses every instance to one node carrying its members;
     * `none`, the default, draws everything. A reader opens what they want, so
     * this says where to START rather than what may be seen — the same shape
     * `nesting` has, and for the same reason: a view is an opinion about a
     * first look, not a restriction.
     */
    readonly fold?: import('./fold-tree.js').FoldMode
    readonly showLifecycle?: boolean
    readonly showEvidence?: boolean
    readonly showOwnership?: boolean
    /**
     * Whether responsibility edges draw on the canvas (#557, ADR 0159). Off
     * when absent: the subject's properties read the letters either way.
     */
    readonly showResponsibility?: boolean
    /**
     * Whether an unnamed relationship is labelled with its reading - "serves",
     * "served by", "realizes" - or left to its line style and arrowhead
     * (ADR 0147). A named relationship keeps its name either way. On when
     * absent, which is what shipped.
     */
    readonly showKindLabels?: boolean
    /**
     * The folder this view files itself under in an editor's rail: a label the
     * author declares, nested with `/`, never the directory the projection
     * sits in (ADR 0104). The same word `yarramate/likec4-project/v1` uses for
     * the same thing.
     */
    readonly folder?: string
    /**
     * The notation this view draws in. `archimate` is the only one, and the
     * field is kept rather than dropped so a second notation has somewhere to
     * land - the same reason `layout` stayed an enum when `radial` and `force`
     * went (ADR 0086, ADR 0087).
     */
    readonly notation?: 'archimate'
  }
}

/**
 * A relationship kind a view may draw as nesting, and the default. Defined in
 * `./nesting.js`, which imports nothing, and re-exported here so a consumer
 * that already reads projection types keeps finding them. The browser should
 * still import them from there rather than from here: this module loads Ajv
 * and a schema, which is a great deal of bundle for one constant (ADR 0101).
 */
export { DEFAULT_NESTING, type NestingKind } from './nesting.js'
/**
 * Whether a view folds instances, and the default. Defined in `./fold-tree.js`,
 * which imports nothing, and re-exported here on the same terms as the nesting
 * vocabulary above (#473).
 */
export { DEFAULT_FOLD, type FoldMode } from './fold-tree.js'
import type { NestingKind } from './nesting.js'
import { DEFAULT_NESTING as NESTING_DEFAULT } from './nesting.js'
import { foldTree, type FoldMembership } from './fold-tree.js'
import { kindLabelOf } from './kind-label.js'
import { responsibilityLetterOf } from './responsibility-kinds.js'

/**
 * Which way a view runs, and the default. Split out for the same reason as the
 * nesting vocabulary above, and re-exported here on the same terms (ADR 0121).
 */
export { DEFAULT_DIRECTION, type LayoutDirection } from './layout-direction.js'
import type { LayoutDirection } from './layout-direction.js'
/**
 * How a view arranges itself, and the default. Same split, same terms
 * (ADR 0147).
 */
export { DEFAULT_LAYOUT, LAYOUT_MODES, type LayoutMode } from './layout-mode.js'
import type { LayoutMode } from './layout-mode.js'
import { validateProjection } from './schema-validation.js'

export type ProjectionQuery = ProjectionDefinition['query']

export interface ProjectionResult {
  readonly format: 'yarramate/projection-result/v1'
  readonly projection: string
  readonly presentation?: ProjectionDefinition['presentation']
  readonly documents: SemanticGraph['documents']
  readonly subjects: SemanticGraph['subjects']
  readonly claims: readonly GraphClaim[]
}

export type ProjectionLoadResult =
  | { readonly ok: true; readonly projection: ProjectionDefinition }
  | { readonly ok: false; readonly diagnostics: readonly Diagnostic[] }

export function loadProjection(source: WorkspaceSource): ProjectionLoadResult {
  const loaded = loadSourceDocument<ProjectionDefinition>(
    source,
    validateProjection,
    'Projection',
  )
  return loaded.ok
    ? { ok: true, projection: loaded.document.value }
    : loaded
}

export function canonicalProjection(
  projection: ProjectionDefinition,
): ProjectionDefinition {
  const query = projection.query
  const presentation = projection.presentation
  return {
    format: projection.format,
    id: projection.id,
    version: projection.version,
    query: {
      ...(query.subjects === undefined ? {} : { subjects: [...query.subjects].sort() }),
      ...(query.instances === undefined ? {} : { instances: [...query.instances].sort() }),
      ...(query.documents === undefined ? {} : { documents: [...query.documents].sort() }),
      ...(query.kinds === undefined ? {} : { kinds: [...query.kinds].sort() }),
      ...(query.layers === undefined ? {} : { layers: [...query.layers].sort() }),
      ...(query.statuses === undefined ? {} : { statuses: [...query.statuses].sort() }),
      ...(query.excludeStatuses === undefined ? {} : { excludeStatuses: [...query.excludeStatuses].sort() }),
      ...(query.states === undefined ? {} : { states: [...query.states].sort() }),
      ...(query.owners === undefined ? {} : { owners: [...query.owners].sort() }),
      ...(query.constraints === undefined ? {} : { constraints: [...query.constraints].sort() }),
      ...(query.relationshipKinds === undefined ? {} : { relationshipKinds: [...query.relationshipKinds].sort() }),
      ...(query.kindMatching === undefined ? {} : { kindMatching: query.kindMatching }),
      ...(query.relationships === undefined ? {} : { relationships: query.relationships }),
      ...(query.isolatedConcepts === undefined ? {} : { isolatedConcepts: query.isolatedConcepts }),
    },
    ...(presentation === undefined
      ? {}
      : {
          presentation: {
            ...(presentation.title === undefined ? {} : { title: presentation.title }),
            ...(presentation.description === undefined ? {} : { description: presentation.description }),
            ...(presentation.layout === undefined ? {} : { layout: presentation.layout }),
            ...(presentation.direction === undefined ? {} : { direction: presentation.direction }),
            ...(presentation.nesting === undefined ? {} : { nesting: presentation.nesting }),
            ...(presentation.fold === undefined ? {} : { fold: presentation.fold }),
            ...(presentation.showLifecycle === undefined ? {} : { showLifecycle: presentation.showLifecycle }),
            ...(presentation.showEvidence === undefined ? {} : { showEvidence: presentation.showEvidence }),
            ...(presentation.showOwnership === undefined ? {} : { showOwnership: presentation.showOwnership }),
            ...(presentation.showResponsibility === undefined ? {} : { showResponsibility: presentation.showResponsibility }),
            ...(presentation.showKindLabels === undefined ? {} : { showKindLabels: presentation.showKindLabels }),
            ...(presentation.notation === undefined ? {} : { notation: presentation.notation }),
          },
        }),
  }
}

const claimValue = (
  claims: readonly GraphClaim[],
  subject: string,
  predicate: string,
): string | undefined => {
  const object = claims.find(
    (claim) => claim.subject === subject && claim.predicate === predicate,
  )?.object
  return object !== undefined && 'value' in object ? object.value : undefined
}

const claimReference = (
  claims: readonly GraphClaim[],
  subject: string,
  predicate: string,
): string | undefined => {
  const object = claims.find(
    (claim) => claim.subject === subject && claim.predicate === predicate,
  )?.object
  return object !== undefined && 'ref' in object ? object.ref : undefined
}

const claimReferences = (
  claims: readonly GraphClaim[],
  subject: string,
  predicate: string,
): readonly string[] =>
  claims.flatMap((claim) =>
    claim.subject === subject &&
    claim.predicate === predicate &&
    'ref' in claim.object
      ? [claim.object.ref]
      : [],
  )

/**
 * A facet of a query, named the way the query names it. What
 * {@link explainProjection} reports as the reason a subject is not in a view.
 */
export type ConceptFacet =
  | 'exclude'
  | 'states'
  | 'subjects'
  | 'instances'
  | 'documents'
  | 'kinds'
  | 'layers'
  | 'statuses'
  | 'excludeStatuses'
  | 'owners'
  | 'constraints'

/** One subject a query dropped, and the facet that dropped it. */
export interface ProjectionExclusion {
  readonly id: string
  readonly facet: ConceptFacet
}

interface ConceptSelector {
  /** The facet that drops this concept, or `undefined` when the query keeps it. */
  readonly droppedBy: (id: string) => ConceptFacet | undefined
  readonly architectureStateIds: ReadonlySet<string>
  readonly participatesInSelectedState: (subject: string) => boolean
}

/**
 * How a query decides about concepts, built once and shared by the two things
 * that ask.
 *
 * `evaluateProjection` asks whether a subject is in; `explainProjection` asks
 * why one is out. They must never be able to disagree, which is why there is
 * one selector rather than a filter here and a reason-finder somewhere else.
 */
/**
 * Which subjects each named pattern instance holds, transitively.
 *
 * The SAME tree the canvas folds, computed from the same module over the same
 * inputs, because a view that names an instance must select exactly what the
 * box would have contained. Two implementations of "what is inside this
 * instance" would be two answers to one question, and the one the reader sees
 * is whichever they happened to open (rule: a test must go through the seam it
 * is testing - so must a second caller).
 *
 * Nesting comes from THIS view's `presentation.nesting`, not the default, for
 * the reason folding reads it too: containment is a property of the view, and a
 * view that nests on composition alone holds less than one that also nests on
 * assignment.
 *
 * Without `memberships` the closure is the named instances ALONE. That is a
 * degradation, not an answer, and it is why `check` refuses rather than
 * quietly returning a smaller view (#447, #450).
 */
export function instanceClosureOf(
  graph: SemanticGraph,
  projection: ProjectionDefinition,
  profileContext?: ResolvedProfileContext,
  memberships?: readonly FoldMembership[],
): ReadonlyMap<string, string> {
  const named = projection.query.instances
  const broughtInBy = new Map<string, string>()
  if (named === undefined || named.length === 0) return broughtInBy

  // Sorted so that an instance nested inside another named instance resolves to
  // a stable owner rather than to whichever the author typed first.
  const roots = [...named].sort()
  for (const root of roots) broughtInBy.set(root, root)
  if (memberships === undefined) return broughtInBy

  const kindOf = new Map<string, string>()
  for (const claim of graph.claims) {
    if (claim.predicate !== 'yarramate/concept/kind') continue
    if ('value' in claim.object) kindOf.set(claim.subject, claim.object.value)
  }

  const nodes = graph.subjects
    .filter(({ type }) => type === 'concept')
    .map(({ id }) => {
      const kind = kindOf.get(id) ?? ''
      return {
        id,
        kind,
        // The same reading `projectGraphForCanvas` gives `coreKindLabel`: the
        // nearest declared ancestor, labelled. Every rule in `foldTree` reads
        // this and never the authored kind (#473).
        coreKind: kindLabelOf(
          profileContext?.conceptKindLineages.get(kind)?.[0] ?? kind,
        ),
      }
    })

  const edges = graph.subjects
    .filter(({ type }) => type === 'relationship')
    .flatMap(({ id }) => {
      const claim = graph.claims.find((candidate) => candidate.id === id)
      if (claim === undefined || !('ref' in claim.object)) return []
      return [
        {
          id,
          kind: claim.predicate,
          from: claim.subject,
          to: claim.object.ref,
        },
      ]
    })

  const tree = foldTree({
    nodes,
    edges,
    memberships,
    nesting: projection.presentation?.nesting ?? NESTING_DEFAULT,
  })

  const childrenOf = new Map<string, string[]>()
  for (const [child, parent] of tree.parentOf) {
    const siblings = childrenOf.get(parent)
    if (siblings === undefined) childrenOf.set(parent, [child])
    else siblings.push(child)
  }

  // Transitive, because the box is: unfolding one reveals the folded rows
  // inside it, and a view naming the outer instance wants those too.
  for (const root of roots) {
    const queue = [root]
    while (queue.length > 0) {
      const current = queue.pop()!
      for (const child of childrenOf.get(current) ?? []) {
        if (broughtInBy.has(child)) continue
        broughtInBy.set(child, root)
        queue.push(child)
      }
    }
  }
  return broughtInBy
}

const conceptSelector = (
  graph: SemanticGraph,
  projection: ProjectionDefinition,
  profileContext?: ResolvedProfileContext,
  memberships?: readonly FoldMembership[],
): ConceptSelector => {
  // Computed once for the whole query rather than per subject: the fold tree is
  // a fact about the model and the view, not about the subject being judged.
  const instanceClosure = instanceClosureOf(
    graph,
    projection,
    profileContext,
    memberships,
  )
  const architectureStateIds = new Set(
    graph.claims
      .filter(({ predicate }) => predicate === 'yarramate/state/type')
      .map(({ subject }) => subject),
  )
  const selectedStateIds =
    projection.query.states === undefined
      ? undefined
      : projection.query.states.filter((state) =>
          architectureStateIds.has(state),
        )
  const participatesInSelectedState = (subject: string) => {
    if (selectedStateIds === undefined) return true
    if (selectedStateIds.length === 0) return false
    const presence = claimReferences(
      graph.claims,
      subject,
      'yarramate/state/present-in',
    )
    return (
      presence.length === 0 ||
      presence.some((state) => selectedStateIds.includes(state))
    )
  }
  // A subject id no longer carries the document that declared it, so the
  // `documents` selector reads provenance from the claim that declares the
  // concept's kind - the one claim every concept has, recorded in the document
  // that authored it. Built once: the alternative is a claim scan per subject
  // per query.
  const documentOfSubject = new Map<string, string>()
  for (const claim of graph.claims) {
    if (claim.predicate !== 'yarramate/concept/kind') continue
    const document = claim.source?.document
    if (typeof document === 'string') {
      documentOfSubject.set(claim.subject, document)
    }
  }

  return {
    architectureStateIds,
    participatesInSelectedState,
    droppedBy: (id: string): ConceptFacet | undefined => {
      const query = projection.query
      const documentId = documentOfSubject.get(id) ?? ''
      const kind = claimValue(graph.claims, id, 'yarramate/concept/kind')
      const status = claimValue(graph.claims, id, 'yarramate/lifecycle/status')
      const owner = claimReference(
        graph.claims,
        id,
        'yarramate/ownership/owner',
      )
      const constraints = claimReferences(
        graph.claims,
        id,
        'yarramate/constraint/requires',
      )
      const kindLayer =
        kind === undefined
          ? undefined
          : profileContext?.conceptKindLayers.get(kind)

      // Ordered the way a query declares its facets, so "the first reason" is
      // the one a reader would reach first themselves - except the explicit
      // exception, which outranks every rule: when someone has written the
      // subject down as taken out, that IS the first reason, whatever else
      // would also have dropped it (#267).
      if (query.exclude?.includes(id) === true) {
        return 'exclude'
      }
      if (
        query.states !== undefined &&
        (architectureStateIds.has(id) || !participatesInSelectedState(id))
      ) {
        return 'states'
      }
      // `subjects` and `instances` are ONE identity facet spelled two ways,
      // and values within a facet combine with OR - the rule
      // `docs/PROJECTIONS.md` already states for the values inside a list,
      // applied to the two lists that name the same thing. Naming a subject and
      // naming the instance that holds it are the same act of selection, so a
      // query carrying both selects the union and every other facet then ANDs
      // over it, exactly as before.
      //
      // The reported facet keeps `subjects` whenever the author wrote one, so
      // that no view which exists today changes the answer it gives the editor;
      // `instances` is reported only where it is the sole identity facet.
      if (query.subjects !== undefined || query.instances !== undefined) {
        if (
          query.subjects?.includes(id) !== true &&
          !instanceClosure.has(id)
        ) {
          return query.subjects === undefined ? 'instances' : 'subjects'
        }
      }
      if (
        query.documents !== undefined &&
        !query.documents.includes(documentId)
      ) {
        return 'documents'
      }
      if (
        query.kinds !== undefined &&
        !(
          kind !== undefined &&
          query.kinds.some(
            (selectedKind) =>
              selectedKind === kind ||
              (query.kindMatching === 'descendants' &&
                profileContext?.conceptKindLineages
                  .get(kind)
                  ?.includes(selectedKind) === true),
          )
        )
      ) {
        return 'kinds'
      }
      if (
        query.layers !== undefined &&
        !(kindLayer !== undefined && query.layers.includes(kindLayer))
      ) {
        return 'layers'
      }
      if (
        query.statuses !== undefined &&
        !(
          status !== undefined &&
          query.statuses.includes(status as LifecycleStatus)
        )
      ) {
        return 'statuses'
      }
      if (
        query.excludeStatuses !== undefined &&
        status !== undefined &&
        query.excludeStatuses.includes(status as LifecycleStatus)
      ) {
        return 'excludeStatuses'
      }
      if (
        query.owners !== undefined &&
        !(owner !== undefined && query.owners.includes(owner))
      ) {
        return 'owners'
      }
      if (
        query.constraints !== undefined &&
        !constraints.some((constraint) => query.constraints?.includes(constraint))
      ) {
        return 'constraints'
      }
      return undefined
    },
  }
}

/** A query facet naming something the model does not have. */
export interface UnmatchedSelector {
  readonly facet: string
  readonly value: string
  /** The closest name the facet does offer, when one is close enough to be a likely typo. */
  readonly nearest?: string
}

/** Below this, a suggestion is noise rather than a hint. */
const SUGGESTION_THRESHOLD = 0.6

/**
 * Every value in a projection query that names nothing.
 *
 * A projection is a DOCUMENT, and a query holds references the same way a
 * relationship does. YarraMate refuses a relationship pointing at a concept
 * that does not exist; it did not refuse a query naming a state that does not
 * exist, and the symptom is silent. `states: [target-stat]` selects no state,
 * which selects no subject, which exports a clean empty artifact with exit 0.
 * Someone hands that to a client.
 *
 * Checked at `check`, not at `export`, because the typo is in a file rather
 * than in an invocation: CI catches it, and every verb over the same
 * projection inherits the guard instead of each growing its own.
 *
 * ONLY FACETS WITH A CLOSED NAMESPACE ARE CHECKED. `statuses` and
 * `excludeStatuses` are schema enums, refused upstream before this runs.
 * Everything else names something: `owners` and `constraints` are REFS to
 * concepts, which the compiler itself proves by refusing an unresolved owner
 * with YM304, so their namespace is the subject list like `subjects`.
 *
 * Each namespace is derived the way the FILTER derives it, so the check cannot
 * drift from what it guards: `documents` reads the same provenance the
 * `documents` facet compares against, and `states` is the same
 * `yarramate/state/type` scan `conceptSelector` runs.
 *
 * A kind whose profile is not loaded is DORMANT rather than wrong, the same
 * distinction #351 drew for question catalogues, so the kind facets are
 * checked only when a profile context is present.
 *
 * An empty RESULT is not reported here and must not be. A query whose every
 * name resolves and which selects nothing is a real answer to a real question:
 * a target state nobody has populated yet is empty, correctly.
 */
export function unmatchedSelectors(
  graph: SemanticGraph,
  projection: ProjectionDefinition,
  profileContext?: ResolvedProfileContext,
): readonly UnmatchedSelector[] {
  const query = projection.query
  const found: UnmatchedSelector[] = []

  const check = (
    facet: string,
    values: readonly string[] | undefined,
    known: ReadonlySet<string>,
  ): void => {
    if (values === undefined) return
    for (const value of values) {
      if (known.has(value)) continue
      let nearest: string | undefined
      let best = 0
      for (const candidate of known) {
        const score = similarity(value, candidate)
        if (score > best) {
          best = score
          nearest = candidate
        }
      }
      found.push({
        facet,
        value,
        ...(nearest !== undefined && best >= SUGGESTION_THRESHOLD
          ? { nearest }
          : {}),
      })
    }
  }

  const subjectIds = new Set(graph.subjects.map(({ id }) => id))
  check('subjects', query.subjects, subjectIds)
  // Only whether the id names a subject at all. Whether that subject is a
  // pattern INSTANCE is a second question with a different answer and its own
  // diagnostic, because "you misspelled this" and "this is real but it is not
  // an instance" send an author to two different places.
  check('instances', query.instances, subjectIds)
  check('exclude', query.exclude, subjectIds)
  // Against the SUBJECT list rather than against owners currently in use: a
  // team that owns nothing yet is a real concept and selecting it is a real
  // question with an empty answer, which is exactly what must not be refused.
  check('owners', query.owners, subjectIds)
  check('constraints', query.constraints, subjectIds)

  // The same provenance `documents` filters on: a subject id no longer carries
  // the document that declared it, so both read it off the kind claim.
  const documentIds = new Set<string>()
  for (const claim of graph.claims) {
    if (claim.predicate !== 'yarramate/concept/kind') continue
    const document = claim.source?.document
    if (typeof document === 'string') documentIds.add(document)
  }
  check('documents', query.documents, documentIds)

  check(
    'states',
    query.states,
    new Set(
      graph.claims
        .filter(({ predicate }) => predicate === 'yarramate/state/type')
        .map(({ subject }) => subject),
    ),
  )

  if (profileContext !== undefined) {
    check('kinds', query.kinds, new Set(profileContext.conceptKindLineages.keys()))
    check(
      'relationshipKinds',
      query.relationshipKinds,
      new Set(profileContext.relationshipKindLineages.keys()),
    )
    check('layers', query.layers, new Set(profileContext.conceptKindLayers.values()))
  }

  return found
}

/**
 * Where a value sits in the projection source, so the diagnostic is clickable.
 * A query value appears once in a list item, and finding it by text is enough:
 * the alternative is threading a YAML CST through a check that only needs to
 * point at a line.
 */
const locate = (source: string, value: string): { line: number; column: number } => {
  const lines = source.split('\n')
  for (let index = 0; index < lines.length; index += 1) {
    const at = lines[index]!.indexOf(value)
    if (at >= 0) return { line: index + 1, column: at + 1 }
  }
  return { line: 1, column: 1 }
}

/**
 * {@link unmatchedSelectors} as diagnostics, built HERE rather than at each
 * caller so `check`, and anything that adopts this later, refuse in identical
 * words with an identical code.
 */
export function projectionReferenceDiagnostics(
  source: WorkspaceSource,
  projection: ProjectionDefinition,
  graph: SemanticGraph,
  profileContext?: ResolvedProfileContext,
  instances?: ReadonlySet<string>,
): readonly Diagnostic[] {
  const unmatched = unmatchedSelectors(graph, projection, profileContext).map(
    ({ facet, value, nearest }) => ({
      severity: 'error' as const,
      code: 'YM921',
      message:
        `Projection query \`${facet}\` names ${JSON.stringify(value)}, ` +
        'which this workspace does not have, so it can never match. ' +
        (nearest === undefined
          ? 'Check the spelling against the model.'
          : `Did you mean ${JSON.stringify(nearest)}?`),
      path: source.path,
      pointer: `/query/${facet}`,
      ...locate(source.source, value),
    }),
  )

  const named = projection.query.instances
  if (named === undefined) return unmatched

  // The facet cannot be resolved without knowing which subjects are instances,
  // and a caller that did not look is not the same as a workspace with none.
  // Answering anyway would return the instances alone, which is a SMALLER view
  // that reads exactly like a correct one - the failure #450 is about.
  if (instances === undefined) {
    return [
      ...unmatched,
      {
        severity: 'error' as const,
        code: 'YM923',
        message:
          'Projection query `instances` cannot be resolved here, because this ' +
          'check was given no pattern instances to resolve it against. ' +
          'Without them the facet would select each named instance alone and ' +
          'silently drop everything it holds.',
        path: source.path,
        pointer: '/query/instances',
        // The facet itself is what is wrong here, not any one name in it, so
        // point at the word `instances` rather than at an arbitrary member.
        ...locate(source.source, 'instances'),
      },
    ]
  }

  const knownIds = new Set(graph.subjects.map(({ id }) => id))
  return [
    ...unmatched,
    ...named
      // A name that resolves to nothing is already YM921's; saying it twice
      // would send the author looking for a second fault.
      .filter((value) => knownIds.has(value) && !instances.has(value))
      .map((value) => ({
        severity: 'error' as const,
        code: 'YM922',
        message:
          `Projection query \`instances\` names ${JSON.stringify(value)}, ` +
          'which this workspace has but which is not a pattern instance, so ' +
          'it holds nothing for the facet to select. Name it under ' +
          '`subjects` to select the subject itself.',
        path: source.path,
        pointer: '/query/instances',
        ...locate(source.source, value),
      })),
  ]
}

/**
 * Every concept a query leaves out, and the facet that left it out.
 *
 * The editor needs this to say why a subject is not on the canvas (#248): a
 * query that selects nothing, or that quietly drops the one subject the
 * reviewer was looking for, is otherwise indistinguishable from a model that
 * does not hold it. Relationships are not reported - they enter a view through
 * their endpoints rather than by matching a facet of their own, so "why" for a
 * relationship is a statement about the concepts it joins.
 *
 * Separate from `evaluateProjection` rather than a field on its result,
 * because `yarramate/projection-result/v1` is a published document with
 * `additionalProperties: false` and this is a question about a query rather
 * than part of what a projection IS.
 */
export function explainProjection(
  graph: SemanticGraph,
  projection: ProjectionDefinition,
  profileContext?: ResolvedProfileContext,
  memberships?: readonly FoldMembership[],
): readonly ProjectionExclusion[] {
  const { droppedBy } = conceptSelector(
    graph,
    projection,
    profileContext,
    memberships,
  )
  const exclusions: ProjectionExclusion[] = []
  for (const subject of graph.subjects) {
    if (subject.type !== 'concept') continue
    const facet = droppedBy(subject.id)
    if (facet !== undefined) exclusions.push({ id: subject.id, facet })
  }
  return exclusions
}

export function evaluateProjection(
  graph: SemanticGraph,
  projection: ProjectionDefinition,
  profileContext?: ResolvedProfileContext,
  memberships?: readonly FoldMembership[],
): ProjectionResult {
  const { droppedBy, architectureStateIds, participatesInSelectedState } =
    conceptSelector(graph, projection, profileContext, memberships)
  const endpointExcluded = (id: string): boolean => {
    // An exclusion is final (#267, ADR 0122). Dropping the subject from the
    // initial selection alone would not be: `relationships: connected` adds
    // the far end of every relationship it draws, so an excluded subject would
    // walk back in by the other end of a relationship to one that stayed.
    if (projection.query.exclude?.includes(id) === true) return true
    if (!participatesInSelectedState(id)) return true
    const status = claimValue(
      graph.claims,
      id,
      'yarramate/lifecycle/status',
    )
    return (
      status !== undefined &&
      projection.query.excludeStatuses?.includes(status as LifecycleStatus) ===
        true
    )
  }
  const initiallySelectedConceptIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'concept')
      .filter(({ id }) => droppedBy(id) === undefined)
      .map(({ id }) => id),
  )
  const selectedConceptIds = new Set(initiallySelectedConceptIds)

  const selectedRelationshipIds = new Set<string>()
  const relationshipMode = projection.query.relationships ?? 'between'
  if (relationshipMode !== 'none') {
    for (const subject of graph.subjects) {
      if (subject.type !== 'relationship') continue
      const relationship = graph.claims.find(
        (claim) => claim.id === subject.id,
      )

      const relationshipStatus = claimValue(
        graph.claims,
        subject.id,
        'yarramate/lifecycle/status',
      )
      if (
        // A relationship can be taken out by name too: `exclude` names
        // subjects, and a relationship is a subject.
        projection.query.exclude?.includes(subject.id) === true ||
        relationship === undefined ||
        !('ref' in relationship.object) ||
        (projection.query.excludeStatuses !== undefined &&
          relationshipStatus !== undefined &&
          projection.query.excludeStatuses.includes(
            relationshipStatus as LifecycleStatus,
          )) ||
        (projection.query.relationshipKinds !== undefined &&
          !projection.query.relationshipKinds.some(
            (selectedKind) =>
              selectedKind === relationship.predicate ||
              (projection.query.kindMatching === 'descendants' &&
                profileContext?.relationshipKindLineages
                  .get(relationship.predicate)
                  ?.includes(selectedKind) === true),
          )) ||
        !participatesInSelectedState(subject.id)
      ) {
        continue
      }
      const sourceSelected = initiallySelectedConceptIds.has(
        relationship.subject,
      )
      const targetSelected = initiallySelectedConceptIds.has(
        relationship.object.ref,
      )
      if (
        endpointExcluded(relationship.subject) ||
        endpointExcluded(relationship.object.ref)
      ) {
        continue
      }
      const bothSelected = sourceSelected && targetSelected
      // A responsibility edge does not carry the `connected` walk unless the
      // view shows responsibility (#563, ADR 0161). The canvas hides these
      // edges while the flag is off (ADR 0159), so walking one stood a person
      // in an application landscape with no line to anything: four of them on
      // the ApertureX reference. Between two subjects the query selected on
      // their own merits the edge is selected like any other, so a
      // whole-workspace evaluation, the workbook and the matrix builders keep
      // seeing every relationship; only the walk reads the flag. Read through
      // the lineage, so an adopter's subkind of `responsible` is held back
      // exactly as the shipped kind is.
      const carriesTheWalk =
        projection.presentation?.showResponsibility === true ||
        responsibilityLetterOf(
          profileContext?.relationshipKindLineages.get(relationship.predicate),
          relationship.predicate,
        ) === null
      if (
        bothSelected ||
        (relationshipMode === 'connected' &&
          carriesTheWalk &&
          (sourceSelected || targetSelected))
      ) {
        selectedRelationshipIds.add(subject.id)
        if (relationshipMode === 'connected') {
          selectedConceptIds.add(relationship.subject)
          selectedConceptIds.add(relationship.object.ref)
        }
      }
    }
  }
  if (projection.query.isolatedConcepts === 'exclude') {
    const relationshipEndpoints = new Set<string>()
    for (const relationshipId of selectedRelationshipIds) {
      const relationship = graph.claims.find(
        ({ id, object }) => id === relationshipId && 'ref' in object,
      )
      if (relationship !== undefined && 'ref' in relationship.object) {
        relationshipEndpoints.add(relationship.subject)
        relationshipEndpoints.add(relationship.object.ref)
      }
    }
    for (const conceptId of selectedConceptIds) {
      if (!relationshipEndpoints.has(conceptId)) {
        selectedConceptIds.delete(conceptId)
      }
    }
  }

  const selectedSubjectIds = new Set([
    ...selectedConceptIds,
    ...selectedRelationshipIds,
  ])
  const relationshipIds = new Set(
    graph.subjects
      .filter(({ type }) => type === 'relationship')
      .map(({ id }) => id),
  )
  const subjects = graph.subjects.filter(({ id }) => selectedSubjectIds.has(id))
  const claims = graph.claims.filter(
    (claim) =>
      (selectedConceptIds.has(claim.subject) &&
        !relationshipIds.has(claim.id)) ||
      selectedRelationshipIds.has(claim.subject) ||
      selectedRelationshipIds.has(claim.id),
  )
  const selectedDocuments = new Set(
    [...selectedConceptIds].map((id) => id.slice(0, id.indexOf('#'))),
  )

  return {
    format: 'yarramate/projection-result/v1',
    projection: `${projection.id}@${projection.version}`,
    ...(projection.presentation === undefined
      ? {}
      : {
          presentation: {
            ...(projection.presentation.title === undefined
              ? {}
              : { title: projection.presentation.title }),
            ...(projection.presentation.description === undefined
              ? {}
              : { description: projection.presentation.description }),
            ...(projection.presentation.layout === undefined
              ? {}
              : { layout: projection.presentation.layout }),
            ...(projection.presentation.direction === undefined
              ? {}
              : { direction: projection.presentation.direction }),
